/* 令和3年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r03.committeeSessions.push(...[{"id":"r03-20210302-3","meetingId":"r03-c-budget","date":"2021年3月2日","dateIso":"2021-03-02","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を182件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"西村副委員長","kind":"質問","question":"１人当たりの質問時間は、２０分のいずれかとし、１日につき１０分となります。残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"質問は、補正予算全体のことをお伺いします。当然、一概には言えないと思うのですけれども、おおむねで結構なので、執行率の見通しについて説明を求めました。","respondent":"品川財政課長","answer":"執行率ですが、毎年、大体９５％ぐらいを予定しています。新型コロナウイルス感染症の関係でできなかった部分がありますので、やはり前年と比べますと、少し執行率は落ちているです。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"背景はよく理解できますが、待ったなしのものに対して、どのような考えなのか。その点について説明を求めました。","respondent":"品川財政課長","answer":"緊急性の高いもの等については、今年度内にできるだけ行っていると認識しています。こういった部分については、翌年度しっかりとやっていくというような考えで進めていきたいと考えております。","id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"ぜひ鋭意努力をお願いします。その中で、事業計画どおりにできなかったことで支障などは生じなかったのか、その点だけ説明を求めました。","respondent":"品川財政課長","answer":"ただ、完成予定時期等も決めている中で延長している部分がありますので、地域の皆様の思いを少し達成できなかったという部分はあるかとは思います。これについても、来年度、とにかくできる環境等を早急に整えていきたいと考えています。","id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"把握するのは難しいかもしれませんけれども、品川区内にはマンションが２,２５３棟あります。その点について、何か分析などあれば教えてほしいと求めました。","respondent":"鷹箸保健予防課長、高山健康課長","answer":"よくお聞きしますと、エレベーターの階数ボタンを介してということでは、明確に我々は今のところ把握してございません。電話の受話器など、現在、ホームページにも公開しているところです。 ４１ページの感染症対策事業の充当先です。５月１２日に開設いたしましたＰＣＲ検査センターの運営に係る経費に、この予算を使用させていただいているところです。","id":"exchange-005"},{"speaker":"本多委員","kind":"質問・要望","question":"手が触れるというのは、非接触対応というのが求められてきている中、エレベーターにおけるその辺のことについてお聞かせほしいと求めました。その辺は難しいのかもしれないのですけれども、その辺の方向性についても、あれば説明を求めました。","respondent":"鷹箸保健予防課長","answer":"例えば手を洗って除去するとか、ステッカーが貼ってあることで安心するというよりも、外出から帰っていらっしゃったら確実に手洗いをしていただく。手袋なども重要ですが、まずは、外出先から帰られたら手洗いの確実な励行をお願いしたいと考えております。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"もし分かれば効果についても教えてください。分からなければ結構です。","respondent":"鷹箸保健予防課長","answer":"先ほどの内容について、もう少し詳しいご説明です。そのエレベーターであれば安心というわけには、なかなかいかないというのが現状と、私どもは考えております。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"区営住宅など、区の建物に対して何か講じることがあれば、その考えを教えてください。目をこすってしまうことが多いと思うのですが、それに対する、新型コロナウイルス感染症に関連して防止の注意喚起などあれば説明を求めました。","respondent":"鷹箸保健予防課長","answer":"まず３密を避けるという掲示はされている場合があると思うのですけれども、やはり外出から帰られたときの手洗いの励行を一番にお勧めするところです。花粉症については、ちょっと聞き取れなかったので、もう一度お願いします。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"積極的疫学調査が拡大されたということも伺っているのですが、これらの状況が品川区においてはどうなのか、お知らせほしいと求めました。今後の感染の見通しもお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"品川区でも対応を変更していたところですが、新たな対応をという通知が都から出されたことに伴いまして、品川区の方針も変更しています。感染拡大を防止するための、発症前２日間の詳しい聞き取りというものを、本日より再開しています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"引き続き、行政検査が行われるということを確認させていただきました。次に、ワクチン接種における積極的な情報提供についてお伺いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今の医療従事者に関してのご質問にお答えいたします。品川区には、３月８日、昭和大学にワクチンが３箱到着して、そこから接種が始まると聞いております。","id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"２３区全てのホームページを確認いたしましたが、全ての区にワクチンに関しての情報が掲載されておりましたが、体裁や見せ方などは様々でありました。コールセンターについてお伺いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"区は、予約、それから一般的な相談窓口をコールセンターに設置するものでございまして、専門的な副反応であったり、コロナワクチンのそもそもの元のお話に関しては、国ないし都で対応するというふうに示されております。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問","question":"聴覚障害の方の丁寧な周知をお願いしたいところですが、相談窓口のところに、区と厚生労働省のフリーダイヤルが一緒に掲載されております。より一層、丁寧な情報提供を望みますが、いかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今のご指摘です。今後、柔軟に対応してまいりまして、区民の皆様に十分に情報が行き渡るように対応してまいりたいと考えております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"それもあわせて要望させてほしいと求めました。こういう詐欺も起きているのだという情報もぜひ載せてほしいと求めましたが、まとめて、これらに関していかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"適切な情報を、情報過多にならないように、十分に分かりやすく掲載してまいりたいと考えております。準備状況についても、準備が整い次第、少しずつ、確定した情報を開示してまいりますので、引き続きよろしくお願いいたします。","id":"exchange-013"},{"speaker":"新妻委員","kind":"確認","question":"ちょっと話は変わりますが、これから感染者が増えても充足できる分の数があるということを確認させていただきました。何台追加されるのか、お分かりでしたらお知らせください。","respondent":"鷹箸保健予防課長","answer":"これまでのところ３７３台ですが、この後、たしか４０台の追加があり、合計約４００台、大体、常時保持し、必要な方にお配りするという方向性で進めているところです。","id":"exchange-014"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、品川区各会計補正予算、同説明書８１ページ、４款衛生費、地域医療連携について質問をいたします。この支援金の目的と、その具体的な内容について、まずご説明をお願いいたします。","respondent":"高山健康課長","answer":"今回の支援金についてご説明いたします。それから３点目の、発熱外来診療・検査医療機関支援金につきましては、そうした発熱外来を設置していただいている医療機関に対する支援金です。","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"意見","question":"今回の補正の初めの２つの支援金は、これらの医療機関を支援するものと理解しました。この支援金の意義について、品川区のお考えをご説明くださいとの意見を述べました。","respondent":"高山健康課長","answer":"新型コロナウイルス感染症患者受入医療機関支援金と、新型コロナウイルス感染症入院患者搬送協力支援金の実施の意義という点です。こうした国と東京都の実施を基本としつつも、品川区とともに新型コロナウイルス感染症への対応を着実なものとして進めていく上で。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"あわせて、このような発熱外来診療・検査医療機関に対する支援は、他の区でも行われているものなのでしょうか。あわせてご説明をお願いいたします。","respondent":"高山健康課長","answer":"そうした発熱外来を設置していただいている診療所の方々に対して、やはりこれまでの支援に加えた特別な支援というのが必要と考えているところです。近隣ですと、２３区内では荒川区などで取組があるということは承知しておりますが…","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"意見","question":"新型コロナウイルス感染症は、どんなに感染予防に注力しても、１００％、クラスターを防ぐことはできません。数だけが問題なのではなくて、要するに内容が問題だと思いますので、よろしくご説明をお願いいたしますとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"昨年が２か所、今年２か所の医療機関で、クラスター、５人以上の陽性者の方の発生を私どものほうで確認しております。お１人、実は陽性と分かったと、様々な背景を持つ患者が多いという現状です。","id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"質問","question":"成人も含め、健診・予防接種の昨年・一昨年との比較はいかがでしょうか。健診・予防接種の勧奨に、現在どのように品川区は取り組まれているか、ご説明をお願いいたします。","respondent":"鷹箸保健予防課長、高山健康課長","answer":"昨年７月以降、２か月と１歳のときの予診票を送るときに全員、子どもの予防接種と乳幼児健診をお知らせしております。昨年の４月は１５０件ということで、３倍もの里帰り先での予防接種の希望があったところで… 分かりやすい検診の必要性を訴えかけるホームページ等のリンクを張るなど、今後も継続的に検診を受ける必要性についてご説明申し上げております。その他、肺がん検診などにつきましては個別の勧奨通知を送るなどして…","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"新型コロナウイルス感染症だけにとらわれることなく、しかし新型コロナウイルス感染症に関しても徹底的な施策の遂行をお願いしたいと思います。ワクチンに関しては衛生費で、質問します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私からは、４１ページの感染症対策事業で、３月中に新たに実施することになったＰＣＲ検査について伺いたいと思います。もう一つ、８５ページの産業経済費で、品川区の家賃支援給付金について伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"今回、昨年末に１回目の検査をさせていただきまして、このたび、この３月、年度内いっぱいで、第２回目の検査を実施する予定でおります。それから、第１回目の検査の結果、約４,０００人に検査を実施いたしまして、５人の方の陽性が出ました。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ずっと要望させていただいたのが、１回されて、歓迎するところです。区としてどう捉え、どのような対策を取ってきたのか、また今後どんな対策が必要だと考えられているのかについても伺いたいと思います。","respondent":"宮尾高齢者福祉課長、鷹箸保健予防課長","answer":"介護サービスは、こういった状況下にあってもサービスの継続を求められている業種ですので、まずは予防対策を徹底することが大事だと考えています。大きく入所施設と通所施設が、それぞれ半々、半数ずつというところで捉えてあります。 死亡者数が増えていることに対しての保健所の対応ですが、対象者に対してのサービスの対応方法を徹底するなど、全てに丁寧に対応しています。クラスターが起きないようにということで、引き続き…","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"定期的な検査の実施を求めるということで、現場の声もお聞きしたのですが、安心につながるということで言われていました。その後も定期的な検査を行うように求めたいと思うのですが、いかがか尋ねました。","respondent":"鷹箸保健予防課長、宮尾高齢者福祉課長","answer":"高齢者施設で実施する計画をベースに、現在、取りまとめ中です。７月に行ったものは希望者がということでございましたけれども、今、調査をしているところになります。 それから、全体の調整等を品川ケア協議会に、前回と同様に予定しています。なお、４月以降につきましては、また感染状況等を見ながら判断していく必要があると考えているところです。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"再拡大につながっていきますし、医療・介護施設への定期的な検査は第一に行うべきだと、専門家の方々も言われております。ここまで社会的検査を行うようになったことを評価するとともに、さらに定期的に検査を行うよう改めて求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"６３ページ、８１ページ、一般会計補正予算全般についてお伺いいたします。なぜ特別区民税が増えたのか、法人住民税が減ったのかの理由も簡潔にお答えください。","respondent":"品川財政課長","answer":"基準日が令和２年１月１日となっておりまして、１月１日を見ますと、区民税については増額補正をしています。これはやはり法人住民税の国税化、それから新型コロナウイルス感染症の関係による企業業績等といったところが影響しまして、減額としています。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"基準日が令和２年１月１日で、令和３年度以降は、ご見解をお願いします。その点も簡潔に、区のご見解を説明を求めました。","respondent":"伊東税務課長、品川財政課長","answer":"令和元年中の状況を反映して令和２年度の課税という形になっていますので、その当時、やはり納税義務者は非常に増えてきたという事実があります。今後につきましては、当然、今度は昨年中の状況が反映されて賦課されますので… 区の政策としても、やはり重点的に行う政策について税は投入していく、歳出のほうは計上していきたいと考えております。来年度に回してもいいもの、そういったものについては…","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問・要望","question":"その点、引き続き区長会を通じて指摘していただきたいのですけれども、その点、ご見解がありましたらお答えください。財政調整基金積立金が約６５億６,７００万円計上させられておりますけれども、一気にこうした大きい額を計上した理由や意図をお知らせください。","respondent":"品川財政課長","answer":"当然２３区が一致して、それから東京都も含めて、国に声を上げていくということを引き続き続けていきたいと考えています。こういったところから、最終補正で翌年度に向けて積立てていくというものです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"引き続き健全財政に向けて、ここで一気に積み立てるという理解でよろしいのかということで、分かりました。では情報システム運営費についてお伺いしますけれども、ネットワーク・セキュリティや住民情報システムなどは、減額された理由は何か尋ねました。","respondent":"山本情報推進課長","answer":"入札で行ったのですけれども、入札の結果、価格の落差が出たというところで減額補正をしています。今年度、情報連携を行うためのサーバーの入替えを予定していたのですが、こちらを来年度に先送りしたため減額補正となっています。","id":"exchange-028"},{"speaker":"筒井委員","kind":"意見","question":"行政のデジタル化の推進など、関係して進んでいくと思いますので、そこはしっかり予算を手当てしてほしいと求めました。続けて８１ページの感染症予防費についてなのですけれども、こうした感染症予防費の事業について、所管としてご見解があればお知らせくださいとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"第３波まで経験してきた中で、まだ今後の課題はたくさんあるところですけれども、今できるところを１つずつ対応しています。皆様にお認めいただいた予算の中でできるところ、それから人員体制の充実も含めまして、今後も確実に対応していきたいと考えているところです。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"では、もう少し、予算としてはあればあるほど十分な、複雑なコロナ対策なので、本当にどう対策して、どこまで必要なのかという問題点はありますけれども、現場としては、かなり足りないぐらいというご認識でよろしいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"例えばワクチンに対する対応、あるいは医療機関に対する対応、また改めて考えていく必要があるかと思います。ただ、人がたくさんいるという部分については、必要なときに、庁内の応援も含めましてご対応いただけたことに感謝しています。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問","question":"一般会計補正予算全般についてお伺いいたしますけれども、今までお答えいただいたように、新型コロナウイルスの感染状況の悪化で続くかもしれない。その点、そうした準備というか、心積もりはあるのか尋ねました。","respondent":"品川財政課長","answer":"状況に応じて臨機応変に対応していくということが、来年度もやはり見込まれるのではないかと思います。必要な状況に応じて早急に予算等が立てられるような形で、来年度も頑張っていきたいと考えております。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問・要望","question":"それでもしっかりと区民のために臨機応変に、ぜひ予算立てや事業をしっかりと進めていってほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"９８ページ、７款教育費、２項１目学校管理費について伺います。今年１月２８日に厚生労働大臣は、扶養照会は義務ではないと国会答弁をしていますが、区の見解と対応状況を伺います。","respondent":"櫻木生活福祉課長","answer":"考えられます要因としましては、様々な支援等が一定の下支えをしているものと考えております。基本的に、ＤＶ等の世帯の自立を妨げる可能性があるところには、扶養照会は見合わせているような状況です。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"改めて扶養照会は必要ないと、区として示し、対応してほしいと求めますが、見解を伺います。ケースワーカーの増員が今後さらに求められると生活者ネットワークは考えますが、見解を伺います。","respondent":"櫻木生活福祉課長","answer":"健康管理支援事業は、受給者の方の健康状況を改善するための施策ということで、令和３年度につきましては健診受診率の向上に取り組んでいく予定です。積極的に勧奨を行うことで、受給者の健康増進、ひいては医療費の適正化等につながるように実施してまいりたいと考えています。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"見解を伺います。すまいるスクール職員など、子どもと密に接する職種もＰＣＲ検査の対象とすべきと求めていますが、現在の検討状況を伺います。","respondent":"宮尾高齢者福祉課長、鷹箸保健予防課長","answer":"年度内に１回、さらにもう１回、従事者に対して検査を実施するという予定で今動いております。この後ですけれども、区内の介護従事者に対する感染状況を見極めながら、適切に対応してまいりたいと考えているところです。 広く検査をするようにといった方針が打ち出されておりますが、お子さんにそれが波及したという事例は、まだ把握してございません。生徒・学生、あるいは生徒・学生を担当する職員等への検査については…","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"預け先がなくなり、働けなくなることが起きないよう、予防対策の一つとして積極的な区の姿勢を求めたいと思います。必要があるときであり、ＰＣＲ検査を行うときなのではないかと生活者ネットワークは考えますが、品川区教育委員会の見解を伺います。","respondent":"鷹箸保健予防課長","answer":"恒久的なその方の健康管理、あるいは周りへの感染拡大防止のために役立つものとは、現時点では考えておりません。お子さんでは重症化した方が少ない、現在のところ、お子さんたちにかかわる先生方への検査等は計画してございません。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"関連してワクチン接種について伺います。東京都からどのように配分されるのか、スケジュールなどがあればお知らせください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"接種計画は現在策定中ですので、まだ完成しておりません。東京都からのワクチンについての状況ですが、昨日問合せをいたしましたが、現時点ではお答えできないという回答がありました。","id":"exchange-037"},{"speaker":"田中委員","kind":"確認","question":"衛生管理の専門である保健所が、分かりやすい消毒の仕方の指標を示し、周知してほしいと考えますが、見解を伺います。そして、各所管の感染症対策ガイドラインについて確認しました。","respondent":"鷹箸保健予防課長、若生保育支援課長、廣田子ども育成課長","answer":"特に一昨年、保育所における感染症対策ガイドラインが改訂されましたので、それをきっかけに、対象者向けの講演会なども実施しています。機会を捉えて… 対応を行っているところですけれども、それ以外に独自に、ガイドラインというかマニュアルを作成しております。… すまいるスクールについてですけれども、すまいるスクールは学校の中にありますので、区立学校のガイドラインに準じた形で対応しています。…","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"見解を伺います。子どもや保護者への周知に大変有効だと考えますが、発行の目的と今後の活用、配布方法について伺います。","respondent":"廣田子ども育成課長","answer":"仮に緊急事態宣言が解除にならなかったとしても、春休みについては小学生の居場所がなくなるので、何らかの形で検討したいと考えているところです。今回、すまいるスクールの説明会のところで、今後またさらに配布を広げていこうと考えているところです。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"リーフレットは大変分かりやすいものでしたので、ぜひ、すまいるスクールの説明会にとどまらず、子どもが関わる施設全てで有効に活用されるよう求めたいと要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"出産１か月前から、妊産婦へのネウボラ面接の際に、該当の妊婦に対してサービスの概要をどのように説明していますでしょうか。妊娠したかもしれないという段階からの支援の拡充を要望いたしますが、区のお考えを説明を求めました。","respondent":"柏木品川保健センター所長","answer":"区のホームページにも紹介しておりますが、東京都では妊娠相談ほっとラインで支援を実施しています。オンライン相談の拡充については、まず妊婦面談を始めてから、今後の状況を見ながら検討したいと考えております。","id":"exchange-041"},{"speaker":"横山委員","kind":"提案","question":"パートナーシップへの関心が高まる時期でもありますので、夫婦などのパートナーシップを学べる講座の開催を提案いたしますが、いかがでしょうか。２点目に、生活保護費についてお伺いいたしますとの意見を述べました。","respondent":"柏木品川保健センター所長、櫻木生活福祉課長","answer":"児童センターでは、父親の子育て参加促進事業を実施し、パートナーの理解・協力が深められるようにいたしております。これらの機会を通じて、引き続き… 私からは、若年被害女性等の居住支援についてお答えします。いわゆる女性支援の枠組みや、就労支援等を通じて、自立をサポートするようなことになるかと考えています。","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"若年女性のための宿泊施設の確保に努めている民間支援団体への支援などを検討してはいかがでしょうか。今後の若年女性の居住支援について、区のお考えを説明を求めました。","respondent":"櫻木生活福祉課長","answer":"若年女性に向けた公設のネットカフェもしくはシェアハウスというものの設置、または民間支援団体に直接支援を行うということは考えておりませんが、そちらをご案内するとともに支援メニューの周知に努めてまいりたいと考えています。","id":"exchange-043"},{"speaker":"横山委員","kind":"意見","question":"東京都や国など、様々モデル事業などもあるやに聞いておりますので、そういったところを注視していただいて、ぜひご案内いただくようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"芹澤委員","kind":"質問","question":"私からは、８５ページ、収集運搬事業、あとは９５ページ、防災訓練経費についてお伺いします。初めに収集運搬事業について伺います。","respondent":"工藤品川区清掃事務所長","answer":"予算を組んでいる予定ですが、約２５日ですけれども、そちらのほうでコンパクトな形で収集体制を整えているです。家庭ごみの対策といたしましては、私どもも臨時的な車両を追加しまして、収集が滞らないような形で収集業務を行っているところです。","id":"exchange-045"},{"speaker":"芹澤委員","kind":"意見","question":"４月当時、エッセンシャルワーカーの中に清掃事業がなかなか入ってこなかったというのを大変残念に思っています。ここまでは結構、この清掃事業に対して、品川区からコロナ禍の中でどういった支援をされてきたのかを説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"やはり清掃事業、ごみ収集は、生活インフラに直結しているということで、どんな状況の中でも業務をしっかり円滑に進める必要があると思ってあります。私ども事務所といたしましては、無理のかからないような形で車両を配置しまして…","id":"exchange-046"},{"speaker":"芹澤委員","kind":"提案","question":"実際、ゼロにはやはりならないものですから、なかなかスポットライトの当たらない清掃事業者の皆さんに感謝の思いを込めてはいかがかご提案します。その辺については、品川区としての見解を、どうお考えなのかを説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"ご提案のイベントというところにつきましても、どういった形でできるかというところは今後詰めて、いろいろと検討してまいりたいと考えています。防護具に関しましては、今後も引き続き、どのような防具を使えば感染症対策をより一層できるかは検討してまいりたいと考えておりま…","id":"exchange-047"},{"speaker":"芹澤委員","kind":"質問","question":"続いて、防災訓練経費について伺います。総合防災訓練に関しては、今年度全て中止になって、一斉防災訓練、１２月のものが実施されたと伺っています。","respondent":"大森災害対策担当課長","answer":"自助・共助の能力を育成するために、１３の地域ごとに、災害時の初動対応に必要な初期消火や応急救護などの訓練を行っているところです。訓練の中止の判断ですが、各地区の防災協議会と綿密に確認を取りながら、協議会の判断等によって中止が決定されたという経緯です。","id":"exchange-048"},{"speaker":"芹澤委員","kind":"質問・要望","question":"区から防災の必要性をしっかりと説いて、ぜひやっていただきたいというような旨、働きかけは継続してやってほしいと求めました。視聴者数の確認というのも含めて、外れても、本年度の実績と評価を説明を求めました。","respondent":"大澤広報広聴課長","answer":"４０名の応募がありました。改めて防災を意識しました」というようなメッセージがございましたので、一定の効果はあったと考えております。","id":"exchange-049"},{"speaker":"芹澤委員","kind":"意見","question":"ラジオを配布したという経緯があったかと思いますので、グッズのこれからの検討は、ぜひ前向きに取り組んでほしいと求めました。グッズの考え方について、最後に説明を求めました。","respondent":"大澤広報広聴課長","answer":"今回、応募者の中で８割がテレビ、２割がラジオということで、内訳もある程度把握できたと思います。今後も機会を捉えて同様の取組をしてまいりたいと考えております。","id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１点目、医療連携推進費に計上されている３事業についてのご質問がありましたが、もう少し突っ込んでお伺いしたいと思います。１人１０万円でなどということを要望していたので、その際に厚生委員会で質問させていただいたときには５,４００万円が計上されていました。","respondent":"高山健康課長","answer":"当時の見込みとしまして、年度末までで５４０人と考えていたのですが、最終的には年度末の見込みを１,４２０人と見込ませていただいております。当初の見込みとしましては、５４０人で足るという見込みであったのですが、今回の増額に至った理由です。","id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"まだ７月、８月ということで、そのときは柔軟なご対応をお願いしたいと思います。いわゆる対象をどのようにお考えになっているのか説明を求めました。","respondent":"高山健康課長","answer":"新型コロナウイルス感染症入院患者搬送協力支援金につきましては、全てのということではなくて、コロナ患者の入院患者を受け入れてくださっている医療機関を対象として見据えているところです。","id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問","question":"その車を私も見せていただきました。それで、今回１,３２５万円という予算が計上されているのですけれども、この算定根拠は何なのか説明を求めました。","respondent":"高山健康課長","answer":"おおむね民間の救急搬送などを依頼いたしますと、１回当たりの搬送に１０万円程度の金額がかかってまいります。年度末の３月までの予測と合わせまして、２６５回分の搬送ということで、この金額を計上させていただいたものです。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それでお話も伺って、当然、国、そして東京都にも要望をお伝えさせていただきました。６５ページの喫煙マナーアップ啓発事業がマイナスになっていますが、それの、どの辺りがマイナスになったのかを一旦説明を求めました。","respondent":"黛生活安全担当課長","answer":"各地の夏祭りが中止になったため、うちわの作成を取りやめたので、減額補正をさせていただいたものです。","id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問","question":"質問なのですけれども、この指定された地区で路上喫煙をした場合、どのような強制力があるのかということが１点。もし入っているとしたら、なぜ店舗は灰皿を店先に出せるのか説明を求めました。","respondent":"黛生活安全担当課長","answer":"すずらん通りにつきましては、大井町の中の指定地区に含まれておりますので、ここで違反した場合については、過料の対象となると認識しております。そうした状況がある場合につきましては、生活安全サポート隊などが現地に赴きまして…","id":"exchange-055"},{"speaker":"あくつ委員","kind":"質問","question":"お店側もその辺のご事情をよく分かっていて、お店の敷地内、いわゆる私道内というのですか、私有地内の路上ぎりぎりのところに灰皿を置かれている。改正健康増進法ですか、ぜひ区もそこに呼びかけをお願いしたいと思うのですけれども、いかがか尋ねました。","respondent":"黛生活安全担当課長","answer":"商店街と連携した取組は恐らくこれから大変重要になってくるのだろうと認識、今、勉強させていただきました。商店街の方のお力もお借りしながら、たばこを吸う人、吸わない人がともに快適に過ごせるようなまちづくりに努めてまいりたいと考えております。","id":"exchange-056"},{"speaker":"あくつ委員","kind":"質問・要望","question":"最後に保健予防費から、関連なのですけれども、ワクチン接種記録システムについて伺います。接種記録を一元管理させていただきたいということで、接種会場で記録を取ってほしいということが、つい直近の自治体説明会で説明があったと。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"そこにも１回目接種が終わった方等々の登録をすることができるように、今、委員がご指摘のようなシステムを構築中です。転出・転入先でもマイナンバーを使って１回目接種・２回目接種の記録が分かることから、品川区では、現時点では進めてあります。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"よりきめ細かな支援ができるように、システムの見直しというものも、いろいろな項目で行っていただきたいと思うのですが、いかがでしょうか。それから３点目、衛生費ですが、これはコロナワクチンについて後ほどお伺いしたいと思いますので、お願いします。","respondent":"若生保育支援課長、櫻木生活福祉課長","answer":"各私立保育園、私立幼稚園、それから公設・民営も含めまして全て事業者に対しては支給は終了しております。個々の従事者に対しては、各事業者から２月中に支給されているということで認識しています。 今後はこの件に限らず、統計的なものについてどのような形で数値を捉えられるか、工夫をしてまいりたいと考えています。２月末に厚生労働省から通知が出ておりまして、虐待等の例示がされておりますので…","id":"exchange-058"},{"speaker":"あべ委員","kind":"質問","question":"それから、コロナワクチン接種についてお伺いします。品川区でも外部事業者に一括委託をするのか尋ねました。","respondent":"若生保育支援課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"新型コロナウイルス感染症に伴う保育従事者への応援金の個々の従事者への支給のサイン等の確認状況です。２月末までで各事業者宛てに報告を締め切って求めているものでして、まだ３月の初めということで… 品川区でも３月１日、昨日よりコールセンターを動かしてまいっております。金額は３,９００万円ほどを見込んでおりまして、今、仕様の細部を、現時点では詰めている最中です。","id":"exchange-059"},{"speaker":"あべ委員","kind":"質問","question":"仕様の細部を詰めているということですが、ではコールセンターは先行してスタートしたという理解でよろしいのでしょうか。事業者の選定プロセスも説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"契約は既に終わっておりまして、３,９００万円余ということで、随意契約で行っております。予備費から充用しております。","id":"exchange-060"},{"speaker":"あべ委員","kind":"質問","question":"委託先も伺ったのですけれども、言えるようだったら教えてください。随意契約は分かったのですけれども、例えば近隣の区であったら、品川区ではどうだったでしょうかということをお伺いしました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"３社からいろいろご提示いただきまして、現時点ではＪＴＢに委託しています。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"そうしたものを受け止める仕組み、これは区あるいは事業者も含めて仕組みをつくってほしいと求めましたが、いかがでしょうか。品川区としても、サービスを最初から高いレベルで提供するというやり方もあるのではないかと思いますけれども、そうしたお考えはいかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"４月中は、ワクチンが入ってくる量もまだ限られているということで、まずは医師会の医師・看護師で進めさせていただきたいと考えております。チャットボットにつきましては、順次、今のものをバージョンアップしながら進めていければと考えております。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"ある程度時間がたって、そんなにすぐではないと思いますけれども、かなり量が増えてきたときの医療従事者の確保はとても大切な問題だと思います。せっかくなので、前向きにこの時間を有効に使って検討してほしいと求めましたが、再度ご答弁をお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、渡部委員長","answer":"様々な方法を使いまして、区民の皆様がスムーズに接種できるように体制を構築してまいりたいと考えております。 進めます。次に、せお委員。","id":"exchange-063"},{"speaker":"せお委員","kind":"質問","question":"区固有教員の全体の人数のめどを３０人としているので、現在は２９人ですから、来年度は１人の採用等をしていくのでしょうか。それとも、例えばですが、１校に１人配置で、４６人から５０人程度を目指す予定もおありか尋ねました。","respondent":"工藤指導課長","answer":"区固有教員の採用についてですが、ご指摘いただきましたように、現在２９名、採用していますが、現状は３０人を目途に採用選考を行っていく予定ですので、次年度、実施されるときには、現在２９名ですので、１名の採用に関しての選考を行っていく予定です。","id":"exchange-064"},{"speaker":"せお委員","kind":"質問・要望","question":"ですから、区固有教員の採用を止めることなく、今後増やす方向で検討していただきたいと要望します。特に、現在は区固有教員が特別支援教育へどのように関わっているのか説明を求めました。","respondent":"工藤指導課長","answer":"特別支援教育に関しましても、現在、そのニーズは非常に高まっており、また、その理解も必要なところです。やはり区固有教員の中でも特別支援教育のそれぞれ能力の高い者については、特別支援学級での教育を中心に担わせるということも行ってあります。","id":"exchange-065"},{"speaker":"せお委員","kind":"意見","question":"そこで、現在、品川区において、特別支援教育コーディネーターは１校に何人程度の配置かお聞かせください。主に発達障害児への支援と、品川区としても位置づけているのか、その辺の考えを説明を求めました。","respondent":"矢部教育総合支援センター長","answer":"１点目、人数ですが、授業を持っている教員もおりますので、確実に１人または２人ということではありませんが、複数ということでお答えします。校内委員会を開いたときに、少しでも校内の子どもたちを応援するために…","id":"exchange-066"},{"speaker":"せお委員","kind":"質問・要望","question":"特別支援教育は、今ご答弁にありましたコーディネーターですが、幅広く支援が必要なお子さんを支えていただきたいと思っています。学校の状況に合わせて、特別支援教育コーディネーターの役職に就くということを検討してほしいと求めましたが、見解を説明を求めました。","respondent":"工藤指導課長","answer":"お尋ねの特別支援教育コーディネーターですが、現在、区固有教員の中でも特別支援教育コーディネーターを命ぜられて担っている者があります。特別支援教育の充実に関しましては、また特別支援教育コーディネーターを担う力を身につけるとともに、担っていなくても。","id":"exchange-067"},{"speaker":"せお委員","kind":"質問・要望","question":"特別支援教育コーディネーターだけに注力してほしいわけではなく、都の教員とはまた違った立場というのを有効に活用していただきたいと思っています。先ほどもご答弁がありましたが、特別支援学校教諭免許も、特に区固有教員には積極的に取得していただきたいと要望して質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"おくの委員","kind":"質問","question":"私からは、３８ページ、歳入の中の使用料、特に集会所・文化センター・中小企業センターなどの使用料について質問いたします。どのくらい定員数を減らしているのか、区民集会所、文化センター、中小企業センター、それぞれについてお教えください。","respondent":"川島地域活動課長、古巻文化観光課長、遠藤商業・ものづくり課長","answer":"区民集会所の新型コロナウイルス対策に伴う定員制限ですが、全ての区民集会所におきまして、定員を３分の１程度に制限しています。 つまりスポーツ施設とは若干違うところはありますけれども、基本的には区民集会所と同じ３分の１の定員ということで、お願いしています。 もともと余裕を持っている施設ですので、おおむね４平米当たり１人という形で、大体２分の１から３分の１という形になっております。","id":"exchange-069"},{"speaker":"おくの委員","kind":"質問","question":"利用する側の便益が削られているのに、支払う対価は同じというのでは、私はおかしいと思うのですが、いかがでしょうか。お伺いいたします。","respondent":"川島地域活動課長、古巻文化観光課長、遠藤商業・ものづくり課長","answer":"例年６０％ぐらいの部屋の使用が、１月末現在で４３.７％ぐらい、利用状況は例年より低い水準です。私どもの集会所の貸出しの考え方ですけれども… １人当たり幾らというような料金設定、ご不便はかけているところではありますが、それによって減額をするというような考え方には立っていないです。 区民集会所、文化センターと同様の考えでございまして、私どもにおいても、区民の方に丁寧に説明した上で、その金額で使っていただくです。","id":"exchange-070"},{"speaker":"おくの委員","kind":"質問","question":"今回、２回に分けて会を開くようにしたなどの声を、昨年のことですけれども伺いました。反しているのだと私は思いますけれども、この点はいかがか尋ねました。","respondent":"品川財政課長","answer":"部屋の広さ、得られる益は基本的には同じだということで、基本的に使用料は変えない方向で考えております。いろいろなところで区民に対しては、負担を軽減するような形で事業を進めておりますので、そういう形で今後も対応していきたいと考えています。","id":"exchange-071"},{"speaker":"おくの委員","kind":"質問","question":"利用者の皆さんは、それで部屋を決めているわけですから、非常に大きいと思います。このような港区の態度を見習うべきではないかと私は思いますけれども、いかがか尋ねました。","respondent":"品川財政課長","answer":"区の政策の方向としては、各区、いろいろな考え方があるかと思います。区もいろいろな給付金等、対応して、区民の皆様の不便がないように今後も対応していきたいと考えています。","id":"exchange-072"},{"speaker":"木村委員","kind":"質問","question":"６５ページの中ほどよりちょっと下にありますけれども、１億６,７６０万円余からですが、しながわ荘の記載がないのはどういう理由なのでしょうか。ご説明ください。","respondent":"川島地域活動課長","answer":"その下段の部分、宿泊費助成の減額補正につきましては、しながわ荘と光林荘、２つの保養所の宿泊費助成を表しております。分かりやすい記載、表記に努めてまいりたいと考えています。","id":"exchange-073"},{"speaker":"木村委員","kind":"質問・要望","question":"コロナ禍の中において、区民保養所は利用者が大きく落ち込んだとお聞きしております。新型コロナウイルス感染症の影響による利用者の大幅な減少について、現在のしながわ荘と光林荘の具体的な利用状況を教えてほしいと求めました。","respondent":"川島地域活動課長","answer":"利用率につきましても、１２月末までで比べますと、令和２年が２.１％、令和元年、前年度が６.３％、こちらも下回っているところです。なお、光林荘につきましては、このような形で利用が見込めないところですので、令和３年１月から３月末まで一時休館させていただいているで…","id":"exchange-074"},{"speaker":"木村委員","kind":"質問","question":"元気に、また満足して帰っていただくためには、区としてどのようなところに気を使っているのでしょうか。説明を求めました。","respondent":"川島地域活動課長","answer":"季節に応じた土産コーナーのレイアウトの変更や、装飾を変更したり、お食事につきましては２か月ごとに目玉メニューを変更しまして。様々な工夫を凝らして、運営事業者が頑張っているところですので、区としても引き続きこうした取組を後押ししていきたいと思ってあります。","id":"exchange-075"},{"speaker":"木村委員","kind":"質問・要望","question":"やはり、区民が保養所を利用する機会を確保していただくためにも、引き続き区民のための保養所の適切な運営をよろしくお願いしたいと思います。１,４１５万円余からですけれども、それでも、いつものような活動はできなかったということか尋ねました。","respondent":"黛生活安全担当課長","answer":"例年、コロナ禍の影響で夏祭りが中止となったということで、うちわの作成を取りやめた。このため、減額補正をしたところです。","id":"exchange-076"},{"speaker":"木村委員","kind":"質問","question":"現在はどのような状況でしょうか。新型コロナウイルス感染症の関係で事業ができないということが大きな原因なのか尋ねました。","respondent":"黛生活安全担当課長","answer":"少なからず、新型コロナウイルス感染症の影響があるのではないかと考えております。区といたしましては、生活安全サポート隊やシルバー人材センターの指導員などによる巡回指導を、粘り強く実施しています。","id":"exchange-077"},{"speaker":"木村委員","kind":"質問","question":"６７ページの一番上にあるコンテナ型等喫煙所設置、維持管理ですが、区内には以前はコンテナがありましたけれども、現在はこれを封鎖しているということでよろしいのか尋ねました。","respondent":"黛生活安全担当課長","answer":"区内には現在、９か所の指定喫煙所がございまして、そのうちの３か所につきまして閉鎖しています。","id":"exchange-078"},{"speaker":"木村委員","kind":"質問","question":"多くの通行人がたばこを吸うため、風向きによっては近所の住民が煙で大変迷惑しているということを聞いたことがありました。何か解決方法というのはないか尋ねました。","respondent":"黛生活安全担当課長","answer":"健康課と連携いたしまして、そこから流れ出る副流煙が周りの方の迷惑にならないように、灰皿の位置を移動するなどお願いしています。なかなか直ちに効果が出るものではありませんが、関係課と連携しながら、これからも地道にこうした活動を継続してまいりたいと考えております。","id":"exchange-079"},{"speaker":"木村委員","kind":"質問","question":"もちろん、区としては、たばこを勧めることはできませんが、行政としてどのようにお考えでしょうか。最後にお答えください。","respondent":"黛生活安全担当課長","answer":"まさにご指摘のような点もあります。たばこを吸う方と吸わない方、ともに快適に過ごすことのできるまちづくりに向けて、担当としてこれからも努力を続けてまいります。","id":"exchange-080"},{"speaker":"松本委員","kind":"質問","question":"私からは、６２ページ、総務運営費、間に合えば６５ページ、国際交流推進事業について伺います。中止してもかかった費用があるということだと思いますが、この２４万９,０００円の内訳をお願いいたします。","respondent":"立川総務課長","answer":"こちらは主に郵便代等の事務費です。","id":"exchange-081"},{"speaker":"松本委員","kind":"質問","question":"新年賀詞交歓会の中止なのですけれども、中止はいつ頃、誰の判断で決まったと理解すればよろしいでしょうか。お願いします。","respondent":"立川総務課長","answer":"新年賀詞交歓会は、一応、飲食等をしない方向で開催するということで考えておりましたけれども、１２月に、やはり感染拡大してまいりましたので、区長の判断で中止いたしました。","id":"exchange-082"},{"speaker":"松本委員","kind":"質問","question":"式典は中止されたけれども減額なしということになっているのですけれども、こちらはいいのでしょうか。区のウェブサイトを拝見すると、対象の新成人全員に記念品を送付する予定とのことですけれども、こちらの予算はどうなっているのか尋ねました。","respondent":"立川総務課長","answer":"その出演にあたり楽器の運搬代などの補助等を実施しておりますので、特に減額等はございません。そちらにつきましては予備費等を活用して実施、３月に配付を予定しています。","id":"exchange-083"},{"speaker":"松本委員","kind":"意見","question":"７日の時点で、どのようなメンバーというか、検討をした人たちがどのような議論をしたのか。いろいろな通知が来るということも想定すべきだと思うのですけれども、７日に開催するのだ、お願いいたしますとの意見を述べました。","respondent":"立川総務課長","answer":"７日までの国と都の資料では、朝令暮改みたいな形にはなってしまったのですけれども、いわゆるオンライン開催をいたしたところです。","id":"exchange-084"},{"speaker":"松本委員","kind":"確認","question":"伺う限りだと、かなり直前というか、本当にそのタイミングでいろいろと言ってきたのだろうというのは想定するところです。そちらに移行しなくていいのですかというようなことを、東京都もしくは国に確認するということは、７日よりも前の段階に行われたのか尋ねました。","respondent":"立川総務課長","answer":"品川区といたしましては、オンライン開催も延期もその時点では考えておりません。","id":"exchange-085"},{"speaker":"松本委員","kind":"質問・要望","question":"これは私も実際の会場での式典の中止のご連絡を受けた際にご要望させていただいた点でもあるのですけれども、今ご検討いただいていると思います。これも本当に、ぜひともお願いしたいところではあるのですが、そちらの検討状況をお伺いできればと思います。","respondent":"立川総務課長","answer":"コロナ禍が収まりつつあるとは言えないのですけれども、新年度、検討を進めてまいりたいと考えております。","id":"exchange-086"},{"speaker":"松本委員","kind":"質問・要望","question":"東京都が主体となるべきで、新型コロナウイルス感染症の影響で被害を被っているという状況ですから、重視していただきたいと思うところです。最後、ご答弁をお願いできればと思います。","respondent":"立川総務課長","answer":"新成人に対してどんなことができるかということにつきましては、今後とも検討していきたいと考えております。","id":"exchange-087"},{"speaker":"小芝委員","kind":"質問","question":"私からは、６５ページの歩行喫煙防止推進経費と、９９ページの教材教具等経費の中の学校ＩＣＴ活用経費についてお伺いいたします。１２億８,２５８万円余の減額ということで、去年の２回目の補正予算で計上されました、この減額になりました経緯を教えていただけますか尋ねました。","respondent":"篠田学務課長","answer":"実際の配備が２月中となり、正式に運用が始まったのは３月からということで、４か月分だったものが１か月分になったということ。通信料等が、機器本体も安く手に入ったということがございまして、こういった形での減額になったものです。","id":"exchange-088"},{"speaker":"小芝委員","kind":"確認","question":"走りながら考えるという新しい１年であった中で、ＧＩＧＡスクール構想における課題などについてお聞きしたいと思います。まず確認ですが、その端末が持ち運びが許されていたものかどうだったか、お伺いいたします。","respondent":"篠田学務課長","answer":"ＩＣＴ教育推進校における端末は、これまで、いわゆるＷｉｎｄｏｗｓのタブレットを配備してございました。基本的には学校で使うことがメインだったのですけれども、例えば持ち帰って宿題等でも使えるような形で運用してきたものです。","id":"exchange-089"},{"speaker":"小芝委員","kind":"質問","question":"フィルタリングを設けることで、かえって家庭学習の弊害になってしまっては本末転倒であります。先般の一般質問で取り上げました主権者教育の中で、情報の取捨選択をつける力という観点で質問した際には、区のお考えをお聞かせ願います。","respondent":"篠田学務課長","answer":"ただ、それも実際にこれから運用をしていく中で、学習に支障のないような形で対応してまいりたいと。これはすぐに外して、そういった形で事例が積み上がっていけば、柔軟な対応もこれからも考えていきたいと考えているところです。","id":"exchange-090"},{"speaker":"小芝委員","kind":"質問","question":"今、閲覧するサイトの範囲についてお聞きしていますが、今度は、端末でどの程度まで通信ができるのかというのも、また今後の課題であると思います。その辺りの通信料の制限やチェックはどのようにされていくのか、お考えをお聞かせ願います。","respondent":"篠田学務課長","answer":"トータルで２万数千台の容量を設定しているですので、使うお子さん、それぞれうまくシェアしながら使っていただけるのかと考えているところです。その辺、各学校を通じて、それぞれのお子さんの指導をしていただくというようなことで対応してまいりたいと考えているところです。","id":"exchange-091"},{"speaker":"小芝委員","kind":"質問","question":"ＩＣＴ教育の質問の最後になりますが、品川区のこれまでのＩＣＴ教育は、時代の先端を見据えた教育であったと思います。その方向性というものがあれば、教えてほしいと求めました。","respondent":"工藤指導課長","answer":"次の課題、自分の課題に取り組むなど、授業の中でも活用が進んでいるところがございました。今後、また全ての児童・生徒が、それぞれタブレットを使った学習の中で資質・能力を伸ばしていくような教育を推進していきたいと考えています。","id":"exchange-092"},{"speaker":"小芝委員","kind":"質問","question":"続きまして、６５ページの歩行喫煙防止推進経費のことをお聞きします。そういったところに住む地域住民の方々への周知というものがされておるのかどうか、お伺いいたします。","respondent":"黛生活安全担当課長","answer":"町会長などに概要の説明を行わせていただいたところでありますが、今、委員からご指摘いただいた点は大変重要だと認識しております。より具体的になった段階で、説明会に出られない方もおられると思いますので、しっかりと説明をして不安の解消に努めてまいりたいと考えておりま…","id":"exchange-093"},{"speaker":"小芝委員","kind":"質問","question":"約３分の１ほど使用できない中で、こういう状況ではありますが、コンテナ型喫煙所設置のめどというのは立っておるのでしょうか。お伺いいたします。","respondent":"黛生活安全担当課長","answer":"コロナ禍の中におきまして３密を生みまして、感染拡大防止のための新技術というものにも着目しつつ、慎重に計画を進めてまいりたいと考えているところです。","id":"exchange-094"},{"speaker":"小芝委員","kind":"質問・要望","question":"そういったこともぜひお考えいただいて、コンテナ型喫煙所の設置を進めてほしいと求めました。２３区の区役所でも、区役所の中で喫煙所を再開するめどはあるのかどうか、お伺いいたします。","respondent":"東野経理課長","answer":"区役所の屋外喫煙所ですが、新型コロナウイルス感染症対策として現在閉鎖しています。新型コロナウイルス感染症の収束に合わせて再開したいと考えているところでございまして、現在のところ、閉鎖は続けていきたいと考えております。","id":"exchange-095"},{"speaker":"小芝委員","kind":"質問","question":"３密を防ぐ喫煙所ということで、そういった密防止の取組を考えてほしいと求めましたが、ご所見をお伺いできればと思います。","respondent":"東野経理課長","answer":"かなり狭いような状況ですので、そういったアート的なものを描くようなスペースもないというような状況です。今後の対策につきましては、考えていきたいと考えております。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問・要望","question":"それから７７ページの子どもすこやか医療費助成事業、９７ページの、移動教室経費について伺いたいと思います。この１０年の間で大きく改善した部分があるかと思いますので、その成果についてお伺いしたい、お話しほしいと求めました。","respondent":"佐藤木密整備推進課長","answer":"不燃化１０年プロジェクトにつきましては、区では平成２５年度から助成に取り組んでおりまして、都と区が連携して実施してきております。目標とします不燃領域率７０％には達していないという状況もありますので、令和３年度以降５年間…","id":"exchange-097"},{"speaker":"塚本委員","kind":"質問・要望","question":"全部で１２地区になるのですか、５年間の延長と、新規でプラス３地区ということになりました。新しく加わった３地区は、最初にお伺いしたいのは、これまで木密連担地域改善事業が行われてきました。","respondent":"佐藤木密整備推進課長","answer":"今ご指摘いただきました、新しく追加する３地区のうちの西品川一丁目についてです。防災まちづくりにつきましては、地区計画の導入等も視野に入れまして、引き続き取り組んでまいりたいと考えております。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問・要望","question":"新しく加わった３地区も、他の９地区と同様に成果が出るように取組を強めていただきたいという思いですので、どうぞよろしくお願いしたいと思います。２億５,０００万円余の減額ということで、なぜそのようなことになったのか、どういう原因で減額という状況になったかを説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"４月から１１月までの支出額の実績値を前年度と比較しますと、マイナス２０％と減っておりますので、一番そこが大きいと考えています。こちらに関しましては、新型コロナウイルス感染症の影響で、それに伴って受診の件数も控えられているのではないかと思われております。","id":"exchange-099"},{"speaker":"塚本委員","kind":"意見","question":"令和３年度はどのような予算を組むかということがあるわけですけれども、しっかりとサービスが行き届くようにということでお願いしたいと思います。以上ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-100"},{"speaker":"松澤委員","kind":"質問","question":"私からは、６５ページ、歩行喫煙防止推進経費を質問します。あくつ委員への答弁で、物品のうちわのマイナス経費とお聞きしましたけれども、オリンピック・パラリンピックの臨時喫煙所も入っているのか尋ねました。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおり、オリンピック開催時のホッケー会場へのラストマイル上ですが、ここにコンテナ型の臨時喫煙所を設置する予定でございました。しかしながら、ご案内のとおり東京２０２０大会が延期になったため、この事業を中止させていただき…","id":"exchange-101"},{"speaker":"松澤委員","kind":"質問","question":"３密になるということで、多分、事業が停止されているというお話だったと思います。事業がストップという話ですけれども、これは新型コロナウイルス感染症が収まったら、コンテナ型の喫煙所は設置するという形でよろしいか尋ねました。","respondent":"黛生活安全担当課長","answer":"令和２年度中に設置予定であったコンテナ型の喫煙所につきましては、一時、改めまして令和２年度の計画を仕切り直したものになります。来年度の計画についても、新しい技術の導入なども検討して、計画を進めてまいりたいと考えております。","id":"exchange-102"},{"speaker":"松澤委員","kind":"質問","question":"先ほどお聞きしましたが、指定喫煙所９か所のうち３か所閉鎖しています。指定喫煙所が閉鎖しているところと、閉鎖していないところ、その違いを説明を求めました。","respondent":"黛生活安全担当課長","answer":"区内にあります９か所の指定喫煙所の中で、さらに、利用者と直近を通行する人の間に十分な距離を保つことのできないような喫煙所があります。現在も閉鎖を継続させていただいているところでございまして、そして大井町駅東口の喫煙所、大井町駅の城南信用金庫前の喫煙所です。","id":"exchange-103"},{"speaker":"松澤委員","kind":"質問","question":"喫煙所の中でも、やはり開けておくと副流煙問題が発生するところは禁止されているということです。やはり人の立つ位置を工夫して開放している喫煙所もあるのですけれども、品川区としてそのようようなやり方をするお考えはないのか尋ねました。","respondent":"黛生活安全担当課長","answer":"昨年の８月ですが、利用者が自然と距離を保てるような工夫をさせていただいたところ、これは一定の効果が認められているところです。今後、こうした工夫を、他の喫煙所に応用してまいりたいと考えているところです。","id":"exchange-104"},{"speaker":"松澤委員","kind":"質問","question":"品川区の喫煙所は、新型コロナウイルス感染症の一定の収束があれば開けるというお話でしたけれども、公園にも喫煙所があります。ちょっと所管が違うのですけれども、公園課はどういうふうに思っているのか教えていただけますか。","respondent":"高梨公園課長","answer":"公園における喫煙所・灰皿の状況ですが、昨年４月２１日より順次、公園については全ての喫煙所・灰皿を使用中止にしておるところです。撤去していくのか、再開するのかといったところについては、検討してまいりたいと考えているところです。","id":"exchange-105"},{"speaker":"松澤委員","kind":"意見","question":"２０２０年５月あたりから、喫煙所という検索ワードがどんどん増えていることが分かります。品川区は民間公共喫煙所助成というものを立ち上げていますが、この助成の内容はどんなものなのか、説明していただけますかとの意見を述べました。","respondent":"黛生活安全担当課長","answer":"令和３年４月を目途に、要綱を定め運用を始めてまいりたいと考えているところです。細部については現在、調整中となっておりますが、なるべく早くこちらの運用を始められるように準備を進めてまいります。","id":"exchange-106"},{"speaker":"松澤委員","kind":"意見","question":"そういう問題を解決する一助になる取組だと大変期待しております。商店街、地域と連携するのも１つかと思いますけれども、最後にお考えだけお願いいたしますとの意見を述べました。","respondent":"黛生活安全担当課長","answer":"委員からのご指摘、非常に参考になりました。まちの方々にも私どものほうから声をかけさせていただいて、こちらに応募していただくように、しっかりと取り組んでまいります。","id":"exchange-107"},{"speaker":"くにば委員","kind":"質問","question":"本日は、６６ページの文化観光費の都市型観光プラン推進事業、８５ページの商店街活性化事業費の商店街国際化推進事業についてお伺いします。時間があれば、５１ページのとうきょうママパパ応援事業補助金についても伺います。","respondent":"古巻文化観光課長","answer":"予算書でご説明させていただければ、時間等の短縮はございましたけれども、予定どおり実施させていただいているというような形です。来年度にまた延期していきたいと考えておりますし、できなかったものにつきましても、許される範囲で予算化をしているような状況です。","id":"exchange-108"},{"speaker":"くにば委員","kind":"意見","question":"これは将来的なインバウンド目的での品川区の長期目標として継続できたかと思うのですけれども、これに関して中止した理由を先ほどおっしゃいましたが、令和３年度の実施予定等を説明を求めました。","respondent":"古巻文化観光課長","answer":"特に東京２０２０大会への誘致ということでは、なかなかその事業目的が達成できないのかというところで、中止しているところです。来年度につきましては、できるだけそういったことを継続して、将来のインバウンド需要につなげていきたいと考えております。","id":"exchange-109"},{"speaker":"くにば委員","kind":"質問","question":"次に、８５ページの商店街国際化推進事業についてお伺いします。こちらは１,５６０万円の減額補正となっておりますけれども、こちらの詳細について説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"商店街が実施する多言語等の情報提供、それからイベント実施などにつきまして、支援する目的で実施しておりまして。残念ながら東京２０２０大会が延期という形になりましたので、令和２年度につきましては、全て減という形でさせていただいたところです。","id":"exchange-110"},{"speaker":"くにば委員","kind":"質問・要望","question":"次に、外国人観光客誘致に対しての方針についてお伺いします。文化観光課、商業・ものづくり課、それぞれの観点から見解を説明を求めました。","respondent":"古巻文化観光課長、遠藤商業・ものづくり課長","answer":"ワクチンの供給量も、なかなかまだ、日本は特に遅れている部分がありますので、状況を見極めながら判断せざるを得ないと考えているところです。１００％、なかなかまだ難しいのかというようなところはありますので… こちらの商店街国際化推進事業、平成２７年から外国人が増えるということで、ずっとやってきたところです。いずれは外国人の方が増えるのは、商店街の意見を聞きながら、こちらを進めていければと考えているところです。","id":"exchange-111"},{"speaker":"くにば委員","kind":"意見","question":"最後に、とうきょうママパパ応援事業補助金については、時間がないので民生費の款で触れたいと思います。以上ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-112"},{"speaker":"のだて委員","kind":"質問・要望","question":"総合支援資金を借りている方に、再申請が可能になったことを周知すべきですけれども、いかがでしょうか。以前に住居確保給付金を受けた方に連絡を取って、生活状況を聞きながら、再申請が可能になったことを周知すべきですが、いかがか尋ねました。","respondent":"櫻木生活福祉課長","answer":"基本的には品川区社会福祉協議会が実施されているもので、総合支援資金につきましては３,１７２件、合計して４,９８１件。困窮された際には暮らし・しごと応援センターにご相談いただくよう、徹底して案内しておりますので、またご相談いただけるものと考えております。","id":"exchange-113"},{"speaker":"のだて委員","kind":"質問・要望","question":"安心して申請できるよう、緊急小口資金・総合支援資金の延長・再延長の資金の返済免除の実施を国に求めるべきです。国が実施するまでは、社会福祉協議会を通して貸付けている人を対象に、区独自に給付に転換する制度をつくることを求めますが、いかがでしょう。","respondent":"櫻木生活福祉課長","answer":"先ほど申し上げました件数につきましては、２５億２,８５６万円というのは、総合支援資金の貸付分および延長分の合計の金額となります。緊急小口資金および総合支援資金について給付をですが、これは、国もしくは社会福祉協議会が適切に判断されると考えています。","id":"exchange-114"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ周知はしっかりやっていただきたいのと、返済免除について、ぜひ区として求めていただきたいのです。品川区として国に求めることが、生活困窮者への支援の後押しになるとは思わないのか、伺います。","respondent":"櫻木生活福祉課長","answer":"返済免除の件ですが、緊急小口資金については、住民税非課税世帯については一定の免除があるという旨が徹底されていると聞いております。総合支援資金につきましても、ただいま検討中ですので、その辺り、社会福祉協議会の判断を注視してまいりたいと考えています。","id":"exchange-115"},{"speaker":"のだて委員","kind":"提案","question":"例えば、家賃支援給付金をさらに増額し、国と同じ６か月支給に延長することを求めます。先ほど提案しました、緊急貸付金の給付への転換制度なども含めて、余った財源を活用してほしいと求めましたが、いかがでしょうとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"２月２６日までに助成が決定したという形になりますが、２,７４２件、１億２,２５５万円が決定しています。今後の家賃支援給付金の追加の給付につきましては、現段階では考えておりません。","id":"exchange-116"},{"speaker":"のだて委員","kind":"質問・要望","question":"次に、第４回定例会で取り上げさせていただいた、戸越公園駅周辺の再開発のために戸越小学校を公園にする計画について伺います。何か説明を受けているのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"委員の今ご指摘のありました、戸越公園駅の近くにあります戸越小学校の件ですが、まちづくり協議会は、当初から戸越公園と文庫の森を一体化するということで、地域資源を活用し、来訪者を増やし、商店街を回遊することで地域の活性化に努めたいと聞いてあります。","id":"exchange-117"},{"speaker":"こんの委員","kind":"質問・要望","question":"９９ページ、１０３ページ、職員給与費の中の通勤手当についてお伺いしたいと思います。どのようなお考えで実施されたのか、その辺をお伺いしたいのと、お聞かせほしいと求めました。","respondent":"大森災害対策担当課長","answer":"区民の方に内容についてしっかり認識していただくという広報効果等も狙いまして、ケーブルテレビ品川とラジオを見て聴いていただいた方に。非常に大切なことだと区としても認識しておりますので、これらの情報伝達の方法について、しっかりと周知してまいりたいと考えております。","id":"exchange-118"},{"speaker":"こんの委員","kind":"質問","question":"そうしたこともあわせてされると、もっと区民の方に、やはり最初ですから、そうしたことも必要ではなかったのかと思います。災害時または緊急時ですから、そうしたことも訓練のときには必要ではないかと思われますが、いかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"まず災害があったときに、区民の方に区長から直接呼びかける必要があるときに臨時スタジオを設置しますので、まずは臨時スタジオを設置したものです。いろいろ課題はあると思いますので、今後、より分かりやすい放送について検討してまいりたいと考えています。","id":"exchange-119"},{"speaker":"こんの委員","kind":"質問","question":"こうしたことがあるというところで、地上系、衛星系、有線放送も、停電や断線に起因する、そうしたことが起きやすいと言われてもおります。昨年の台風第１５号・第１９号では、そうした対応はどのようにされているのか、最後にお聞きします。","respondent":"大澤広報広聴課長","answer":"災害時は、ケーブルテレビ品川、ＦＭしながわ、ともに防災協定を結んでおりますので、どんなときにも区の情報を優先して放送していただけるということになっております。","id":"exchange-120"},{"speaker":"こんの委員","kind":"質問","question":"次は、就学援助についてお伺いしたいと思います。様々、援助金が執行されなかったのかと予想しておりますが、まず減額補正になった状況についてお聞きしたいと思います。","respondent":"篠田学務課長","answer":"一番大きいのは、移動教室というか、修学旅行です。こちらがほとんどできていないというようなことが、一番大きな理由となっています。","id":"exchange-121"},{"speaker":"こんの委員","kind":"質問","question":"次は申請受付について伺いたいと思いますけれども、翌年２月１日まで随時、受付可能となっております。家計が急変したというご家庭が多くあったのではないかと予測しているわけですが、そうした家庭への対応についてお尋ねしたいと思います。","respondent":"篠田学務課長","answer":"例年ですと、４月３０日は年度当初の締切りなのですけれども、今年度に関しましては５月末まで受付を延ばしたといった状況があります。直近の３か月の所得の状況等を見て、前年度の所得にとらわれることなく、認定は行っているような状況があります。","id":"exchange-122"},{"speaker":"こんの委員","kind":"確認","question":"直近３か月の所得で判断をしてくださっているということが確認できました。生活保護世帯以外の方、いわゆるこれから１年生に上がられるご家庭へのご案内や申請時期、支給時期などはどのようにされていますか尋ねました。","respondent":"篠田学務課長","answer":"新１年生の方へのご案内は、例年９月に、その中にご案内を一緒に同封して送らせていただいてあります。１０月１日から末日までの１か月間で申請をお受けいたしまして、その後、支給に関しましては２月の末までに支給するという形で対応しています。","id":"exchange-123"},{"speaker":"こんの委員","kind":"確認","question":"早い段階でのお知らせと、また支給の体制を取ってくださっているということが確認できました。今、現状、学校では、ポンプ式の学校、網に固形石けんを入れて対応している学校と、どんな状況か尋ねました。","respondent":"矢部教育総合支援センター長","answer":"委員のご指摘のとおり、ポンプ式に替える学校はとても多くあります。適宜、消毒液等も使いながら、衛生に努めております。","id":"exchange-124"},{"speaker":"こんの委員","kind":"質問・要望","question":"どうか、ポンプ式に順次、替えていくような考え方をお願いしたいと思います。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-125"},{"speaker":"西本委員","kind":"質問","question":"８１億円余、３１０億円余、どのような仕組みで積み上がってくるのでしょうか。現状把握はどのようにされているか尋ねました。","respondent":"品川財政課長、伊東税務課長","answer":"対応していこうというような考えで、来年度、進めてまいりたいと考えています。きっちりとした仕組みというか考え方というよりも、今年度、しながわ活力応援給付金の実施にあたり財政調整基金を活用させていただきました。 想定していた収納率よりは、良く推移してきているという状況ですので、結果的に増の補正になったです。現状で言えば、皆様の納税意識の高いというところでは、しっかり納税していただいているというようなところだと考えています。","id":"exchange-126"},{"speaker":"西本委員","kind":"質問・要望","question":"特別区民税なのですが、ある結構若い方、３０代なのでしょうか、意見交換をしたときに、非常に給料が下がって困ったという話が出ました。あまり使い切れていないのではないかというのがあって、その辺の関係性がどうなっているのか、今後の考え方を説明を求めました。","respondent":"伊東税務課長、品川財政課長","answer":"徴収猶予もしくは分割等々、相談に応じて、無理のない納付ということでお願いをしているという状況です。 支援金については、効率よく活用していきたいと考えております。","id":"exchange-127"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"５３ページ、密集住宅市街地整備促進事業補助金、６７ページ、鉄道会社と連携した情報発信事業から質問をさせてほしいと求めました。どういう選定をしたのかどうかということを、まず１つ、お聞きしたいと思います。","respondent":"佐藤木密整備推進課長","answer":"継続を訴えるとともに、それに続いて必要性があるというところで３地区について選定し、東京都と協議を行いました。それぞれ、不燃領域率や、都が実施しています地域危険度測定調査の結果を踏まえまして、都と協議を行って認められたです。","id":"exchange-128"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"それで、今後のスケジュール感なのですけれども、３月に要綱が改正されて、４月から新制度が開始されるということで、これは、新しく加わった３地区について、区政協力委員の方や地域への説明、どのように周知しているのかをお知らせほしいと求めました。","respondent":"佐藤木密整備推進課長","answer":"再度、３月下旬にかけて、新しい令和３年度のパンフレットを対象地域に対して個別に配布するということを予定しております。新年度に入りましても、引き続き周知に努め、制度の推進を図ってまいります。","id":"exchange-129"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは、マイナス補正で５７０万円余が計上されています。ほかに何か要因、詳しくではなくても構わないので、大体教えてほしいと求めました。","respondent":"古巻文化観光課長","answer":"鉄道会社と連携した情報発信の関係ですけれども、やはり東京２０２０大会の延期に伴う関連事業、東京モノレールの羽田空港駅に広告を出す。人の配置を取りやめたことによりまして、今回、この額の減額補正をする形の内容になってあります。","id":"exchange-130"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"かなり易しかった、オンラインだったので３０分ほどで終わってしまった、こういう書き込みというか声があります。今、現在どのぐらいのアクセスといいますか、お分かりになれば教えてほしいと求めました。","respondent":"古巻文化観光課長","answer":"私のところに届いている報告によりますとと、２月末現在ぐらいで約５,７００名の方が参加されているというふうな報告を受けているのですけれども、目標を５,０００名としておりましたので、ほぼ目標を達成できているような状況と認識しております。","id":"exchange-131"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひとも今後も継続してやってほしいと求めましたので、よろしくお願いいたします。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-132"},{"speaker":"湯澤委員","kind":"質問・要望","question":"そこで質問なのですけれども、現在、窓口が混雑しているのは、マイナンバーカード取得によるものが要因なのでしょうか。ある区民の方からは、マイナンバーカードを１０月に申し込んだけれども、役所から通知が来たのは年明けだったというお話も伺いました。","respondent":"木村戸籍住民課長","answer":"マイナンバーにつきましては、予約制の導入を昨年１１月から行いまして、いわゆるロビーの３密の状態は解消できているです。今は、そういう状況です。","id":"exchange-133"},{"speaker":"湯澤委員","kind":"質問","question":"職員を増やしたり、マイナンバーカードの処理は行っている状況であるようですけれども、職員の長時間勤務や労働負担は軽減されているのでしょうか。申請も、感染リスクを少しでも軽減させるために、申請会場を地域センターなどで行う予定はないのかお知らせください。","respondent":"木村戸籍住民課長","answer":"４月以降からですけれども、会計年度任用職員を大幅増員いたしまして、体制強化して対応していこうかというところを考えておるところです。それから、その他の施設についての拡大も、今、検討中です。","id":"exchange-134"},{"speaker":"湯澤委員","kind":"質問・要望","question":"処理が終わったときの普及率がどのくらいあるのか、お知らせほしいと求めました。区として普及率をいつまでにどれぐらい上げるかという目標・ビジョンがあれば、教えてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"具体的に検討には入っておりませんけれども、どういうやり方があるか、引き続き考えてまいりたいと思います。２年後までに国民全員へですので、先ほどご説明したとおり、考えてくださいという要望を出しておるところです。","id":"exchange-135"},{"speaker":"湯澤委員","kind":"質問・要望","question":"次に、新年賀詞交歓会について１点だけお伺いさせてほしいと求めました。は総合体育館のような大きな会場に変更するなどして開催をしていくべきだと考えていますが、どのようにお考えがあるのかをお知らせください。","respondent":"立川総務課長","answer":"新年賀詞交歓会の開催方法につきましては、様々ご提案がなされているところです。今後のあり方につきましては、新型コロナウイルス感染症の状況、また周辺自治体の動向等を踏まえ、適切に対応していきたいと考えております。","id":"exchange-136"},{"speaker":"湯澤委員","kind":"質問・要望","question":"来年は開催できるように、ぜひ準備をしてほしいと求めましたので、できる限りの準備をしてほしいと求めました。以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-137"},{"speaker":"中塚委員","kind":"質問","question":"私からは、最終補正全体の特徴についてと、８４ページ、産業経済費より、持続化給付金について伺いたいと思います。なぜこのような補正にしたのか、伺いたいと思います。","respondent":"品川財政課長","answer":"原則、上げるとなりますと、３月末までの執行で物事を進めなければいけないというところがあります。さすがに、例えば新規の項目を上げたりして準備等をやったとしても、なかなか３月までに予算執行が全部終わるかというところを考えますと。","id":"exchange-138"},{"speaker":"中塚委員","kind":"提案","question":"第１回定例会の本会議で複数の会派から、持続化給付金の再給付など国に求めるべきだと提案があったことを、品川区はどのように受け止めているのか。改めて、国にしっかり対策、財源を求めるべきだと思いますが、持続化給付金についていかがか尋ねました。","respondent":"品川財政課長、遠藤商業・ものづくり課長","answer":"まさに今、緊急事態宣言の中、急遽の対応というところは非常に求められているという部分はあるかと思います。こういった部分も活用しまして、３月までの対応については、やっていきたいと考えています。 持続化給付金につきましては、国のほうで一定、いろいろな支払方法や、あるいは緊急性などを考えて、事業構築されたものかと考えています。現在のところ、区としては特に要望等する考えはございません。","id":"exchange-139"},{"speaker":"中塚委員","kind":"質問・要望","question":"予備費を積み増して７億円あるというご説明でしたが、事業所や区民への直接支援を強めていただきたいと要望したいと思います。コロナ危機の下では、国にしっかりと求めていくという姿勢がとても重要だと思うのですけれども、改めていかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"持続化給付金の国への延長等の要望ですが、先ほどもご答弁したとおり、国に要望する考えはございません。私どもといたしましては、あるいは雇用関係につきましては雇用環境安定化事業助成金などを通じまして、地域の経済を守っていくという考えです。","id":"exchange-140"},{"speaker":"中塚委員","kind":"質問・要望","question":"持続化給付金など、必要な支援を国に対してしっかり求めること。９１億円も積立基金を積み増しておりますが、コロナ対策に直ちに充てるよう求めて、一般会計補正予算への反対意見としたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-141"},{"speaker":"若林委員","kind":"質問・要望","question":"この２つが、それから翌年度への繰越金というところに積み上がっていっているのか、基本的な確認をさせてほしいと求めました。繰越金は今回２０億円余、何でしょうか、その辺の感覚もあわせてお聞かせほしいと求めました。","respondent":"品川財政課長、宮尾高齢者福祉課長、中島防災課長、長尾建築課長、池田国保医療年金課長","answer":"やはり、もう今年度の見込みの中で、来年度予算にしっかりとやっていこうというような考え方というところが大きなところかとは思ってあります。来年… なかなかしっかりとした打合せの場を持つことが難しいということもございまして、今回、減額補正という形で提案を出させていただいたものです。しか… やはり避難行動要支援者の支援に関しましては地域の共助が重要なことから、平成２８年度から支援の補助をしております。… 今年度、工事を完了するのは１件の見込みとなっております。次年度につきましても…","id":"exchange-142"},{"speaker":"高橋（し）委員","kind":"質問","question":"第二戸越幹線のほうは、具体的な報告が建設委員会であったと伺っていますが、この減額について簡単にご説明をお願いします。それから、老朽化対策事業、下水道改修事業のほうもお願いします。","respondent":"松本河川下水道課長","answer":"排水施設建設事業および下水道改修事業の減額についてご説明をさせていただきたいと思います。工事の変更に伴い、工事を延長しましたことから、令和２年度に計画していた施工実績が上がらなかったことによる減額です。","id":"exchange-143"},{"speaker":"高橋（し）委員","kind":"質問","question":"第二戸越幹線のほうは、そういった工事に支障が出たということで、かなり影響が出ているとお聞きしています。９,５００万円とありますけれども、もともとは６億円以上の予算を組んでいましたけれども、その点はいかがか尋ねました。","respondent":"松本河川下水道課長","answer":"今年度も、そのうち１件が契約不調となりましたが、業者の影響をできるだけ少なくするような努力をさせていただいているところです。区民の生活を支える重要な事業ですので、コロナ禍ではありますが、引き続き必要な工事を適切に発注していきたいと考えています。","id":"exchange-144"},{"speaker":"高橋（し）委員","kind":"質問","question":"何というんですか、強さというか、そういうものでご指導をされているのでしょうか。コロナ禍の中で区内中小企業の方々のお仕事が減らないようにすることがとても大事だと思うのですが、その辺りはいかがか尋ねました。","respondent":"松本河川下水道課長","answer":"工事の発注につきましては仕様書の特記で、下請業者につきましては区内業者を極力使うことということで定めております。そこのところは把握できてございませんが、できるだけ区内業者を使うようなことで、仕様書の特記の中で記載させていただいているところです。","id":"exchange-145"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その点は要望でお願いします。先ほどの区内の中小企業たちの、いわゆる経済を回すというところに大きな影響があると思うのですが、その点はいかがか尋ねました。","respondent":"品川財政課長","answer":"年々少し負担行為が減っているですが、これは、工事のスケジュール的な部分等もございまして、そういった中での結果かと思います。コロナ禍によって工事もいろいろ見直しが入ると思いますので、区内企業を助けるためにも、こういった工事を積極的に行っていきたいと考えています。","id":"exchange-146"},{"speaker":"高橋（し）委員","kind":"質問","question":"積極的に推進しているといった部分もあり、自治体で何％ぐらい債務負担行為が行われているかということも、グラフ等で詳しく説明されています。こういった形で４月からすぐにということで、区内事業者向けという大きな意義を持っておりますので、その点の配慮についてはいかがか尋ねました。","respondent":"品川財政課長","answer":"コロナ禍によって区内事業所も大きく影響を受けているところがあるかと思います。ある種、仕事を多くしていくという意味での工事発注等も考えながら、そういった部分も総合的に考えながら進めていきたいと考えています。","id":"exchange-147"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"計画どおりになかなか進まなかったのでしょうか。今後の八潮地区の将来像についての方向性と、あとマスタープラン等の改定がもしあればお答えください。","respondent":"鈴木都市計画課長","answer":"そうしたアンケート結果の説明や、今年度、予定してございました。１０年、今、考えてあります。","id":"exchange-148"},{"speaker":"安藤委員","kind":"質問","question":"今年度の委託の中で、新年度でガイドラインをつくりたいということですが、懇談会をやらずに新しいガイドラインをつくるということなのでしょうか。それは、やはり住民参加という点では、ちょっとよろしくないのではないかと思うのですけれども、その辺の考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"再度ご説明しますが、区も、歩道の拡幅などといった様々なまちづくりを進めてあります。今現在、意見を頂きながら取りまとめていきたいという予定でおりましたので、来年度しっかりワークショップという形で検討を進めて。","id":"exchange-149"},{"speaker":"安藤委員","kind":"質問・要望","question":"少なくとも最低限の条件だと思いますので、その辺はしっかりと住民参加を貫いてほしいと求めました。以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-150"},{"speaker":"大倉委員","kind":"質問・要望","question":"今まで継続してやっているイベントに対しての予算は入っているのかという確認と、事業として、残り年数の考え方について教えてください。６８ページのスポーツ推進費とオリンピック・パラリンピック準備費ですが、延期になったり中止になったりして、その確認をさせてください。","respondent":"古巻文化観光課長、中元スポーツ推進課長、辻オリンピック・パラリンピック準備課長","answer":"今、なかなか地域の事業も予定どおりにできないというような状況が続いておりまして、実施できているもののほうが少ないという状況です。… ３つの計画の中で、区民スポーツ振興事業調査検討で、こちらは令和３年度に予算を再計上するものです。３月末の春休みの時期に予定しております親子でジュ… オリンピック・パラリンピック準備課の補正予算についてご説明申し上げます。１年前どうしようか会議や、オンラインホッケー教室、その他…","id":"exchange-151"},{"speaker":"大倉委員","kind":"質問","question":"しっかりお知らせをして周知していくということが大事かと思っていますので、そうした支援について教えてください。契約の関係もあるというようなお話も伺っておりますが、オンラインで実施したもの、できなかったもの等の課題について説明を求めました。","respondent":"古巻文化観光課長、中元スポーツ推進課長、辻オリンピック・パラリンピック準備課長","answer":"地域資源活性化事業補助の関係ですけれども、周知と、また準備経費等、支出せざるを得なかった部分というのは当然出てくるのかと思います。… ３月のイベントにつきましては、様々検討時間もございましたし、今回切り替えることができました。今後もこのような形で庁内で連携を取らせていただいて… リアルでやるものと全く同じにはできないと思うのです。区民に多くのものを伝えることを考えながら、いろいろな手段を使って…","id":"exchange-152"},{"speaker":"大倉委員","kind":"意見","question":"ぜひ柔軟に対応してほしいと求めました。東京２０２０大会なのですが、中止になるか、また延期になるかどうか分からないので、その辺も見据えてしっかり検討してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"６５ページ、オリンピック・パラリンピック啓発事業支援補助についてお聞きします。説明を求めました。","respondent":"品川財政課長、遠藤商業・ものづくり課長","answer":"区としては、令和２年度、中小企業等の支援等を続けてやってまいりました。引き続き、こういった制度を続けてやっていきたいと思ってあります。 区内の商店街への影響というような話でよろしいでしょうか。","id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"今、区民生活についてどうですかという、それをどのように把握されているか。区民生活についてどのように把握しておられるか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"私どものほうで中小企業の景況調査などをやっているところで、依然としてよくないような状況が続いているということは認識しております。２月のいわゆる緊急事態宣言などもありましたので、その辺について、まだ引き続き厳しいのかと認識しています。","id":"exchange-155"},{"speaker":"須貝委員","kind":"質問","question":"そこで、オリンピック・パラリンピック準備課にお聞きしますが、このような時期に東京２０２０大会は行うべきなのでしょうか。ちょっとご見解を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"世界で初めてのオリンピックとパラリンピックの延期ということで、今年行う予定になっております。皆様が安心して大会が開けるかというところで、今現在検討しているところですので、私どももそれに従いまして推進していくものです。","id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"２万人の方が来たら、やはり国内でも検査が必要ですから、どう見てもスタッフは足りないわけです。それはちょっとおかしくないか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"やはり８０％から９０％の方が、大会の開催はどうなのだというふうなご意見をお持ちというのは、私も重々承知しています。どうやって安全・安心な大会として開けるかというのを考えるのが、国の使命であると考えておりますし、今やることだと考えております。","id":"exchange-157"},{"speaker":"須貝委員","kind":"質問","question":"子どもたちにどうやってこれを説明するのですか。そんな教育を、教育委員会も子ども未来部も子ども育成課も、そういうふうにこれをやっていいんだということなのか尋ねました。","respondent":"工藤指導課長、廣田子ども育成課長","answer":"行われる場合には、安心・安全がもちろん第一ですが、その中で、大事な見るというアクションを行うというところで準備を進めているところです。そういった理念、大事な部分は、引き続き教育としてしっかり行っていきたいと考えています。 できる限りで東京２０２０大会をやるという想定で、東京２０２０大会ができる・できないにかかわらず、そちらは応援していきたいと考えています。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"そうではないのではないですか。関係ないですから、レガシーですから、子どもに見る教育が大事だかという見解になるんか尋ねました。","respondent":"山崎文化スポーツ振興部長","answer":"それと同時に、オリンピックの関係も、そうしたコロナ対策を十分に施した上で、一丸となって開催に向けて準備・検討しているです。そうしたものも含めて、やはり一体となって行う責務は品川区もありますので、それに向けて頑張っていく所存です。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問・要望","question":"だって、ワクチンを打っても、なくならないのですから、それでもやるのですか。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-160"},{"speaker":"石田（ち）委員","kind":"質問","question":"１１２ページの国民健康保険、そして１３２ページの後期高齢者医療、そして１４８ページの介護保険について伺いたいと思います。それで、この減免に使われた額は、どこから支出されているものなのか伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"７７人の方が該当いたしまして、保険料といたしましては、およそ１,０００万円ほどになります。国民健康保険のほうは１,６２２世帯になりまして、およそ４億円ほどが減額免除の対象となりまして、全て戻ってくる予定になってあります。","id":"exchange-161"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません。介護保険のほうも、減免件数と額を説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"今年度、介護保険につきましては減免ということで、今年６月から実施しています。年度内いっぱい、やらせていただく予定となっております。","id":"exchange-162"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そういったところを教えていただきたいのと、そして差押え数、それから国民健康保険や後期高齢者医療のところでは滞納処分の執行停止。こうした数、件数、そして収納率も、それぞれ教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長、池田国保医療年金課長","answer":"今年度、１２月末時点ですけれども、申請を３８０件頂いております。このうち要件に当てはまる方が３４４件ということで、対応させていただいているところです。 ４億円、５億円というような額になっていまして、ほぼ想定した範囲内での減額という形になっていると考えています。滞納繰越分についてですけれども、こちらは昨年より若干落ちているという状況で…","id":"exchange-163"},{"speaker":"石田（ち）委員","kind":"質問","question":"国民健康保険と後期高齢者医療の傷病手当も支給が実施されたと思うのですけれども、その件数と額も説明を求めました。","respondent":"池田国保医療年金課長","answer":"品川区では１人、後期高齢者の該当の方はお一人で、１５万２,０００円ほど支給したということになっています。それと、あと国民健康保険につきましては１２人の方に傷病手当金を支給させていただきまして、合計がおよそ１００万円ほどという形になっています。","id":"exchange-164"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この保険料の減免や、傷病手当もそうですけれど、今年の３月３１日が対象期限ということになっていると思うのです。広がるかもしれないという状況ですから、やはり延長していくということを求めたいと思うのですけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"６月末まで延長するというようなことで、今、通知がきたところです。コロナ減免につきましても、国のほうで少し検討するというようなことが、この間、新聞報道では載っておりましたところです。","id":"exchange-165"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして、この新型コロナウイルス感染症ですから、保険料は、私はもうそもそも引下げこそすべきだと思うのです。そういう中で、滞納者に対して延滞金を取るということをしてきたわけですけれども、令和２年の延滞金徴収の件数と額を説明を求めました。","respondent":"池田国保医療年金課長","answer":"徴収済みの延滞金につきましては７０件ほどで、未徴収の延滞金は２４８件ほどございまして、金額的には１０４万８,０００円です。今回は補正で、当初の金額よりも延滞金の額が少ないということで、マイナスの補正をお願いしています。","id":"exchange-166"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やるべきではないということを求めてきましたけれども、コロナ禍ですから、さらなる負担を住民に押しつけるのはやめるべきだと思います。伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"例えば１つ、戸越台特別養護老人ホームの中にも１つ入っているのですが、休止させていただいているところです。実績につきましては、今お調べしますので、少々お待ちください。","id":"exchange-167"},{"speaker":"石田（ち）委員","kind":"質問","question":"予算書に、社会福祉法人に８件と２件と書かれているのですけれど、そのことですか。１０戸程度という認識でいいか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"その理解で結構です。","id":"exchange-168"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"７,０００人いる従事者に対して、わずか１０戸で、家賃助成の事業をやっていますというのは、幾ら何でも少な過ぎる。処遇改善には全くつながらないのではないかと思うのですけれども、やはり家賃助成をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"家賃助成事業につきましては、東京都でも、一定の要件がありますが、各種事業を行っております。私どもは、必要に応じて、各施設、事業所に対して、そちらの制度も案内をしています。","id":"exchange-169"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そして介護保険は、コロナ禍で介護労働者の重要性が改めて認識される中で、抜本的な処遇改善が求められているのに、全く不十分です。よって、令和２年度補正予算の国民健康保険、後期高齢者医療、介護保険に反対の態度を表明して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-170"},{"speaker":"大沢委員","kind":"質問","question":"６４ページ、地域活動費、それに付随して補正予算についての考え方を伺いたいのが１点。それと８５ページ、商店街国際化、この２点について伺います。","respondent":"川島地域活動課長","answer":"６億２,５００万円余が差引き不用額の見込みというところで、それから、大きな工事でも必要性が低いと思われる部分については先送りした。ずっと出てきていると言われておりますけれども、これもコロナ禍の影響であると、感想を持っているところです。","id":"exchange-171"},{"speaker":"大沢委員","kind":"質問","question":"これは増額ということですから、事業に対する前向きな姿勢、前向きな流れの中での補正予算だと思いますが、今回についてはマイナスの補正。これについての先ほど来の話をいろいろと伺っていて、それについて私の意義が見いだせないことについての感想も、課長から聞きたいと。","respondent":"品川財政課長","answer":"そういう中で、区として対応していったところで結果として、このように執行残が出て、トータル的にはマイナス補正という形にはなってしまいました。やはり流れというところもあったかというところが、１つ感想としてはあります。","id":"exchange-172"},{"speaker":"大沢委員","kind":"質問","question":"補正は本当に必要だったのかどうか、ちょっと私は疑問に感じざるを得ないのですけれども、そこの部分はどういうふうにお考えか尋ねました。","respondent":"品川財政課長","answer":"この最終補正を抜いて６回、補正を行ってきたところでは、当然プラス補正という形で出しております。令和２年度、大きく考え方等も変わって、補正予算は必要であったということで思っております。","id":"exchange-173"},{"speaker":"大沢委員","kind":"質問・要望","question":"この非常事態宣言下の中、この進め方は、私はいかがなものかと思っていながら、こういう質問をさせていただきました。平成２８年ですか、非常に少ないサンプリングの中で結論を出しているというような表記があったのですけれども、そこについてお答えいただきたい。","respondent":"遠藤商業・ものづくり課長","answer":"平成２７年度から実施させていただきまして、そういう形で対応できるということで、ホームページなどでご紹介させていただいているところです。","id":"exchange-174"},{"speaker":"大沢委員","kind":"質問","question":"商店街の中の一番の悩みは、言葉が違うので外国の方とお話ができない。下北沢でしょうか、要はお客様をそちらのグローバル化された土地に引っ張っていってしまうわけですから、どのように処していくか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"商店街におきましては、あとは実際に住んでいらっしゃる方への対応といいますか、ふだん使うというところの２種類あるのかと思っているところです。商店街によって、現在、そういう面で各商店街に合った支援策などを使うような形でできればと考えているところです。","id":"exchange-175"},{"speaker":"大沢委員","kind":"質問・要望","question":"先ほどの平成２８年の報告書でも、やはり品川区を訪れるインバウンドというのは、ホテルの、ビジネス目的の方が多いと。区内在住者も数万人いるわけですから、そこらに向けた取組を一層加速していただきたいのですけれども、どのように思われますか。","respondent":"遠藤商業・ものづくり課長","answer":"商店街にとって、外国人の方も大事なお客様の一人だと考えています。それぞれ商店街に合った部分で、いろいろな形で研究させていただいて取り組めればと考えているところです。","id":"exchange-176"},{"speaker":"たけうち委員","kind":"質問","question":"約６億円近くマイナスというか、８４ページには載ってこないのですが、それはなぜなのか。水たまりが奥のほうにできてしまうということで、この間ちょっと通ったら直っていたような気がしたので、その辺の取組状況を説明を求めました。","respondent":"遠藤商業・ものづくり課長、川口交通安全担当課長","answer":"家賃支援給付金につきましては、執行がどうなるか見込めなかったところがありますので、今回は補正予算としては上程しなかったです。まだもう少し時間がありますので、かなりの金額が残額として残るのかという認識ではおります。 下神明駅の自転車等駐車場の維持工事関係です。舗装のかさ上げを実施し、本年の２月１８日に工事を完了しましたので、再開したところです。","id":"exchange-177"},{"speaker":"たけうち委員","kind":"質問","question":"ただもう、そのまま多分、何も載らずに、これは気づかなければこれに出てこないのだという話で終わるということですか。これは断定はできないかと思うのですけれども、それについての、今後何か検討されていることがあれば説明を求めました。","respondent":"遠藤商業・ものづくり課長、稲田土木管理課長","answer":"ところが結構、口約束に近いようなものであったりというところで、なかなか進まなかったと認識しております。逆に今回の品川区の家賃支援給付金、かなりの確率で… 私どももその後、検討いたしました。底地が東京都のものですので、東京都と今、調整をやっております。","id":"exchange-178"},{"speaker":"たけうち委員","kind":"質問","question":"本会議で新妻委員が質問したときに、家賃支援給付みたいに、そこに上乗せしていく。そこに対して区独自で何か支援ができないのかというところを、ぜひ検討してもらいたいのですが、ご答弁をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"今後の支援につきましても、様々なものが考えられるかと思います。広く使える新型コロナウイルス感染症対応特別助成などをしていますが、そのものも含めまして、またいろいろ考えさせていただきたいと思います。","id":"exchange-179"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから３８ページ、それから６５ページ、区民保養所経費等について伺いたいと思います。宿泊費助成が１,８８１万円余マイナスなんだけど、その１億４,８８０万円余のマイナスは、それをまずちょっと教えていただきます。","respondent":"品川財政課長、川島地域活動課長","answer":"積立金の見込額ですけれども、おおむねですけれども、７５０億円程度ということになってあります。見込額は幾らだというところは、また新たに状況によって基金の額が変化してくるというようなことは、考えられるところです。 区民保養所についてのご質問ですが、１点目の質問の１億７,０００万円余の減額補正につきましては、光林荘の照明工事のＬＥＤ化工事を先送りしたものになります。","id":"exchange-180"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"取れる部分はやっていかないと、我々の税金ですから。それがマイナスではないか尋ねました。","respondent":"川島地域活動課長","answer":"当該事業者が運営主体となって保養施設の管理運営を行うもので、指定管理者制度の運用という形ではございませんので、よろしくお願いいたします。","id":"exchange-181"},{"speaker":"石田（秀）委員","kind":"意見","question":"特記事項にないので、利用料の分も、両方もらえてしまうわけです。だから、その辺の契約の特記事項を含めて、指定管理の部分も、そうやって見直すなどという考えだけ、最後に聞きたいとの意見を述べました。","respondent":"佐藤企画調整課長","answer":"新型コロナウイルス感染症に対応する指定管理の規定の関係です。減収補填等も考えておりまして、今、調整をしています。","id":"exchange-182"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/309623?Template=document&Id=1126#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":130504,"voices":428}},{"id":"r03-20210303-3","meetingId":"r03-c-budget","date":"2021年3月3日","dateIso":"2021-03-03","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を181件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"私からは、９１ページ、新型コロナウイルスの予防接種事業について、全般的に何点かお伺いいたします。多くの職員の方が、新型コロナウイルス感染症のワクチン接種に関しては、この６名の方が行っていくということなのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今のご質問の国、都、区の区分について、改めてご説明します。区は、一般相談の対応と、住民の接種の勧奨、個別通知、あと、集団接種会場の確保、こういったものを主に行っております。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"確認","question":"民間委託に関してですけれども、会場運営と、あとはいわゆる接種券みたいなものの印刷とか発送とか、そこもあわせてやるのでしょうか。確認をお願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご説明いたします。委託内容ですが、印刷、それから郵送に関しましても委託業者のほうにお願いをしています。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"ウェルカムセンター原と八潮学園を含めて８会場ということでお話を伺いました。それとあと、印刷、郵送も民間に委託されるということで、これは、しながわ活力応援給付金のときも同じような形をとったのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ウェルカムセンター原、八潮学園に関しましては、使用時期について現在調整をしていますが、会場の確保は済んでいるです。それから接種券番号については、印刷業者のほうにお渡しをして、印刷をして郵送いただくという形になっております。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"しながわ活力応援給付金の際は、そういった対応ではなくて、役所内で対応したということか尋ねました。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"しながわ活力応援給付金につきましても、委託なのですが、コールセンター、事務センター、あと、申請書の印刷、封入等も全て委託して対応したです。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"何点か教えていただいて、あと、ほかに平時に使っていたりというところはどういう調整をされていらっしゃるのかお聞かせください。例えばファイザー製のものが来ても、その後どうなるか分からないというものなのだと思っていますけれども、説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"地域活動課のバックアップをいただきまして、会場の使用をストップという形とし、現在は利用ができるような状態になっております。それからワクチンに関しましては、ディープフリーザー等々の設置が徐々に進んでおりますが、それ以降のワクチンの流通体制に関しては現在未定です。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問・要望","question":"その場で、いわゆる解凍していくということになるのでしょうか。接種のスケジュールといいますか、例えば土日、夜間とか、どういった時間帯で接種をしていくものなのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"医師と看護師等と、執務時間等について詰めておりますので、現状では時間については定まっておりません。調整中です。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"意見","question":"来年の令和４年２月末までというのが国のスケジュールだったと思います。会場確保をして人的体制を整えたとすれば、２月末までに終わるのかということを聞きたいと思っていますので、見込み上限数を説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１会場については、現時点では、およそ３００名程度の接種ができることを見込んでおります。令和４年２月末までの接種完了を目指して、現在、体制を整えております。","id":"exchange-007"},{"speaker":"芹澤委員","kind":"質問","question":"これは８会場あって、前後は若干ありますけれども、ほぼ同じ３００名を目指してやっていらっしゃるということでよろしいでしょうか。その場合に、医師会が両方にかかわっていくのかと思うのですけれども、医師会とのやり取りというのはどのような形で行っていらっしゃるのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１セットというか、医師２名体制で行った場合ということで想定しており、その辺りは医師会の皆様と調整をする予定です。ＰＣＲ検査センターとの兼ね合いですが、その辺りも医師会の先生方と同時並行できるように、現在調整を進めております。","id":"exchange-008"},{"speaker":"芹澤委員","kind":"質問・要望","question":"財源について確認をさせてほしいと求めました。このコロナワクチン接種の全ての費用は国に出していただけるということでよろしいのでしょうか、説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"委員ご指摘のとおり、現時点で、国から真に必要な費用は全て負担するというふうに示されております。","id":"exchange-009"},{"speaker":"芹澤委員","kind":"確認","question":"国から満額もらえないのではないかというような報道があったのですけれども、品川区はそこはあまり関係ないというような認識でよろしいでしょうか。この従事者の範囲はどのように確認をしていくのか、説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"報道等はあるかもしれませんが、通知がまだ正式なものが来ておりませんので、その辺りを確認しながら進めてまいりたいというふうに考えております。その施設の施設長が、施設の従事者に証明書を発行して進めていくというところで…","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"保有台数は、一般質問でのご答弁では３７３台、昨日は東京都から追加支給で４０台あったと伺い、計４１３台と確認いたしました。それともう１点、一般質問で、再度利用ができるということをしっかり周知してほしいということを要望いたしました。","respondent":"鷹箸保健予防課長、櫻木生活福祉課長","answer":"パルスオキシメーターですが、昨日お伝えした数に加えまして、今年度末までに、都から１５０台貸与されることが予定されております。合わせて年度末までに５２３台保有する予定となっております。 住居確保給付金の再支給のご案内に関するご質問です。現在、周知が行き届きますように、必要なご案内をお送りするなど細やかな対応ができるよう準備を進めているところです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"確認","question":"品川区の接種方法の考え方ですが、今、６会場プラス２会場、８会場ということが確認されました。品川区の接種方法の考え方は、集団接種が基本であって、加えて、町の中の医療機関でもやっていくという、そういう考え方でよろしいのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご指摘のとおり、集団接種の会場をまず開設いたしまして、その後、病院等々での個別接種のほうに調整しながら進めていければというふうに考えております。","id":"exchange-012"},{"speaker":"新妻委員","kind":"確認","question":"平日であれば授業を受けている生徒がいて、その同じ場所で接種も行われるという、そういうイメージでよろしいのでしょうか。そのほかにも授業は進めながらやらなければいけない会場もあると思いますが、学校施設でありますので、その点だけ確認をさせてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ご指摘のとおり、動線については十分に注意してまいりますので、その辺りで混乱が起きないようにしてまいります。","id":"exchange-013"},{"speaker":"新妻委員","kind":"意見","question":"何かもっと早く情報があれば、区はこっちをやらなかったのにとか、そういうことも起こり得る現状があるのかなと思います。この情報交換といいますか、やり取りはどういう体制でされているのかということをお知らせくださいとの意見を述べました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"国、もしくは東京都とのやり取りですが、基本的にはメールによる通知で行っております。その他、こちらのほうで問合せ事項があれば、Ｑ＆Ａという形で、メールないしは電話で直接確認をするということで対応しております。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問・要望","question":"続きまして、母子保健衛生費に関連して、不妊治療助成についてお伺いいたします。確認をさせていただきたいのが、妊娠以降の支援というのはたくさんあると確認しているのですが、お伺いいたします。","respondent":"高山健康課長","answer":"通常ですと、保健センターなどで様々な相談事の中の１つとして保健師が対応するといったケースが１つ考えられるかと思います。そのほかに、妊娠支援のウェブサイトなどを開設するほか、そうした東京都の広域的な相談体制などもご活用いただければというふうに考えております。","id":"exchange-015"},{"speaker":"新妻委員","kind":"質問・要望","question":"男性だけに原因があるのは２４％、男女共に原因があるのは２４％で、男性に何かしらの原因があるのが４８％にも及んでいると。健康課なりにチラシを置くなり、ぜひ進めてほしいと求めましたが、いかがか尋ねました。","respondent":"高山健康課長","answer":"それは誤った認識ですので、そうした正しい認識が広く伝わりますよう、区民の方々が正しい認識に至るように努力してまいりたいと考えております。","id":"exchange-016"},{"speaker":"鈴木（博）委員","kind":"質問","question":"１４款都支出金、２目民生費補助金７節子ども家庭支援包括補助金に関連して、乳幼児健診について質問いたします。その経緯と、今回の措置について、まずご説明をお願いいたします。","respondent":"柏木品川保健センター所長","answer":"現在のコロナ禍において、保健センターで実施しております集団健診、または公共交通機関での移動等に不安をお持ちの保護者がおられます。医療機関での健診を希望する場合は、事前に管轄の保健センターにご連絡をいただき…","id":"exchange-017"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"コロナ流行下、集団健診に不安を持つご父兄の要望に応え、正に時宜にかなった適切な対応であると我が会派は高く評価いたします。４ヵ月児健康診査の内容と意義についてご説明をお願いします。","respondent":"柏木品川保健センター所長","answer":"生後３か月から４か月になると、首も座り、あやすと笑う、人によく反応するなど、乳児の社会性の発達が見られるようになります。発育や発達面の課題等を早期に把握し、その後の健やかな成長につなげていく上で重要な時期に当たると考えております。","id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"確認","question":"母親に心配事はないか、母親のメンタル状態は、などの母子関係や家庭の育児環境についても確認と相談を行う大切な機会となっています。昨年の新型コロナウイルス流行第２波以降の４ヵ月児健康診査の受診者数の推移についてお示しください。","respondent":"柏木品川保健センター所長","answer":"緊急事態宣言で健診が実施できなかったため、受診者数は２,３７７名、受診率は９２.１％になります。参考までに、昨年度の受診率は９５.８％です。","id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"４ヵ月児健診の集団健診、個別健診の併用が始まるにあたり、区としてそのメリットとデメリットをどのように捉えられているのでしょうか。それについてのご説明をお願いします。","respondent":"柏木品川保健センター所長","answer":"かかりつけ医や近くの医療機関で受診することができ、普段からなじみのある環境で保護者も子も安心して受診できることが挙げられます。デメリットとしては、保健センター等の関係機関への連絡のみとなり、要支援家庭への早期の支援につながりにくい可能性があることが挙げられま…","id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"その支援の体制あるいは具体的な集団健診の内容についてのご説明がもう少し詳しくあればよかったと参加者として思いました。区のご意見、ご見解はいかがか尋ねました。","respondent":"柏木品川保健センター所長","answer":"医療機関との連携です。ほかの６ヵ月児健診、９ヵ月児健診等においても、要支援家庭への早期の支援につなげられるようにしたいと考えております。","id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"意見","question":"推進ということが可能であること、それぞれにメリットがあり、それぞれを享受することが品川区民の健康と子育て支援に非常に大切なことだと考えます。今後、ご配慮、ご推進をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２０２０年度分は、２月１日、もう既に締切りとなりましたけれども、申請者数が何人か、学習塾、受験料、高校、大学、それぞれ伺いたいと思います。何％ぐらいが免除になっているのかについても伺います。","respondent":"櫻木生活福祉課長","answer":"受験生チャレンジ支援貸付事業です。貸付件数が１６６件、そのうち免除になったのが１５２件ということで、９１.６％の免除率です。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それであれば、この受験生チャレンジ支援貸付事業も、必要な証明書が無料で取れるようにぜひしていただきたいと思うのですが、いかがでしょうか。この手続も、申請書はネットで取ることができ、郵送できるようにならないでしょうかという、この２点をお願いしたいと思います。","respondent":"櫻木生活福祉課長","answer":"こちら、都のほうに提出する書類ですので、都のほうで調整していただくことになるのかなと考えています。ただし、最初の借入申込書以外のところにつきましては、郵送でのやり取りが、状況によっては対応できるです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、もしどうしても役所に来なければならないというのであれば、休日や夜間の開庁時に手続ができるようにということにはならないでしょうか。いかがか尋ねました。","respondent":"櫻木生活福祉課長","answer":"手数料の件ですが、使用料・手数料につきましては、区全体もしくは各所管がそれぞれで総合的に判断するものと認識しております。受験費用を借りるということをしっかりとご認識いただくということと、制度説明をしっかりするという意味で、一度はご来所いただいているです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最低でも１回だけということで、それ以外のところは郵送でも大丈夫だということで確認させてほしいと求めました。額も幾つもの区が１０万円にしておりますので、ぜひ対象と慰労金の額について拡充をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"高山健康課長","answer":"その配分に関しましては、病院の対応方針などに任せておりますので、その配分方針に従った形で有効に予算を使っていただければと考えております。増額に関しては現時点では考えてございません。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、品川区では看護師の確保というのはどうされるのか、見通しがあるのか伺いたいと思います。ワクチンの安全性や有効性、区としても情報公開については国任せにしない取組が必要だと思うのですが、いかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"２月１７日というのは医療従事者のことでございまして、ワクチンの供給量が見えたところで、ある程度完成ができるかというふうに見込んでおります。調整中ですので、こちらも皆様に行き渡るように、うまく調整して進めていきたいというふうに考えております。","id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"次が１３９ページの、民間企業が入っていますが、どういう形でお金は入ってくるのでしょうか。私が伺ったのは、たしか固定で毎年幾らと決まっていると思うのですが、それとも、売上げによって何％という形になっているのか、説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、濱中庁舎計画担当課長、三ッ橋子育て応援課長、東野経理課長、森住宅課長","answer":"４月１２日以降スタートができるようにというふうに国から指示も出ておりますので、その段階で医師が不足しないように、現在調整しております。… 基本計画等で、新庁舎の規模等が検討されていきまして、それに応じた適切な負担金をいただくという形でお願いしていくことになると考えています。 全国ひとり親世帯等調査ですけれども、５年に１回の調査でして、こちらは調査の歳入・歳出に関しましては、調査旅費、また事務費です。… こちらは総合庁舎、第２庁舎、中小企業センターを含めまして…","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"やろうと思えばできるという証明だと思うのですけれども、その辺についてもう１回お伺いします。ただ、ＰＣＲ検査センターでスペースを取っていますので、その辺はどうなったのか、お伺いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、三ッ橋子育て応援課長、東野経理課長、森住宅課長","answer":"もしくは休診時間、診療時間外の時間を使いまして、時間も含めて調整を進めているところです。今、調整をしてお願いができないかというところで働き… こちら全国的に国が調査の地区・世帯の割り振りを考えるのですけれども、そして就労など、ひとり親世帯の基礎調査となるものを調査するものです。… このため中に駐車してございました庁有車約１８台を外に駐車しています。そのため、昨年８月からなのですけれども、月約４５万円ほど減額いたしまし… 大規模３棟の区民住宅は、今、５２戸空いているです。…","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"全体を考えているということでぜひ教えていただきたいのですけれども、まず、これはまず何が一番問題があるのでしょうか。日本は１,０００兆円以上の借金があって、１人につき９００万円以上あるというような話が出ていますが、この辺についてどう考えるか説明を求めました。","respondent":"佐藤企画調整課長","answer":"２点目のご質問の金融緩和のことですが、いまだいろいろ課題があって達成できていないと捉えております。まずは区といたしまして、新しい長期基本計画をきっちりと進めていくというところで一生懸命頑張っていきたいと考えております。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"だから、何が言いたいかというと、企画調整するときに、少しでいいので頭へ入れておいていただきたいのは、介護離職させては駄目なのです。その辺についてはいかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"１点目の資産運用に関しましては、区としても重要な取組だと考えておりますので、会計管理室等と連携して確実に進めていきたいと考えております。委員ご案内の介護離職の件に関しましても、区として対応してまいります。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"そもそもワクチンの計画全体がまだまだいろいろ定まらない中で、どういう委託になっているのかということを伺いたいと思います。昨日、３社の中から選んで随契というふうに伺ったと思うのですが、どういうふうに優位性を認めてここを選ばれたのかについても伺いたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"それから、業者につきましては、３社の中で見積り等々、それから提案を受けまして内容を精査いたしました。２３区の中で全部で１０の区と契約を結ぶというところもあり、情報も含めて連携がとれるということと、こちらのほうで選定をしたです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"ほかの今までの実績の中から選ばれたということだと思うのですけれども、これはぜひうまくやってほしいという要望にしておきます。多いのではないでしょうかということで、この人数を担当していて十分なアウトリーチができているのか、伺いたいと思います。","respondent":"櫻木生活福祉課長","answer":"集中化、ＩＴ化等を通して、ケースワーカーの対人援助業務の余力を創出するような取組を進めてまいりたいと考えています。令和３年度につきましては、被保護者世帯の健診率の向上を進めてまいりたいと思っています。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"１０月の決算特別委員会では、保育の質の確保のために、東京都が補助金の要件としている財務情報の点検を求めて質問しました。保育園運営の事業計画などの提出は求めているのか伺いたいと思います。","respondent":"若生保育支援課長","answer":"事業者の保育に対する考え方ですとか財務状況等から適格性を見極め、問題がない場合、開設に向けて手続を進めていくということになってあります。事業内容ですとか保育事業者の考え方、こちらのほうで確認させていただいて…","id":"exchange-034"},{"speaker":"吉田委員","kind":"提案","question":"提案の中に、結果として財務情報の中にそれが表れてくるのだと思うのですけれども、その辺もちゃんと点検されているということでよろしいでしょうか。あたかも安定した事業とうたっているということに、とても違和感があるのですが、お考えを伺いたいと思いますとの意見を述べました。","respondent":"若生保育支援課長","answer":"１点目、これは新規でご提案があった場合は、区のほうで経営分析を必ず実施しております。そのような中で、そういった投資法人を立ち上げて、市場から出資を募るという手法は当然あり得ることであるということで認識しております。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"保育園運営の事業計画もよく確認していただきたいのと、やはり運営されているところについては、財務情報の点検を再度強く求めたいと思います。伺います。","respondent":"鷹箸保健予防課長","answer":"好評だったこともあり、今、追加で１,０００部を作成し、この後また配布する予定です。特に２４時間の対応という部分はかなり難しい部分もありますので、東京都が実施しております「こころの健康相談」の窓口などにアクセスしやすいよう。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"時間がなくなってしまったのですけれども、１１１ページの地域生活支援事業について、障害者総合支援法に基づく事業と考えます。３年間の障害児者計画について、この３年間にかける地域生活支援事業について、ぜひお示しください。","respondent":"松山障害者福祉課長","answer":"計画についての見込み数についてお答えいたします。地域生活支援事業は地域に応じまして積極的に今後も実施してまいりたいと考えています。","id":"exchange-037"},{"speaker":"松本委員","kind":"質問","question":"１３９ページ、１５７ページ、雑入について伺います。この上限額、負担金と補助金、どちらも上限があるのか、まず、この上限の考え方をお伺いできればと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"上限額が変更されたものは補助金のほうです。上限額が変更されて、上限額案ということで、先ほどご説明させていただいたとおりです。","id":"exchange-038"},{"speaker":"松本委員","kind":"質問","question":"それとも需用費とかも含めて、旅費とか謝金とかいろいろなものがあるのですけれども、ざっくりまとめて上限が示されているのでしょうか。どちらになるのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今のご質問です。こちらで把握しているのは上限額の８億５,０００万円という先ほどのもののみで、内訳については特に示されておりません。","id":"exchange-039"},{"speaker":"松本委員","kind":"質問","question":"今度は、調布駅前に６００m2規模のプレハブ会場を設けてというふうな、新たに施設をつくってというふうなものを掲げていました。いろいろ状況が変わったときのことに備えてお伺いしたいのですけれども、例えば、この辺りの考え方をお願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今のご質問も、真に必要な経費ということで含まれるということでＱ＆Ａのほうに示されておりました。","id":"exchange-040"},{"speaker":"松本委員","kind":"質問","question":"逆にこれは、この補助金の対象には入らないというふうな理解でよろしいのでしょうか。お願いします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"現時点で把握しているところでは含まれないというふうにこちらは理解をしております。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"次に、品川音頭の著作権料について伺っていきたいのですけれども、これ、予算額を拝見すると、使用料で１万円と極めて少額が計上されています。お願いいたします。","respondent":"大澤広報広聴課長","answer":"これは年度によってかなり差がありまして、平成３０年度は１万円少々だったのですが、１０万円を超える著作権が入ってきてあります。令和２年度は、ラジオ等で使われて５,０００円少しということで、令和３年度は１万円ということで計上しているものです。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"３競技応援キャラクターについては、過去の議事録を拝見すると、商標登録はされているというふうになっているかと思うのです。この辺りのキャラクターとか、あるいは今の品川音頭の著作権とかの知的財産の管理体制は、区全体としてはどういうふうになっているのか尋ねました。","respondent":"中山会計管理者","answer":"知的財産の管理体制ということですが、そのほかに商標登録ですとかロゴの登録とかもあわせまして、一応無形資産ということで会計管理室のほうで管理しているものです。","id":"exchange-043"},{"speaker":"松本委員","kind":"提案","question":"少しご提案をして終わりたいと思うのですけれども、あのくまモンがすごく面白いことをやっているのは、使用料を無料にしているのです。３競技応援キャラクターがありますけれども、どういうふうな扱いになっているのか、お尋ねしたいと思いますとの意見を述べました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"３競技応援キャラクターの取扱いについてです。ぜひたくさん使っていただきたいと思っているところです。","id":"exchange-044"},{"speaker":"塚本委員","kind":"確認","question":"昨日、品川区として、バーコードとかＯＣＲの形で接種券から自動で読み取るみたいなものに対応ができているのですかというところの確認が１点目です。この４万１,０００台という数から、８会場が少なくともあるわけですが、その２点をお伺いしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"国から幾つというのは、まだ現時点で、区のほうに幾つですというのはおりてきておりません。今後また調整が入るかもしれませんが、情報をこちらから取りにいって、十分過不足ないようにしていきたいというふうに考えております。","id":"exchange-045"},{"speaker":"塚本委員","kind":"意見","question":"そのときに、１回の入力で済ませられるのか。いかがなものかというふうに思うので、そういったところの懸念についての現状を、答えられる範囲でお願いしたいと思いますとの意見を述べました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"国のシステムから情報を取り出すことはできるようだということで聞いております。現在、調整して詰めて、効率がよい方法を考えていければというふうに考えております。","id":"exchange-046"},{"speaker":"塚本委員","kind":"質問","question":"ここについてのお考えを、今どういう状況なのかと、認識をお聞きしたいと思います。もう１点は、今年の１月か、それがなぜかという２点をお伺いします。","respondent":"山本情報推進課長、木村戸籍住民課長","answer":"昨年度ですと約５.８％、今年度は１月末時点で８.２％というところで、少しずつ伸びている状況です。引き続き周知等も図りながらコンビニ交付を伸ばしていきたいというふうに考えているところです。 実際に今年の１月からスタートをしておりまして、実際にもう交付を始めておるところでございまして、今後見ていきたいと思います。〔「漏れということはないのではないか」と呼ぶ者あり〕","id":"exchange-047"},{"speaker":"塚本委員","kind":"意見","question":"訂正は、後日しっかりお願いしたいと思います。こういったことに対しての区のお考え、お考えだけで結構ですので、ご答弁ほしいと求めました。","respondent":"山本情報推進課長","answer":"国が実際運用しているというところで、専用のネットワーク等を使いながら、コンビニと区役所間のデータのやり取り等を行っているところです。一部インターネット等を使うことになりますので、その辺がセキュリティ上の問題が少しあるのかなというふうに考えているところです。","id":"exchange-048"},{"speaker":"せお委員","kind":"質問・要望","question":"８９ページ、入院助産費、１１３ページ、放課後子ども教室等補助金、お時間ありましたら、１０１ページ、公園・児童遊園整備費をお伺いします。対象となる方には確実に提供していただきたいのですが、入院助産の周知方法に関しては、現在どのように行っているのか説明を求めました。","respondent":"三ッ橋子育て応援課長","answer":"平成３０年度は５件、平成３１年度（令和元年度）は７件、令和２年度は２件となっております。生活福祉課などが、実際にそれぞれの妊産婦と相談をしながら、こちらの子育て応援課に入院助産として引継ぎをしています。","id":"exchange-049"},{"speaker":"せお委員","kind":"提案","question":"出産育児一時金の４２万円を引いた２０万円以上の金額を出産の際に自費で出すというのは、一般的に考えても大変なことなのではないでしょうか。会派からは、代表質問において出産費用への品川区独自の出産育児一時金の上乗せ給付を提案しました。","respondent":"三ッ橋子育て応援課長","answer":"様々近隣区が実施している出産育児一時金の上乗せ事業ですが、区は、代表質問でもお答えいたしましたように、東京都などの動向を踏まえ、また、近隣区の状況も踏まえながら、区として研究してまいります。","id":"exchange-050"},{"speaker":"せお委員","kind":"質問・要望","question":"従来の縦割りではなく、一緒に考えて一緒に品川区をよりよくしていただきたいので、健康課や保健センター関連の方にもお残りいただきました。予算見積書の中の運営費に、この特別支援に関する補助金は含まれていますか尋ねました。","respondent":"廣田子ども育成課長","answer":"こちらの補助金については、区は委託料の中でまかなっている関係で、申請をしておりません。","id":"exchange-051"},{"speaker":"せお委員","kind":"質問・要望","question":"そちらの答弁が一般質問にはありませんでしたので、改めて全ての児童を受け入れるためのビジョンをお聞きしたいと思います。は４年生以降の受入れの拡大も検討していただきたいのですが、見解を説明を求めました。","respondent":"廣田子ども育成課長","answer":"今、安全確保面でも今現在は大変課題が多いと考えておりますので、現時点で解消するということは大変難しいというふうに思っているところです。今いるお子さんたちに関しても、どうしていくかというところが課題となっておりますので、その検討の中で考えていこうと思っています。","id":"exchange-052"},{"speaker":"せお委員","kind":"質問・要望","question":"このような考え方を取り入れていただいて、品川区の子育て支援が充実した心温まるものとなるよう要望します。そこで、北品川公園と大井坂下公園の改修においては、なぜ国庫補助金である防災・安全交付金の対象となるのか説明を求めました。","respondent":"高梨公園課長","answer":"１０１ページの公園・児童遊園整備費につきましては、防災・安全交付金という国費をいただいているものです。基本的には、このように考えておるところですが、内示額等の状況を見ながら対象とする公園については絞っているというような状況になってあります。","id":"exchange-053"},{"speaker":"せお委員","kind":"質問","question":"続きは土木費でお聞きしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"こんの委員","kind":"確認","question":"その点、まず確認させてください。妻の妊娠や出産、子育てに関して悩んでいる父親に対する支援が必要と考えますが、ご見解を説明を求めました。","respondent":"柏木品川保健センター所長","answer":"子育てまたは産前の悩みを持たれる父親への対応ですが、コロナ禍になりまして、夫婦で面談に来られる方が増えてきております。その中で父親のほうからの質問、あと、父親に対して、妊娠または出産後の内容、またはご相談については、そういう場を通じて、今、実施しています。","id":"exchange-055"},{"speaker":"こんの委員","kind":"質問","question":"それと同時に、ネウボラ相談の中では、両親の方が相談に来られているケースを今伺いました。交流を持つ、こうした支援が必要ではないかと考えるわけですけれども、いかがか尋ねました。","respondent":"柏木品川保健センター所長","answer":"現在、父親学級という形で実施をしておりまして、その中で区の補助事業と類似する内容が多く含まれてあります。父親同士が仲間づくりをすることによって、父親同士の悩みの共有ですとか、情報共有を進めているところです。","id":"exchange-056"},{"speaker":"こんの委員","kind":"質問","question":"今お答えくださったところは、国の予算も使って今後どうですかということを言いましたけれども、それはそれでお願いしたいというふうに思います。多胎妊娠の場合に対して、区としては何か対応していることはあるのか尋ねました。","respondent":"高山健康課長","answer":"おおむねの積み上げの数字が出てまいりませんが、その中での１４回ということで、公費で支援させていただいているです。多胎に関しての特別な支援という点で申しますと、やはり相談などを通じての支援などが考えられると思いますが、あとは出産後に関しては。","id":"exchange-057"},{"speaker":"こんの委員","kind":"質問・要望","question":"おおむねの回数を伺ったところですが、相談なども合わせてどれぐらいなのか、お分かりになれば、お答えほしいと求めました。１４回の妊婦健診に対する費用助成、こうしたことも必要ではないかと考えますが、この点は今どのような状況か尋ねました。","respondent":"高山健康課長","answer":"こちらにつきましては、他区の病院を使用する場合など、都内においては相互に乗り入れるような仕組みも同時に必要になってまいります。２３区共同して、また引き続いて、令和３年度内に検討を進めてまいるということになろうかと考えております。","id":"exchange-058"},{"speaker":"こんの委員","kind":"提案","question":"単胎妊娠よりも追加で受診する妊婦健康診査にかかる費用を補助する市区町村に対して、経費の２分の１を補助するという新規事業を国は始めます。そうした方への費用負担軽減策を創出していただきたい、そのように提案するわけですけれども、いかがか尋ねました。","respondent":"高山健康課長","answer":"区でも同時に検討しつつも、やはり２３区の相互の乗り入れのような仕組みも同時並行で検討することで、手続の負担の省力化を図ってまいりたいと考えております。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこにはスマホ教室も含まれておりますが、これは新規事業なのでしょうか。その点をまずご説明ください。","respondent":"菅野高齢者地域支援課長","answer":"私からは、高齢者社会参加促進事業のうちのスマホ教室が新規事業かどうかということのご質問にお答えします。こちらは令和３年度の新規事業ということで、高齢者の方が安心してスマホを利活用できるようにということで考えております。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうしたものへの一歩踏み出す支援というのでしょうか、こうしたことを今後、スマホ教室の中に入れていただきたい。要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"木村委員","kind":"質問","question":"品川区の人口は、ピーク時より２,０００人ほど減っているということをお聞きいたしました。人口減少も影響していると思いますけれども、区税とは、所得税や住民税のことか尋ねました。","respondent":"伊東税務課長","answer":"区税と特別区税というくくりですけれども、その中には特別区民税、軽自動車税、そして特別区たばこ税、これが入っておりまして、その総称として特別区税と申しているものです。","id":"exchange-062"},{"speaker":"木村委員","kind":"質問・要望","question":"人口が減っているからということで、やっぱりかなりのダメージがあろうかと思いますけれども、頑張ってほしいと求めました。下から２行目にあります、１９款諸収入は前年比５億１,８００万円余の伸びですけれども、これの種類というものを教えてほしいと求めました。","respondent":"品川財政課長","answer":"予算書の１４２ページからずっと書いてあるとおりというところではあるのですが、例えば、そういったものなどがあります。それから、前年度との比較で５億円程度上がっているというところですけれども、大きく伸びているです。","id":"exchange-063"},{"speaker":"木村委員","kind":"質問","question":"同じページの一番下でありますけれども、歳入合計ですが、やはり新型コロナウイルス感染症以外に減額の大きな要因というものが何かあるのでしょうか。説明を求めました。","respondent":"品川財政課長","answer":"そういったところでの住民税額の減というところを見込んでおります。全体として大きいところとしては、歳入面の減額としては、そういうところの要因かというふうに思います。","id":"exchange-064"},{"speaker":"木村委員","kind":"質問","question":"次に、５２ページの一番上の特別区たばこ税、前年比８００万円の減の見込みになりましたけれども、原因はどのようなことが考えられるか。区内でのたばこ店や販売機が大分減っているということも前にお聞きしたことがあったのですが、そして、説明を求めました。","respondent":"伊東税務課長","answer":"値上げとかもされてきていまして、結構な値段になってきているというところもありまして、そういうものが複合的に絡み合いまして売上げの減少につながっているのではないかというふうに考えております。","id":"exchange-065"},{"speaker":"木村委員","kind":"質問","question":"この３０億円の使い道は、以前にもお尋ねしましたが、これといった使い道は決まっていないということで明らかにしてくれませんでした。過去にはどのようなことに使われてきたのか尋ねました。","respondent":"品川財政課長","answer":"特別区たばこ税のところですが、基本的には一般財源分という形になりますので、幅広く利用ができるということになります。これまでの区の事業の中で、特別区たばこ税の収入を使って様々な点で事業に活用させていただいていると、このような状況です。","id":"exchange-066"},{"speaker":"木村委員","kind":"質問","question":"私は喫煙をしませんけれども、１箱でも多くのたばこが区内で売れることを願うものであります。何となくたばこを吸わない目で見ていても気になるところでありますけれども、ここのところを、どのようなお考えか尋ねました。","respondent":"伊東税務課長","answer":"税収というところで見ますと、令和元年の決算でいくと３３億６,０００万円余というところで、逆に若干増えているというような結果があります。売渡し本数に関してはもうしばらく減る傾向は続くのかと考えていますけれども…","id":"exchange-067"},{"speaker":"木村委員","kind":"質問","question":"たばこの売上げだけではなく全てに影響が出てくることも考えられます。我々にも以前のような生活が返ってくると思いお聞きいたしますけれども、ワクチンも含めた全てのことに対して、区のお考えを最後に説明を求めました。","respondent":"品川財政課長","answer":"今、非常に大きな動きとしましては、やっぱりワクチン接種があります。それに応じて、また適切に区としては事業を進めていきたいと、このように思っております。","id":"exchange-068"},{"speaker":"小芝委員","kind":"質問・要望","question":"午前中にも質問がございましたので、二重の答弁をいただかないよう質問させてほしいと求めました。その前の年、前年同月比でどのくらいのパーセンテージだったのか説明を求めました。","respondent":"櫻木生活福祉課長","answer":"令和元年度で最も申請件数の多かった月ですと、令和２年３月が４８件という形で一番多い数字になります。前年同月比ということですと、まだ３月が来ておりませんのでお答えしかねるところではありますが、平均的には１０％程度増えているかです。","id":"exchange-069"},{"speaker":"小芝委員","kind":"質問","question":"昨年４月からの緊急事態宣言による、区のほうで生活保護の相談に来られた方には、どういった対応をされてきたのでしょうか。説明を求めました。","respondent":"櫻木生活福祉課長","answer":"生活保護にまで至らないという方々に対しましては、暮らし・しごと応援センターのほうで、生活保護以外の様々な活用できる手段等をご案内して一緒に考えていくということを行っております。","id":"exchange-070"},{"speaker":"小芝委員","kind":"質問","question":"そのほかにも例えば社会福祉協議会への案内とかもされていたのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"暮らし・しごと応援センターの中で、社会福祉協議会の、特に緊急小口資金であったり、総合支援資金等のご案内も丁寧にしています。","id":"exchange-071"},{"speaker":"小芝委員","kind":"質問","question":"生活福祉課のほうから社会福祉協議会への紹介の割合というのは、例えばその１か月で相談に来られた方のうち、大体どのくらいの割合であったのか、教えてほしいと求めました。","respondent":"櫻木生活福祉課長","answer":"その時点で一定の困窮度合いであるですので、こちらのほうで住居確保給付金のご案内と同時に社会福祉協議会の制度もご案内をしているという意味では、ほぼご案内できているのかと考えています。","id":"exchange-072"},{"speaker":"小芝委員","kind":"確認","question":"一方で、生活保護を受ける側ではなく、そういった方々を支える役割を担っていますケースワーカーについてお聞きいたします。確認ですが、品川区のケースワーカーの方は、今現在、何名いらっしゃるのか尋ねました。","respondent":"櫻木生活福祉課長","answer":"２月１日時点の数字ですが、４４名です。","id":"exchange-073"},{"speaker":"小芝委員","kind":"質問","question":"ケースワーカーというのは、午前中の質疑を聞く限り、例えば、大学などで社会福祉主事の任用資格を持っていなくとも任用されるという認識を持っておりましたが、行政職の方でも人事異動でケースワーカーになるという認識で合っていますか尋ねました。","respondent":"櫻木生活福祉課長","answer":"委員ご指摘のとおり、福祉職以外に、いわゆる事務職の職員もケースワーカーとして携わっております。","id":"exchange-074"},{"speaker":"小芝委員","kind":"質問・要望","question":"人数が法定の標準数に達しないことでケースワーカー１人の負担は大変大きいものと考えます。社会福祉法の求める数はあくまで標準数なので、例えば、いかがか尋ねました。","respondent":"黒田人事課長","answer":"人員配置については、行政全体の業務を執り行えるというところで配置しているところでございまして、あらかじめそのケースワーカーの人数も含めて所要人員調査の中で確認しています。","id":"exchange-075"},{"speaker":"小芝委員","kind":"質問","question":"確かに午前中の質疑では高齢の受給者世帯に会計年度任用職員を活用しているとのお話を伺っておりましたが。現在の会計年度任用職員の採用に際して、どのような基準があるのか教えてもらえますか尋ねました。","respondent":"櫻木生活福祉課長","answer":"会計年度任用職員でケースワークに携わっている高齢者世帯自立支援員という名前がついておりますが、その方々には、社会福祉の豊富な経験もしくは高度な専門性を持った方という要件がありますので、それに沿って採用を行っているです。","id":"exchange-076"},{"speaker":"小芝委員","kind":"意見","question":"こういった会計年度任用職員の方も含めると９０世帯弱ということで、この法定の標準数８０世帯になるべく近づくように取り組んでおられることは認識しておりますので、ご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"横山委員","kind":"質問","question":"一般質問でもお伺いいたしましたが、児童虐待に関する学校と教育委員会の取組について詳細をお聞きします。令和元年５月９日付の「学校・教育委員会等向け虐待対応の手引き」では、管理職とは校長という意味でよろしいか尋ねました。","respondent":"矢部教育総合支援センター長","answer":"生活指導主任会でも子ども家庭支援センターの職員からの講話を受けてありますが、生活指導主任会の中では、生活指導主任が研修をしています。管理職同士の情報連携もとても大切ですので、今後、研修方法の検討とともに理解を進めてまいります。","id":"exchange-078"},{"speaker":"横山委員","kind":"質問・要望","question":"進捗の確認、確認の頻度とチェック方法について、ご説明をお願いいたします。得意分野を伸ばして専門性を高めることができるような研修内容となっていますか尋ねました。","respondent":"立木保育課長","answer":"虐待対応ですとか、インセンティブというよりは、各園こういう取組をしていますというような形でＰＲをしていただくという形になろうかと思います。幼児教育、特別支援リーダー、サブリーダーなどというような得意分野を伸ばすような研修も用意しています。","id":"exchange-079"},{"speaker":"横山委員","kind":"質問・要望","question":"「心とはなんですか」、「愛するとはどういうことですか」など、信頼。言葉の意味を共有し、関係機関で認識のずれが起きないように運用してほしいと求めましたが、区のお考えを説明を求めました。","respondent":"崎村子ども家庭支援センター長","answer":"区の児童虐待対応マニュアルにつきましては、この間、児童福祉法等の改正や組織改正などもございましたので、令和３年度に改定をする予定です。マニュアルをそれぞれの関係機関が対応力の向上に努めていただけるように、共通理解の促進に努めていきたいと考えています。","id":"exchange-080"},{"speaker":"おくの委員","kind":"質問・要望","question":"品川区は、今も区営住宅の入居者が自己負担で浴槽と給湯設備を設置し、また、退去時に撤去すべきだというお考えなのでしょうか。この点からお伺いいたします。","respondent":"森住宅課長","answer":"２年間で１３戸新たに設置をしたところです。令和３年度から、撤去時の風呂釜の撤去費用というものも区のほうで支出するということで、今回ご提案をさせていただいているところです。","id":"exchange-081"},{"speaker":"おくの委員","kind":"質問・要望","question":"壊れた場合に、修繕したり、あるいは取り替えたりした場合にはどうなのでしょうか。これもお伺いいたします。","respondent":"森住宅課長","answer":"令和元年度から区のほうで設置をしておりますけれども、それ以前に自己負担で設置をされた方のものについて修繕が必要だということについては、自己の財産ですので、それぞれの居住者の方にやっていただいているです。","id":"exchange-082"},{"speaker":"おくの委員","kind":"質問","question":"区営住宅においても、こういうことをやってみるべきではないかと私は思ったのですけれども、いかがでしょうか。お伺いします。","respondent":"森住宅課長","answer":"毎月、令和２年６月から８月にかけて、それぞれ申込みを受け付けますという表現がされております。使用者の声がどのように生かされていて、どのぐらいの付け替えがされたのかということは、都のほうとも情報共有していきたいと考えています。","id":"exchange-083"},{"speaker":"おくの委員","kind":"質問","question":"区営住宅のほうで、やるべきではないかという点については、どうお考えか尋ねました。","respondent":"森住宅課長","answer":"基本的には、それぞれの居住者が設置されたものについては、基本的にはそれぞれの方で修理をしていただくということで今のところは考えております。区では、今のところ、それぞれの方に処理していただくということで考えております。","id":"exchange-084"},{"speaker":"おくの委員","kind":"質問・要望","question":"だからこそ、冒頭に課長も言われたように、設置や撤去、これが民間の賃貸住宅と同様に区の負担で行われるようになってきているのだと私は思います。ですから、区の負担で修繕や取替えを行うことに何とか踏み出していただきたいのですけれども、もう一度いかがか尋ねました。","respondent":"森住宅課長","answer":"区のほうで風呂釜の設置をする前の段階におきましては、住宅の維持費等も支給されるというところもございまして、それをご案内しているところです。それぞれの財産ですので、先ほどご紹介いただきました都営住宅の動きなども含めて…","id":"exchange-085"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からは、１４０ページ、ふるさと納税寄附金、それから時間があれば、１３３ページの都議会議員選挙費と衆議院議員選挙費について質問します。会派の同僚も一般質問を何度かさせていただきまして、ふるさと納税による税の流出が増える一方、改めて質問させてほしいと求めました。","respondent":"伊東税務課長","answer":"我々も何とかと思っているところですけれども、根本的には、制度改正をしないことにはなかなか難しいというところがあります。若干の返礼品もこちらのほうで考えまして、こちらのほうにも目を向けてもらう、そのような努力をしているというような状況です。","id":"exchange-086"},{"speaker":"湯澤委員","kind":"質問","question":"登録サイトを増やせば手数料がかかるというご回答は伺っておりますが、こちらのほうは、かなりの人気になっております。以上、登録サイトを増やすこと、品目を増やすこと、金額設定、品切れについて、４点ご意見をお聞かせほしいと求めました。","respondent":"伊東税務課長","answer":"今、同じシナモロールのオリンピック・パラリンピック応援のコラボ３体セットは、まだ在庫があるというところでやっているところです。体験型という返礼品を加えて、それが結構、当面はこの状態を続けていこうかというふうに思っているところです。","id":"exchange-087"},{"speaker":"湯澤委員","kind":"質問","question":"やっぱり返礼品が品切れというのはどうかと思いますので、あとは、寄附者に返礼品が遅くなるという旨を伝えて受注生産するなどすべきかと思います。結果を出すために目標設定をするということは大切であるとも思いますが、いかがか尋ねました。","respondent":"伊東税務課長","answer":"コロナ関係の支援に関しては目標額に若干達しなかった部分はあるのですけれども、子どもに関しては達成しているというような状況です。ガバメントクラウドファンディングの今後ですけれども、それぞれいい事業がございましたら活用していきたいというふうに考えております。","id":"exchange-088"},{"speaker":"くにば委員","kind":"質問","question":"その２つを組み合わせた方式など、区有施設においての契約内容については、どのようになっていますでしょうか。お伺いします。","respondent":"高梨公園課長、東野経理課長、稲田土木管理課長","answer":"区立公園内の自動販売機の状況についてご説明をいたします。区立公園におきましては、１５公園におきまして全３９台の自動販売機を設置しております。 庁舎でいきますと、庁舎内では５台ほど設置しておりまして、この中に６３８万５,０００円ほど計上しているものです。… それと、設置許可で許可をしている自動販売機がございまして、公園内が１８台、年間１１万５,１２８円。それから、自転車駐輪場が１か所あるのですが…","id":"exchange-089"},{"speaker":"くにば委員","kind":"質問","question":"その公園内に設置しているものに関してですけれども、先ほどおっしゃった数字と、プラスアルファで、あと福祉団体が管理している自販機があるというふうに伺ったのですけれども、そこに関しても併せてご答弁をお願いします。","respondent":"高梨公園課長","answer":"先ほどご説明しました１５公園３９台の内訳ですが、私のほうで収入額を申し上げた、飲料事業者によるものが２１台です。そのほかの１８台につきましては、区内の福祉団体による設置ということになってあります。","id":"exchange-090"},{"speaker":"くにば委員","kind":"質問","question":"新たに福祉団体がここに置かせてほしいということがあったら、そこに関してお伺いする限り。１つコカ・コーラの自動販売機が置いてあったら、その横にアサヒ飲料の自動販売機を置くであるとか、そこに関してご見解を伺います。","respondent":"高梨公園課長","answer":"今置いている自動販売機が足りないかどうかといったところをしっかりと見定めて、自動販売機の追加設置等については考えていきたいと、このように考えております。","id":"exchange-091"},{"speaker":"くにば委員","kind":"質問","question":"次に、あわせまして、災害対応型自動販売機、こちらについて伺います。今後、災害対応型自動販売機の導入についての方針やスケジュールを説明を求めました。","respondent":"東野経理課長、高梨公園課長","answer":"８社と契約していますが、全て災害時における自動販売機の無償提供に関する協定書を締結しています。今後も、新規に設置する場合につきましては、同様に災害時の備えを行ってまいりたいと考えています。 公園内自動販売機につきましては、飲料事業者が設置している１１公園２１台については、全て災害対応用のベンダーという形になっております。災害対応用ベンダーがしっかりと整備されているということは…","id":"exchange-092"},{"speaker":"くにば委員","kind":"意見","question":"もう毎号、１日号、１１日号も全て持ってきても、ここは入りますよねというのも、全部お見せしたいぐらい、すごい腑に落ちない部分があるのです。そこの部分はどうにでもなるというふうに申し上げましたけれども、そのスペースがないという部分について…","respondent":"大澤広報広聴課長","answer":"詰めれば入るということだと思うのですけれども、やはり区報は見やすさという観点も重要ですので、現在のところ、広告スペースを増やす考えはございません。","id":"exchange-093"},{"speaker":"くにば委員","kind":"質問","question":"スペースを詰めればというよりは、スペースがあるから、この広告を入れたいということで、すみません、また総務費で質問します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"松澤委員","kind":"質問","question":"私からは、６５ページ、区民活動交流施設使用料についてお聞きします。そこで現在の品川区の人口、今、コロナ禍ですけれども、どれだけ増えて、今後どのような推移を見込んでいるのか説明を求めました。","respondent":"佐藤企画調整課長","answer":"２３区等では、９月から６か月間減少傾向でありまして、その減少に関しましては２,０００人ほど減っているというところです。今後、３月、４月は、転入も増える時期でもありますので、その動向を見極めていきたいと考えています。","id":"exchange-095"},{"speaker":"松澤委員","kind":"質問","question":"町の活力の源の１つは、町会・自治会が元気であるということが欠かせません。町会・自治会の加入率は、ここ数年で、どのような推移をたどっているのか説明を求めました。","respondent":"川島地域活動課長","answer":"町会が配布する物品、町名名入の手拭いやパンフレット等を購入する際にかかる経費に対する補助金を交付するなど、様々な支援策を行ってまいりました。令和２年度が５８.３４％と、約６０％で推移しているところで、ほぼ横ばいの状況という認識です。","id":"exchange-096","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問","question":"「そもそも町会ってなんですか」、「魅力が分からない」、「高齢者しかいないんでしょう」という意見が大半を占め驚きました。多くの人が町内会に加入していた昭和のやり方を、今の時代や住民のニーズに合わせて変えていくことも必要ではないか尋ねました。","respondent":"川島地域活動課長","answer":"令和３年度は３町会が区の支援でホームページを新設する予定で準備をしておりまして、１つの町会がホームページをリニューアルする予定です。現在やってあります町会・自治会活動活性化促進調査の結果などもしっかり活用して、新たな支援策も検討してまいりたいと考えています。","id":"exchange-097"},{"speaker":"松澤委員","kind":"提案","question":"議論して提案をまとめ、審査を通過した後には、地域の方と一緒に汗を流して整備する。そういったような取組も品川区でぜひやってほしいと求めましたが、ご見解を説明を求めました。","respondent":"川島地域活動課長","answer":"町会・自治会が実施する事業のうち、その事業を広く周知しまして、町会・自治会への加入促進につなげることを目的としているものです。その活動を地域で共有しまして、地域の元気の源になります町会・自治会活動の活性化をしっかり支援していきたいというふうに考えております。","id":"exchange-098"},{"speaker":"松澤委員","kind":"質問・要望","question":"やっぱり若い世代が町会・自治会に興味が持てる取組や、円滑な町会・自治会の世代交代につながるような支援をしていただきたいと考えています。何々しなさいとか、時代の変化を注視し、これからもますます活気あふれる品川区になるよう要望して質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-099","title":"町会・自治会支援"},{"speaker":"のだて委員","kind":"質問","question":"これはどういう意味でしょうか。伺います。","respondent":"寺嶋福祉計画課長","answer":"第八期の介護保険事業計画におきましても、様々なニーズに対応するよう特養ホームを含めた施設整備全般を検討していくという意味です。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"今後、そういった整備も含めて行っていくということですけれども、この重度化が想定されるというのはどういう意味でしょうか。これまでと何が違うのか伺います。","respondent":"寺嶋福祉計画課長","answer":"高齢者の人口のうち、いわゆる７５歳以上の後期高齢者の割合が今増えているという状況にあります。そういった意味で、今後、重度化が進むという認識を持っているということで申し上げたところです。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問","question":"高齢化が進んで、それで重度化が進んで、それで必要だということなのですけれども、つまりは特養ホームも増設していくということでよろしいのか伺います。","respondent":"寺嶋福祉計画課長","answer":"特養ホームを含めた様々なサービスの提供に努めていくです。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問・要望","question":"さらなる増設計画はあるのでしょうか。ぜひつくってほしいと求めましたけれども、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"現在予定されているものとしましては、今、委員からありましたとおり、この２か所です。地域密着型サービスの整備ということもあわせて検討しています。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"地域密着型も検討しているということで、今、何か所か検討されているところがあるということか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"ですから、こちら側で一方的に数目だけを計画として出しても、それがなかなか実現するというのは、これは大変難しい要素も兼ね備えているところです。特養ホームの基本計画ということで２か所、それから小山台の計画を進めていくという、今こういう方向性になっているところです。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問","question":"地域密着型については、まだ具体的にはなっていないということだと思います。そして、今回、八潮南特養の増築が示されたわけですけれども、なぜ増築することになったのか、理由を伺います。","respondent":"寺嶋福祉計画課長","answer":"検討はしてきたところですけれども、それから平成２９年６月に上大崎ということで、今実際にあるところの資源も含めて庁内で検討を進めてきたところ。こちらをもとに検討を進めたところ、来年度基本計画ということで予算案に計上させていただいたと、こういう流れです。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問・要望","question":"地域密着型は２９ベッド以下ですけれども、これまでの方針を変えたということでしょうか。伺います。","respondent":"寺嶋福祉計画課長","answer":"これまでの方針に関しては全く変えておりません。一定程度、今回も改めて先ほど申し上げたとおりの考え方が１つ浮上したということで、全く方向性としては今までと変わったものではございません。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問","question":"１００歳以上の人も入れないと、８６％の方が入れないという状況を、さきの一般質問でも示させていただきました。今年の２月と、昨年８月の申込み数を伺います。","respondent":"宮尾高齢者福祉課長","answer":"私からは、特別養護老人ホーム入所申請の数についてお答えをいたします。昨年８月にお申込みをいただいた申込者の数ですが４４５人、その半年前の２月の時点でお申込みいただいた方が４７９人とそれぞれなっております。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"まだまだ特養ホームの増設が必要だと思いますけれども、いかがでしょうか。待機者が入れるようにしていくためには必要なのではないかというふうに思うのですけれども、いかがか尋ねました。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"今現在、高齢者の人口がまだ増え続けている時期にあるということでは、一定程度の施設整備が必要だと考えております。その際の施設整備というのは、大型の特養に限ったことではなく地域密着型も含めた施設整備です。 今年２月末でお申込みをいただいた方の数ですが、速報値でありますので、若干人数が変更する可能性はありますが、２月末時点で４１３人の方から申請をいただいております。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"申請をしても入れないという方が待っていらっしゃるというわけですから、この待機者を正しく定義すること、やはり潜在的な待機者もいるわけですから。申請者は入所が必要な方だというふうに考えていらっしゃらないのか伺います。","respondent":"宮尾高齢者福祉課長","answer":"もちろん全ての方に対して我々真摯に受け止めて対応しています。我々のサポート、支援というのは、そこからもずっと続いていくものと考えているところです。","id":"exchange-109"},{"speaker":"のだて委員","kind":"質問","question":"区も、再度入所申請している方が４割と説明をしています。その方々が入れないということで、区の認識でもこういった方々は本当に必要な方だというふうに思うのですが、認識を伺います。","respondent":"宮尾高齢者福祉課長","answer":"その方にとって本当に幸せなことなのかということも含めて、そういったことも含めてトータルにいろいろなところで相談に乗らせていただいております。決して我々の支援、そこからどうやって次につなげていくかというところも、ふだん非常に大切にして業務に当たっているところで…","id":"exchange-110"},{"speaker":"のだて委員","kind":"質問・要望","question":"入れない方が数百人単位でいるわけですから、土地がないというのであれば、民間に土地を募集などもして増設する計画をつくってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２０年近く前からの地元要望であり、区から国へ要望を上げていただくように、これは陰にも陽にも何度も取り上げてきた悲願の一つです。複数の町会からの要望でもありますし、品川区としてどのように考えているのか、改めて説明を求めました。","respondent":"鈴木都市計画課長","answer":"バリアフリー対応のエレベーターもついていないというところで、これまでも継続して様々な機会を捉え、地域の現状と要望を伝えてまいりました。区としましては、実現に向けてこれまでも働きかけをしています。","id":"exchange-112"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこで国会議員にお願いをしまして、先週の金曜日、２月２６日の国会の予算委員会で、地元の要望として質問で取り上げていただきました。所管課長である都市計画課長もご覧になったと思うのですが、国交省道路局長の答弁をお聞きになっての感触、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"ご紹介いただきました国の予算委員会でのやり取りにつきましては、私も確認し、承知しています。やはりこれまでも国から説明のあった、第一歩ということで、前向きに強く受け止めているところです。","id":"exchange-113"},{"speaker":"あくつ委員","kind":"質問・要望","question":"第一京浜ですけれども、これは国会で質問していただくことはできなかったのですが、こちらも長年の地元要望です。この歩道橋に関しての区のお考えと、国への要望状況、また課題等があれば、説明を求めました。","respondent":"鈴木都市計画課長","answer":"昭和４０年代当初、築５０年以上が経過している歩道橋だということで、これまでも強い働きかけを国にしてまいった次第です。","id":"exchange-114"},{"speaker":"あくつ委員","kind":"質問・要望","question":"続きまして、交通安全対策特別交付金、関連をいたしまして自転車活用推進計画についての策定の進捗状況を確認します。２０１９年９月の一般質問で、品川区も独自の自転車活用推進計画を策定してはどうかという質問をさせていただきましたら。","respondent":"鈴木都市計画課長","answer":"１月に東京都において検討会が開かれて、現在、３月中旬頃までパブリックコメントが実施されている状況です。マスタープランの改定検討は、両計画の中身をしっかり把握して、再来年度以降の予算要求の方向性についてしっかり検討していきたいです。","id":"exchange-115"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのことについて、確認が、いわゆる外部委員の方、また委員の方からはあったのか。それが審査に影響をしたのかどうか、そのことについて説明を求めました。","respondent":"築山障害者施策推進担当課長","answer":"そのことも含め審査をしてほしい」という表明がされまして、そのことが応募団体の大事なスタンスとして説明がございました。共同事業体がスムーズな連携がとれるのか、審査会、一体的な管理運営は難しいのではないかといったようなご意見が出たです。","id":"exchange-116"},{"speaker":"あくつ委員","kind":"質問・要望","question":"意向も伺った上で、いわゆる継続を求めたいというお声が非常に利用者の中で多かったというところと、ただ。かなり浮き彫りになりましたので、指定管理者制度については、明後日の総務費で伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-117"},{"speaker":"あべ委員","kind":"質問","question":"どのような積算でこの金額になっているでしょうか。割り返すと、丸々２年以上かかってしまうのではないかと思うのですけれども、こういう体制でいいのかどうかということをまずお伺いします。","respondent":"川口交通安全担当課長、大澤広報広聴課長、木村戸籍住民課長","answer":"こちらにつきましては１１９.９％、こちらにつきましては５３.８％、大井水神公園の地上の当日利用スペースです。こちらにつきましては９７.５％、また… 閲覧にかかる手数料の３００円掛ける１,０００件と、１０円掛ける２万４００枚ということで、大体月１,７００件の計算で出しております。 現状では、ご案内したとおりですけれども、４月以降、職員の増員、それから、いわゆる発行する体制を強化すること。それから…","id":"exchange-118"},{"speaker":"あべ委員","kind":"質問","question":"これはやはり今の時代に合わないと思うので、見直しをされるべきではないかと思いますが、いかがでしょうか。ご答弁をお願いします。","respondent":"川口交通安全担当課長、大澤広報広聴課長","answer":"現在南側と日立大森ビル前ですけれども、先ほどご説明したとおり、まだ利用率が高い状況です。利用率の非常に高い部分は当日利用となっておりますので、今後、利用状況等も見ながら検討してまいりたいというふうに考えております。 現在、国のほうはまだ同じように閲覧の手数料を取っているというふうに認識しております。今のところ、閲覧の手数料はいただくということで実施してまいりたいというふうに考えております。","id":"exchange-119"},{"speaker":"あべ委員","kind":"質問・要望","question":"本年度、どこにもご案内も出てこなくて予算も出てこなくて、どうなっているのかなと。実績を教えていただきたいのと、令和３年度は、どうなっていくのか説明を求めました。","respondent":"櫻木生活福祉課長","answer":"ご質問の暮らし・しごと応援センターで配布しております食料支援の件ですが、実績としましては、今年度につきましては９件の実績があります。来年度につきましても同じような形で継続したいと考えています。","id":"exchange-120"},{"speaker":"あべ委員","kind":"意見","question":"一応制度設計の段階では年間５０件で、９件というのは、知っている方はほとんどいないと思います。これを契機にご案内できるように、ぜひ運用方よろしくお願いしたいと思いますが、一言との意見を述べました。","respondent":"櫻木生活福祉課長","answer":"基本的に制度としては、様々な制度を含め周知をしていくことは大事なことだと考えています。ある程度お話を伺った上で必要な方にご紹介するということもありますので、その辺りを見ながら適切な周知は考えていきたいと考えています。","id":"exchange-121"},{"speaker":"あべ委員","kind":"質問・要望","question":"自治体が運営して、品川区もその利益の一部を受け取っている以上、十分な情報公開をすべきだと考えています。ぜひ品川区としても取り扱ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-122"},{"speaker":"鈴木（真）委員","kind":"確認","question":"新型コロナウイルス感染症の問題で児童虐待が増えているという報道が大分出ていますが、品川区における実態等、確認をさせてください。これも新型コロナウイルス感染症の影響を受けたことから大分支給も増えたと思うのですが、その支給の金額の実態等、世帯数とかを確認させてください。","respondent":"崎村子ども家庭支援センター長、三ッ橋子育て応援課長","answer":"令和元年度が５１０件でございましたので、２か月を残して前年度を上回る件数を、今、受理、対応しています。令和元年１０月から都の児童相談所と区市町村の基本ルールが変更になり… 追加給付は８４０世帯、再支給分は１,８４１世帯、合計４,５２５件で２億６,９００万円となっております。申請の締切りが２月２６日となっておりまして、まだ最終確認をして審査をしている部分がありますので…","id":"exchange-123"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"１件でも少なくなっていただきたいという、その辺、これからも十分対応をお願いしたいと思います。それから、ひとり親の今の手当の関係ですけれども、総額でお話しいただいたのですけれども、１世帯当たりの金額をもう１回確認させてください。","respondent":"加島児童相談所移管担当課長、三ッ橋子育て応援課長","answer":"一時保護についてですが、原則は自らの一時保護所で対応いたします。設置区では、また、他自治体の子どもを自区の一時保護所で受け入れていると聞いております。 追加給付ですが、１世帯当たり５万円です。再支給分は、基本給付と同様で、１世帯当たり５万円、第二子以降、１人当たり３万円となっております。","id":"exchange-124"},{"speaker":"鈴木（真）委員","kind":"質問","question":"新たな組織をつくるということは私は非常におかしいと思いますので、どういう体制をもって相談をやっていくのか、その点について教えてください。新たな形を考えていくのか、ぜひ続けていってもらいたいのですが、その辺のお答えをほしいと求めました。","respondent":"加島児童相談所移管担当課長、三ッ橋子育て応援課長","answer":"こちらにつきましては、依頼元、依頼先併せまして相互に協力して調査した上で対応していくようなことも協定の中に定められております。先行区含め、入所状況の周知、配付に努めているところです。 坂井市がふるさと納税による「きふと」というものを実施しておりまして、品川区のひとり親世帯にお米が届くという制度でございました。なかなかお米については対応できないのですけれども、来年度…","id":"exchange-125"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"建築費総額が約３０億円ですけれども、財源として３種類の国庫補助金、その辺も確認させてください。それからもう１つ、相談していただいているようですが、その辺の役割と今後の活用について説明を求めました。","respondent":"加島児童相談所移管担当課長、三ッ橋子育て応援課長","answer":"こちらは最大で約２億４,０００万円、点数に基づき交付を見込んでおりまして、工事期間の３か年にわたってこれを収入する計画です。児童相談所のほうで弁護士の配置ですとか… 令和２年度から採用した家庭相談員に関しましては、４月１日からこちらに会計年度任用職員として採用しております。こちらは本当に知識や経験が豊富で、離婚の前後の相談、また、親権者の相談、様々、かなり丁寧で…","id":"exchange-126"},{"speaker":"鈴木（真）委員","kind":"確認","question":"最後に、特別区税に関して確認だけ。この状況ですから非常に難しい状況と、それから区の財政全体を今後どう見るかも考えていく中で、考え方だけ確認させてください。","respondent":"佐藤企画調整課長","answer":"総合実施計画の作成の見込みです。新型コロナウイルス感染症が収束に向かいましたら、また策定作業を始めまして、財政面も含めて適切に対応したいと考えています。","id":"exchange-127"},{"speaker":"鈴木（真）委員","kind":"意見","question":"十分その辺は分かりますので、ぜひお願いしたいと。今年は計上してないのかどうか、予算上のどこかに計上されているのかどうか、予算は要らないのかどうかとの意見を述べました。","respondent":"佐藤企画調整課長","answer":"今年度、実施計画の策定に係る予算は計上しておりません。","id":"exchange-128"},{"speaker":"安藤委員","kind":"質問","question":"伺いますが、区はこの間、品川駅南地域のまちづくり検討に予算をつけて委託してきましたが、総額幾ら予算をかけてきたのか、累積額を伺います。いつからこの検討経費が予算化されたのかも伺います。","respondent":"中道まちづくり立体化担当課長","answer":"平成２４年度から計上していまして、令和３年度を含めますと、合計１０回計上しています。歳出の合計金額ですが、令和２年度予算額、令和３年度要望額としまして、合計金額が約１億１,５００万円です。","id":"exchange-129"},{"speaker":"安藤委員","kind":"質問","question":"黒塗りや非公開などの処理をせずに公開すべきだと思うのですけれども、議員から出してと言われたら出していただけるのでしょうか。伺います。","respondent":"中道まちづくり立体化担当課長","answer":"情報公開についてですが、区としましては、行政の情報等は公開が原則ということは認識しています。検討状況であったり、または、その整理をしています。","id":"exchange-130"},{"speaker":"安藤委員","kind":"質問","question":"まちづくりですから、私はおかしいと思っていまして、政策形成過程だからこそ情報は公開すべきなのではないでしょうか。別にアンケートに誰がどう答えたかと個人名出せと言っているわけではないし、その情報がなければ、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"そこのまちづくりの検討中のまだ素案の段階になりますので、そういった観点から、一部情報は非公表にさせていただいてあります。","id":"exchange-131"},{"speaker":"安藤委員","kind":"質問","question":"区はまちづくりの検討、しかも税金も相当使っていますよね。これだけの大きな、私はこれはまちづくりに住民の意見を入れるつもりがないというふうにしか思えないのですけれども、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"検討の段階におきまして、常任委員会の中でご説明しながら、熟度を上げながら整備しています。そういういろいろな段階に応じて、区としては、見極めながら情報は開示し議会のほうとも進めていきたいと考えています。","id":"exchange-132"},{"speaker":"安藤委員","kind":"質問","question":"住民参加、議会に説明というのは建前で、なるべく水面下で検討を進めて、開発協力企業など一部の意向でまちづくりをしたいからではないのでしょうか。伺います。","respondent":"中道まちづくり立体化担当課長","answer":"今現在のまちづくり状況ですが、まだ素案の段階の前なので、建設委員会のほうに報告すべき段階でないです。建設委員会のほうに報告すべき段階、素案等を決定しましたら、その段階で建設委員会のほうには報告いたします。","id":"exchange-133"},{"speaker":"安藤委員","kind":"質問・要望","question":"かなり大がかりにアンケートも１,０００人を対象にやっていたわけですから、そのアンケートが基礎材料となって、それは。検討の中身を隠すのは大問題ですから、公開するよう改めて求めたいのですが、どういう方々が検討しているのか。","respondent":"中道まちづくり立体化担当課長","answer":"品川駅南地域の未来を創る推進協議会、または品川浦周辺地域再開発協議会の事務局ですが、地域の方々の町会長ならびに商店街、または代表者といった方々で構成されてあります。","id":"exchange-134"},{"speaker":"西本委員","kind":"確認","question":"これはどういうときに使われるのでしょうか。それからもう１つ、この利益、歳入は全く発生しないという仕組みなのか尋ねました。","respondent":"森住宅課長、川島地域活動課長、品川財政課長、佐藤企画調整課長","answer":"区営住宅の風呂釜の設置についてですけれども、目的といたしましては、それを少しでも低減させようというところの目的で始めたものです。… こちら１人４m2程度になるような形でということで、新型コロナウイルス感染症対策ということで制限をしているものです。… 例年３億円で計上するようにしているのですが、やはりこのコロナ禍の中、状況がどう動くか分かりません。早急な対応をするためということで２億円増… 指定管理料ですけれども、運営費をたたずまいとしてまず考えまして…","id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"令和３年度から事業として始めますということになっているわけですから、その方々が、例えば故障したといった場合は誰が払うのですか。それから収支率みたいな考え方、これも予算書の中で分かるような状況があると助かるというふうに思いますが、いかがか尋ねました。","respondent":"森住宅課長、川島地域活動課長、佐藤企画調整課長","answer":"令和元年度からは、原状回復に応じて区のほうで設置をさせていただいて、それは区が設置するため区の財産ですので、区のほうで補修をしていきます。… 区民集会所の料金の減免です。制限が感染症対策であるということを丁寧に説明させていただきまして、今のところ… 例えば１５３ページの下から２つ目の品川産業支援交流施設運営収入というのが利用料が多いところで、区に還元があったです。…","id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"壊れたら設置してあげればいいではないですかと思います。ここだけお願いします。","respondent":"川島地域活動課長","answer":"繰り返しの答弁になりますが、現状の料金はそのままという形で考えさせていただきたいと思います。","id":"exchange-137"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"６１ページ、区民斎場使用料、なぎさ会館、６７ページ、八潮北公園スケートボード場について質問します。利用者は１日１組ということなのですけれども、当然、今はまだコロナ禍なので、現況をお知らせほしいと求めました。","respondent":"木村戸籍住民課長","answer":"昨年度は約４０％ですので、ご利用される方の減少傾向があります。感染症拡大防止のために家族葬など葬儀を小規模化するような動きがあるです。","id":"exchange-138"},{"speaker":"高橋（伸）委員","kind":"質問","question":"２４０件に対して、令和３年度の予算は３００件ということで、１日１組ということで計上していると思うのです。それで、今この状態で、緊急事態宣言が解除されて、見込みとして、どういうふうにお考えになっているのかお願いします。","respondent":"木村戸籍住民課長","answer":"実際のコロナ禍のこれからの状況に応じて、ある程度そういう３密みたいな部分での動きが解除されるような形になりましたら、基本的には元通りの２組というような形に戻して、もちろん感染症対策も行いつつ行っていきたいというふうに考えておるところです。","id":"exchange-139"},{"speaker":"高橋（伸）委員","kind":"質問","question":"本当に新型コロナウイルス感染症が終息しても、今後の葬祭のあり方というものが物すごく加速すると思うのです。今後どういうふうに、あるいは、なぎさ会館を今後どういうふうに展開していくのかだけお聞きしたいと思います。","respondent":"木村戸籍住民課長","answer":"地域の方々に使用されない時間帯をご活用いただけないかというようなところのお話もいろいろ出てきているということも聞いております。今後、地域の皆様のそういう需要を踏まえながら活用を考えてまいりたいというふうに思っております。","id":"exchange-140"},{"speaker":"高橋（伸）委員","kind":"質問","question":"ホームページに、授乳室の使用の記載があるのですけれども、「葬儀が執り行われていない時間帯は、斎場利用者以外の方にもご使用いただけます」と書いてあるのですけれども、実際に利用されている方はいらっしゃるのか尋ねました。","respondent":"木村戸籍住民課長","answer":"現地では、のぼりも立ててご案内をしていますけれども、外出自粛の影響もあると思うのですが、現在はほとんどご利用がないというような状態です。引き続き、ご活用いただきたいというふうに考えております。","id":"exchange-141"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続いて、６７ページ、八潮北公園スケートボード場についてお伺いします。３月２７日にあるということなのですけれども、２０人ということで、どういうふうな状況になっているか説明を求めました。","respondent":"高梨公園課長","answer":"通常であれば毎月最終土曜日ということで年１２回実施していますが、令和２年度につきましては、年６回ということで予定をしております。現在まで、８月、１０月、１１月と、今年度は３回実施をしております。","id":"exchange-142"},{"speaker":"高橋（伸）委員","kind":"意見","question":"令和元年の決算を見ても２,４５８回、令和２年の決算３,１４８回ということで、数字的にも利用者がすごく多いのが見受けられます。もっともっとスケートをやる若者たちに知らせるために、区として、ＰＲ強化をこれからどういうふうに展開していくのかどうかだけお知らせくださいとの意見を述べまし…","respondent":"高梨公園課長","answer":"今までもスケートボード場のＰＲとしまして、ホームページや、デザインを工夫したポスターの作成などに取り組んでまいりました。若年層の方が多く使うＳＮＳを中心とした発信を来年度から行う予定で、現在、準備をしています。","id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"ここで確認したいのは、区のほうが２.０パーセント弱、大きくなっている。もう１つは、この法人住民税の影響を小さくするには、今後どのようなことが考えられるのか教えてほしいと求めました。","respondent":"品川財政課長","answer":"その２３区の配分の中で、土木関係の費用等、財調のほうでうまく補助を得られているような形等もあります。２３区連携して、このことについては東京都とも連携して、何とかしてこの法人住民税の国税化を少しでも止めていきたいというふうに考えております。","id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"このような事業者に向けた対応策、新型コロナウイルス感染症対応地方創生臨時交付金の活用も含め、国の強い対応を求めさせていただきました。２点についてお伺いいたします。","respondent":"品川財政課長","answer":"令和２年度から、具体的に言えば、もう去年の３月ぐらいからですか、融資を大分力強く区のほうでは対応して支援を行ってきております。そういう中で、新型コロナウイルス感染症対応地方創生臨時交付金が、来年度以降、出てきてあります。","id":"exchange-145"},{"speaker":"本多委員","kind":"質問","question":"１２９ページの防災区民組織育成費について質問します。３か年計画ですけれども、２０１町会・自治会への普及について、これからについてそれぞれ説明を求めました。","respondent":"中島防災課長","answer":"今年度の９月補正で、災害時の初動対応で電源確保ができるように、資機材の購入費用の一部を助成するものです。来年度につきましては、今年度と同様の８０組織に対して事業を進めていきたいと考えているところです。","id":"exchange-146","title":"町会・自治会支援"},{"speaker":"本多委員","kind":"質問","question":"３年前に北海道胆振東部大地震で、どうして発電機を使っていなかったのだろうか、この対象になるものを見るとすごく網羅できているなと感じます。主にこの８０件というのが、ほかにどういったニーズがあるのか、その現況を説明を求めました。","respondent":"中島防災課長","answer":"コード類が１２６台、ソーラーパネルが２３台、それとコードリール２８台となっております。やはりカセットボンベ式の発電機が、今回の申請では一番数が多かったような状況です。","id":"exchange-147"},{"speaker":"本多委員","kind":"質問","question":"主にガソリン式の発電機などを使う場合に、これを管理する町会・自治会が貯蔵するガソリンなどの量については、どのような対応をされているのか。それに使うガソリンとか、その辺の貯蔵については、どのように把握をされているのか尋ねました。","respondent":"中島防災課長","answer":"ガソリンに関しましては、消防法の危険物の取扱いという規定の中で４０ｌ未満という基準となっています。基本的に燃料は危険なものでありますので、その基準の範囲内で管理していただくように考えております。","id":"exchange-148","title":"町会・自治会支援"},{"speaker":"本多委員","kind":"質問","question":"４０ｌぐらいまでが目安なのでしょうか。逆に危険過ぎるというところで、４０ｌを超える場合の有資格者の配置義務ですとか、その辺についてはいかがか尋ねました。","respondent":"中島防災課長","answer":"基本的に４０ｌを超えますと、区といたしましては、やはり地域の方にはその基準の範囲内の４０ｌ未満で保管はお願いしたいと考えております。４０ｌで、大体１日から３日程度、４０ｌ未満というのが保管量としては適切ではないかというふうに考えているところです。","id":"exchange-149"},{"speaker":"本多委員","kind":"質問・要望","question":"スマートなマニュアルというのでしょうか、ガソリン式発電機とか、誰もが取り扱えるようなマニュアルを。これをやるのは町会・自治会の自主的なものですけれども、ある程度、区もその辺、誰もが使えるような、そのようものを考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-150","title":"町会・自治会支援"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１４０ページの減債基金繰入金についてお尋ねします。幾つかお尋ねするのですが、令和３年度の繰入金額は、これまでの繰入金額よりも１桁多いのです。","respondent":"品川財政課長","answer":"ちょっとこれは古い話になるのですが、平成１０年代ぐらいのとき、減税補てん債をほぼ毎年発行していた経過があります。これに対して、一般の起債の返済分も減債基金のほうでまかなっていくという対応をしている関係から、前年度よりも金額が上がっているというものです。","id":"exchange-151"},{"speaker":"高橋（し）委員","kind":"質問","question":"どうしてぴったりというか、その４,７００万円分に減債基金繰入金を充当していないのか、そこがちょっと分からないのです。すみません、細かいですがお願いします。","respondent":"品川財政課長","answer":"ぴったりというところで、必ず合わせるというようなやり方というところでもございません。歳入・歳出のバランスを見て、その後に各基金のほうの配分を決めていくというような形をとっておりますので、そういった中での計算上の結果です。","id":"exchange-152"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"財調の基金と同じような性格なので一般財源としているという、これまでの課長のご答弁にもありましたが、そういう認識でよろしいのでしょうか。財政の専門家というお立場で教えてほしいと求めました。","respondent":"品川財政課長","answer":"そういう中で減債基金につきましては、先ほど委員のほうからお話があったように、基本的には起債の部分に対して返していくところで活用していく。そういう中での一定のルールに基づいた繰入金の額を今回の令和３年度の予算として計上しているというものです。","id":"exchange-153"},{"speaker":"高橋（し）委員","kind":"確認","question":"それで、目的というか、繰入れ先が決まっているけれども、一般財源扱いというこれまでのご説明は、今、私のほうで幾つか地方財政法のお話をしたのですが、それによって一般財源という扱いになっているという、特定財源という言い方をするとあれですけれども、その辺りは、もう１回確認でお願いします。","respondent":"品川財政課長","answer":"使い方というところに関しては、幅広く使えているので、そういうところの部分と解釈しても構わないかということは考えております。減債基金のほうにつきましては、当然限定されていますので、そういった部分での活用ということになっております。","id":"exchange-154"},{"speaker":"高橋（し）委員","kind":"質問","question":"そちらも別の機会にお伺いします。１０年から数年にわたって行ったということですが、その起債について、見込まれるのかどうかというところもお尋ねします。","respondent":"品川財政課長","answer":"例えば、令和３年度分で起債を償還というような形になっておりますので、これから毎年どんどん償還していくというような流れになってあります。それから、現時点で、歳入状況は非常に今厳しい状況ではあるのですが、減税補てん債を上げていくという方向性の考えは…","id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"意見","question":"財政状況の資料にも、品川区は過去に起債されていた減税補てん債は令和８年で完了するというふうに書いてあります。減税補てん債についても、機会があればお尋ねしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-156"},{"speaker":"大倉委員","kind":"質問・要望","question":"７９ページ、住民基本台帳証明手数料、６０ページ、総務使用料、７５ページ、自転車駐車場について伺います。その辺の確認をさせてほしいと求めましたので、お願いいたします。","respondent":"木村戸籍住民課長、古巻文化観光課長、中元スポーツ推進課長、川口交通安全担当課長","answer":"５割ぐらいいくのではないかなという見立てではあったのですけれども、住民異動係という引越しの手続を行うところで１台で行っておるところです。た… 文化センター等の使用料の支払いですけれども、従前からのやり方ということで、現在いろいろお願いをしている部分があります。… 登録団体であれば口座振替に対応していますが、それ以外、口座登録されてないところは現金払いという現状になっています。こちらについては… こちらは令和元年度ということで、品川区のほうから東京都へ報告した台数ですけれども…","id":"exchange-157"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ進めていっていただきたいのと、今後拡大というご答弁は、それ以外の支払いの方法についても拡大ということなのか確認をさせていただきたい。１回現場に行って支払いをしないと、ぜひ改善してほしいと求めましたが、いかがでしょうかということ。","respondent":"山本情報推進課長、川口交通安全担当課長","answer":"窓口のキャッシュレスにつきましては、交通系ＩＣカード以外のキャッシュレス決済サービスも対応できるように、今、検討を進めているところです。それから施設予約システムの部分に関しましては… 各保管所の収容台数につきましては、現在、八潮北保管所が４,５００台のキャパシティがあります。こちらは平均で、収容台数なのですけれども、１,１０８台の２６％、不動前保管所は５５.３％となっております。","id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"それについてどのように見解をお持ちでしょうか。調布市と同様の工事内容なので、今後、地盤の沈下や隆起や空洞が発生する可能性がこの品川区にもあるということか尋ねました。","respondent":"松本河川下水道課長","answer":"今、私たちでは、第二戸越幹線という幹線工事を実施しています。今、委員からありました調布市で発生した事故については認識しています。","id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"これをつくるにあたって、品川区は地下３５ｍですが、この幹線工事を進めてきましたが、何を根拠に、今、課長はおっしゃっているのですか。さらに、継続して調査しているのか尋ねました。","respondent":"松本河川下水道課長","answer":"昭和６２年から実施してございまして、おおむねトンネル工事と言われるシールド工事につきましては、約９kmやっているところです。あわせまして、シールドマシンが通過した３か月後までは、毎月１回測量して、６か月後までは目視で点検することで検査をしています。","id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"もしこれで万が一のことがあったらどうするのですか。そして今回これをやってもいいと認可したのはどこなのか尋ねました。","respondent":"松本河川下水道課長","answer":"下水道工事で３,０００か所陥没があるというようなお話がございましたが、そこに土砂が入り込んだことによって陥没が起きるということはあります。特殊地盤であること、今回そういったことがないように、しっかり管理をしていきたいと考えているところです。","id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"安全をどうやって保障できるのですか。そして、もし賠償問題になったときは、これは回答がありませんでしたけれども、その責任は品川区にあるということか尋ねました。","respondent":"松本河川下水道課長","answer":"今回はあくまでも土砂を取り込み過ぎたことによって陥没が生じることが多いですので、そういった土量の管理を日々やっていきたいと考えています。発注者である品川区、もしくは受託元の下水道局等と相談しながら補償の問題に取り組む必要があるというふうに考えてあります。","id":"exchange-162"},{"speaker":"須貝委員","kind":"質問","question":"この間の飛行機もそうではないですか。絶対区のほうで、もう絶対に大丈夫だというちゃんと保障ができて、そして賠償もきちんとするということでいいのか尋ねました。","respondent":"松本河川下水道課長","answer":"今お話のありました絶対ということは、やはり私からは、絶対大丈夫だということはなかなか言えないところです。しっかり管理してやっていきたいと考えています。","id":"exchange-163"},{"speaker":"中塚委員","kind":"質問","question":"１４１ページ、歳入減に伴う１０％のマイナスシーリングと、公共事業の先送りについて伺いたいと思います。このマイナスシーリングの対象となり廃止となった、また縮小となった事業はあるのか、それは何か伺いたいと思います。","respondent":"品川財政課長","answer":"令和２年度、８月に依命通達を出したのですが、８月の時点で令和３年度の歳入は非常に厳しいという見込みのもとでシーリングをいたしました。こういった部分を一通りまたゼロベースで見直しをかけて、令和３年度の予算編成をしています。","id":"exchange-164"},{"speaker":"中塚委員","kind":"質問","question":"お伺いしたのは、マイナスシーリングの対象となって廃止となった、または縮小した事業があるのかないのか、伺いたいと思います。","respondent":"品川財政課長","answer":"シーリングですので、事業の中でどういうものを使っているかという中での、基本的に予算の使い方について見直しをしているものです。事業自体というところについては、やはりまた区の政策等、そういったところを見た形でのやり取りでやっていくものだというふうに考えております。","id":"exchange-165"},{"speaker":"中塚委員","kind":"質問","question":"この施政方針で述べた一部先送りの経費の特徴とは何か、伺いたいと思います。そして再開発事業ですけれども、緊急性はないと私は思いますけれども、いかがか尋ねました。","respondent":"品川財政課長、多並都市開発課長","answer":"緊急性の高いものについては令和３年度予算で編成をしています。翌年度に繰り越しても大丈夫ではないかというような判断のもとに、そういった工事の一部を見送って、令和３年度の予算は編成をしています。 区では、老朽化した建物の改築や、または狭い道路の拡幅など、まちの抱える地域の課題を解決するために再開発事業を進めているところです。このような防災性にも資するようなまちの課題を解決するための事業ということで…","id":"exchange-166"},{"speaker":"中塚委員","kind":"質問","question":"代表質問でも、そこに莫大な税金を使っている場合なのかと、少なくとも今はコロナ対策の予算を手厚くすべきだと伺いました。ここで述べられた配慮ですけれども、一体どのような配慮をしたのか、社会経済の変化にも配慮したとは何を差しているのか伺いたいと思います。","respondent":"多並都市開発課長","answer":"区では再開発事業を進める中で、この事業の性格としまして、検討段階から事業の実施までの間に非常に長期となる事業が多くあります。幅広く総合的に捉えて、これらを十分に配慮しながら事業を進めていく必要があると、そういう意味の配慮という意味です。","id":"exchange-167"},{"speaker":"中塚委員","kind":"質問・要望","question":"避難生活は数か月にわたるわけですから、また、オフィスビルは防災対策にはならない。コロナ禍であっても、今までどおりにビルや道路を造り続けるお構いなしという姿勢は改めるべきだと思いますが、改めていかがか尋ねました。","respondent":"多並都市開発課長","answer":"区といたしましては、誰もが安心して暮らせるように、まちの安全を強固なものにして、環境面を含めた持続可能な住みよいまちづくりを目指し進めているものですので、必要な経費については計上させていただいて、しっかり進めていくという考えです。","id":"exchange-168"},{"speaker":"中塚委員","kind":"質問・要望","question":"オフィスビルを縮小、撤退する企業も見受けられます。持続可能とこの場で言うのであれば、それこそ品川区政の根本的な再開発事業優先の姿勢を改めて見直していただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-169"},{"speaker":"大沢委員","kind":"質問","question":"５３ページの児童相談所と、６１ページ、区民集会所をお願いします。５３ページの児童相談所ですけれども、こういう２つの機能を有するわけですけれども、どのような検討がされているのか説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-170"},{"speaker":"大沢委員","kind":"質問","question":"先ほど児童相談所移管担当課長がいらっしゃったので、よかれと思って聞いたのですが、質問を変えて、先に区民集会所からいいですか。私の記憶するところでは昭和５５年辺りからそこら辺を開所したという覚えがありますけれども、まず、ご披露願いたい。","respondent":"川島地域活動課長","answer":"私の認識では、小山三丁目２２番のところに、昭和５５年に荏原第一出張所が移ってきて営業を開始したというふうに認識しております。","id":"exchange-171"},{"speaker":"大沢委員","kind":"質問・要望","question":"当時の私の先代からの話ですと、いろいろとやはり地元の商店街との関わりもあったやに聞いておりますけれども、そこのところをご説明というか、せっかくの機会ですので教えていただきたい。","respondent":"川島地域活動課長","answer":"荏原第一地域センターの１階と２階部分を所有しておりますが、区が３億円余のお金を出しまして床を買い、それでこちらに移ってきたというふうに聞いてあります。","id":"exchange-172"},{"speaker":"大沢委員","kind":"質問","question":"そのような中にあって、今度新しくできるわけですけれども、町会のホームページを見ておりますと、町会のホームページから各地域センターの紹介に移りますけれども、地域センター独自のホームページは、何か事情があってお作りになっていないのか、そこの理由があったら説明を求めました。","respondent":"川島地域活動課長","answer":"作業いたしました町会・自治会連合会のホームページ、そちらが４月から稼働するような予定になっておりますので、イメージしているようなものがそちらで動き始めるです。","id":"exchange-173"},{"speaker":"大沢委員","kind":"意見","question":"近隣８商店街、９商店街、新しいホームページも作れると思うのです。地域センター独自の、官ではなく民に近いような感覚を持ったホームページ作りが大事だと思うのですけれども、どういうふうにお考えになりますかとの意見を述べました。","respondent":"川島地域活動課長","answer":"こちらのほうで情報発信する際は、若い方が喜ぶようなもの、それから新しく来た方が喜ぶようなものというところも踏まえながら作業を進めていきたいと考えています。","id":"exchange-174"},{"speaker":"大沢委員","kind":"質問","question":"聞いていないですか。あるいはいろいろなところをどういうふうにスムーズに移行していくのか、どのような取組がなされているのか、２分以内でお答えください。","respondent":"加島児童相談所移管担当課長","answer":"それから子ども家庭支援センターを併存させる方向で検討を行っておりますので、子ども家庭支援センターが支援というような役割分担をいたしまして、それぞれの支援を行ってまいりたいと考えているところです。","id":"exchange-175"},{"speaker":"たけうち委員","kind":"質問","question":"いろいろそういうお話を伺って大変身が引き締まるわけですが、また、区としてどのように位置づけて考えていくのかということを教えてください。どのような成果を区として感じているかということを説明を求めました。","respondent":"品川財政課長","answer":"こういった部分で歳入減に少しでも対応していこうというような方法で令和３年度予算を編成いたしました。今後も税外収入を確保できるように努力をしてまいりたいと、このように思っております。","id":"exchange-176"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これについての考え方を少し、前の委員会でも出たかもしれませんけれども、教えてほしいと求めました。１０年になりますけれども、その辺の目安というか、予定がもしあったら説明を求めました。","respondent":"黒田人事課長、品川財政課長","answer":"都市部と地方ということで違いもありますけれども、そういったところで、職員に周知してまいりたいというふうに思っております。現在も要請がありますので、そういった中では… 他の自治体でいろいろと行っているところで、区としてもいろいろなところでできないかというところは検討しています。こういったところも考慮しながら、うまく歳入確保できないかどうかというところは、今後もまた検討していきたいと…","id":"exchange-177"},{"speaker":"たけうち委員","kind":"質問","question":"品川区がそれをしっかりとまとめて、引き続き継続されるということなので、ぜひそこは何かの形でまたお聞きしていきたいと思います。いろいろなお考えをお持ちの方もいらっしゃる、そういったことも１つの考えかなと思うのですけれども、一応お聞きしたいと思います。","respondent":"鈴木都市計画課長","answer":"コミュニティバスということですので、私のほうからお答えしますが、導入にあたって他区の事例についていろいろヒアリング等も行ってきております。正にその辺りも検討していくことになるのですが、そうした視点も踏まえながら、来年度検討していきたいというふうに考えてありま…","id":"exchange-178"},{"speaker":"たけうち委員","kind":"質問・要望","question":"恐らく東京の中ではあまりないのかもしれないですけれども、結構地方へ行くと、もうそういう形でやっているところがたくさんありますので、ぜひそこは検討してと、要望だけしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-179"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は、５２ページ、森林環境譲与税についてお伺いをしたいと考えています。例えば校外学習とか、環境交流ツアーみたいな、都市部の人は理解を求めるためにいろいろやってくださいということが一応書かれているわけであります。","respondent":"品川財政課長","answer":"令和３年度予算は３,２００万円程度、活用見込みとして、児童相談所での間伐材の利用というところがあります。そういった部分も見ながら、今後の森林環境譲与税の活用方法については考えていきたいと、このように思っております。","id":"exchange-180"},{"speaker":"石田（秀）委員","kind":"意見","question":"シルバーセンターとかいろいろ出ているけれども、これは、目指してほしいのです。そこの部分にお金を使っていくと言ったら、多分これを１つの項目にして、そこの意気込みだけ聞いて終わりにしますとの意見を述べました。","respondent":"品川財政課長","answer":"電気をとにかくあまり使わない方法を考えていたというところですが、近年、こういった環境対策をやっていこうというような動きがあると思います。よりよい省エネ、創エネができるような建物を築いていきたいと、このように考えております。","id":"exchange-181"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/309623?Template=document&Id=1128#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":124102,"voices":425}},{"id":"r03-20210303-10","meetingId":"r03-cm03","date":"2021年3月3日","dateIso":"2021-03-03","committee":"議会運営委員会","time":"午後 ６時０５分～午後 ６時１１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/861371?Template=document&Id=5402#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":2238,"voices":15}},{"id":"r03-20210305-3","meetingId":"r03-c-budget","date":"2021年3月5日","dateIso":"2021-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０８分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を192件整理しています。","topics":[{"id":"topic-01","title":"予算特別委員会","agenda":"予算特別委員会","exchanges":[{"speaker":"湯澤委員","kind":"質問","question":"私からは１６５ページ、ホームページ等経費、それから１７１ページ、成人式経費について質問します。リニューアルを行った経緯と、どのようなところを変更したのか、説明を求めました。","respondent":"大澤広報広聴課長","answer":"大きな変更点といたしましては、まず画面表示を遅くしていたＳＮＳの埋め込みを廃止しまして、リンクで対応するようにしております。２点目としましては、緊急情報バナーを自由に編集できる仕様に変更しまして、即時対応を可能として、一目で緊急の内容が分かるようにしておりま…","id":"exchange-001"},{"speaker":"湯澤委員","kind":"質問","question":"スマホでも見やすい、そういったホームページの作成が、ほかの自治体でも様々な角度からリニューアルされているかと思います。リニューアルした際に、区民から寄せられたうれしいご意見や厳しいご意見、そのようなものが寄せられていれば説明を求めました。","respondent":"大澤広報広聴課長","answer":"区民の反応ですけれども、やはりスマホで見るときに大変に見やすくなったというお声はいただいております。リニューアルしたことでの苦情は、今のところ特にいただいておりません。","id":"exchange-002"},{"speaker":"湯澤委員","kind":"質問・要望","question":"一方、品川区民がホームページを開くときには明確な目的があって、その目的地に早くたどり着きたいということが求められていると思います。どういったところに重きを置いて、何を強く発信していきたいと考えているか、説明を求めました。","respondent":"大澤広報広聴課長","answer":"ホームページでお伝えしたいことは、まず第一にはやはり緊急情報、重要な情報をより分かりやすく区民の方にお伝えしたいという思いがあります。風景も紹介しておりまして、区民にも区外の方にも、品川区に関心を持っていただければというふうに考えてあります。","id":"exchange-003"},{"speaker":"湯澤委員","kind":"質問","question":"総合案内をしてくれるチャットボットがないのですけれども、それは何か理由があってのことでしょうか。それと、それぞれのチャットボットで文字の大きさや入力のスペースなど、雰囲気が違うように思うのですが、これは製作元が違うのか尋ねました。","respondent":"山本情報推進課長","answer":"総合案内のチャットボットも含めまして、どういった形で運用すれば利用しやすいものになるか、引き続き検討していきたいというふうに考えてあります。現時点では初期設定という形になってありますので、今後デザインや文字の大きさなど…","id":"exchange-004"},{"speaker":"湯澤委員","kind":"質問・要望","question":"職場の仕事の軽減も導入目的の１つだと思いますが、ＡＩチャットボットであるために、それともプログラマーの方が定期的に更新をしていくものなのか。このチャットボットは、多言語にも対応しているのかも教えてほしいと求めました。","respondent":"山本情報推進課長","answer":"電話対応の件数ですが、現時点では目に見えて実感できるほどの電話対応件数が減っているというわけではございませんけれども。それから多言語対応についてですが、現在は委託している事業者のサービスでは対応ができないというところなので、今後の検討課題とします。","id":"exchange-005"},{"speaker":"湯澤委員","kind":"質問・要望","question":"ＬＩＮＥの国内利用者数は２０２０年時点で８,６００万人を超えているということで、特に災害等の緊急時に大きな役割を果たすと思います。そこで、現在の登録者数と、これまでの成果や見えてきた課題、また、最終的に目指したい登録者数などがあれば教えてほしいと求めました。","respondent":"大澤広報広聴課長","answer":"ＬＩＮＥの登録者数ですが、現時点で５,７４５ということで、始めてから毎月大体１０％ぐらいずつ増えております。やはりまだまだの数だと考えていますので、今後も周知に努めて、そちらのほうに持っていけるように努力してまいりたいと考えております。","id":"exchange-006"},{"speaker":"湯澤委員","kind":"質問・要望","question":"次に、成人式経費についてお伺いいたします。記念品の追加購入分の費用や郵便代、そういった追加経費は幾らで、どこから捻出しているのかを教えてほしいと求めました。","respondent":"立川総務課長","answer":"記念品につきましては、当日参加された方に配付するということで、新成人の人数の大体５０％ぐらいを見込んで発注しています。経費につきましては、総務課の成人式の事業の残額、あと総務課の他の事業での残額、そちらのほうを充てまして用意したところです。","id":"exchange-007"},{"speaker":"湯澤委員","kind":"質問・要望","question":"最後の質問になりますけれども、今後の成人式ですが、新型コロナウイルス感染症が収束、今、期待されつつも、これからどうなるかはまだ分かりません。来年も今年同様、ぜひリアル開催に向けてできる限りの準備をしていただきたいと考えていますが、区の方針をお聞かせ願えればと思います。","respondent":"立川総務課長","answer":"国、東京都から要請がありましたので、泣く泣く中止をしたところです。やはりこういった状況が継続する可能性もありますけれども、今年以上に積極的に開催の方向で取り組んでいきたいというふうに考えております。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"私からは１６３ページ、指定管理者モニタリング、１６９ページ、ＡＩツール運用等経費、１９１ページ、総合区民会館運営費から質問をします。こうした選定情報については、何をどこまで我々議会、ひいては区民へ公表されるのか、現行の規定を改めて説明を求めました。","respondent":"佐藤企画調整課長","answer":"委員構成や応募事業者名、選定理由などの選定結果、また会議録を公表するものとしております。ただ、選定委員会での率直な意見交換や、応募団体の営業・技術・信用の保護等に配慮するものということで、ただし書を規定しています。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"率直に言って品川区は、ちょっと点数など、そういった情報が少ないのではないかと思います。さらに高めていただくためにも、公表項目を増やすべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"評価項目と配点、また実際の点数、あと企画書等に相違があると認識をしております。落選した事業者名が特定される場合も考えられるため、今、その辺を見極めて検討しています。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問","question":"厚生委員会や歳入の審議であえて伺いましたように、報道に関する委員の率直な意見の交換というのですか、意見が。やはり指定管理選考に関わる透明性を高めるためにも、いま一歩情報公開を進めるべきだと思いますが、もう一度ご答弁をお願いします。","respondent":"佐藤企画調整課長","answer":"公平性を遵守して実施しておりますが、より透明性を高めるために、選定に関わる情報の公開は必要だと考えております。委員ご指摘のとおり、事業者の営業・信用等の保護に配慮しつつ、公表する項目や内容について、さらに検討を進めてまいりたいと考えております。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"板橋区などでは昨年３月にその運用指針を改訂しまして、その改訂内容のトップに、ＳＤＧｓの視点を基本理念の重点化として導入としています。むしろ公の施設としては健全だと思うのですが、この点、区のご見解はいかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"この間、区といたしましては、指定管理者制度の改正についても様々検討してまいりました。その項目の１つといたしまして、公募によらず指定管理者を選定する場合の回数制限というものを今検討しています。","id":"exchange-012"},{"speaker":"あくつ委員","kind":"質問・要望","question":"任期つきのＣＩＯ補佐官に民間人を任期つき非常職職員として登用したり、専門業者に委託することを検討したらいかがですかという質問をしました。このデジタル・トランスフォーメーションに対応する人材ということでよいのかどうか確認をさせてください。","respondent":"山本情報推進課長","answer":"ここ数年、ほかの自治体も見ますと、外部人材の活用はかなり増えてきているというように認識しています。力を入れてまいりますが、どういった形で活用していくことが最適なのかを今検討していますけれども、引き続き検討を進めします。","id":"exchange-013"},{"speaker":"あくつ委員","kind":"提案","question":"品川区の職員にそのようなスキルがないとおっしゃっているのですかというような、やゆをしているのですか的な感じで言われたのですけれども。このような流れになっているのですけれども、原則、これはこのとおりでいいのかどうか伺いますとの意見を述べました。","respondent":"古巻文化観光課長","answer":"総合区民会館の運営に関してのご質問ですけれども、原則としましては、委員からご指摘のあったとおり、今、ホームページでご案内しているようなやり方で、来館をしていただいて諸手続きをしていただく、お金の支払いもしていただくといった流れになってあります。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"確認","question":"本人確認書類のみは、郵送やファックスで提出が必要ですと。きゅりあんはいよいよ大規模改修に入るのですけれども、こうしたことについての検討は進んでいるのかどうか、伺いたいと思います。","respondent":"古巻文化観光課長","answer":"その辺りは品川文化振興事業団と同様ですけれども、課題として認識をしております。オンライン決済等が進んでいる時代ですので、今後の課題として認識して、検討を進めてまいりたいというふうに考えてあります。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そのような声が上がっているというように品川文化振興事業団の方もおっしゃっていましたので、これはぜひ全体的に進めていただきたいということで、最後に要望して終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"松澤委員","kind":"質問","question":"１８５ページ、１９９ページ、品川区独自ボランティア「しな助」について質問いたします。そこで、最近の犯罪の傾向や動向などをご説明いただけますか尋ねました。","respondent":"黛生活安全担当課長","answer":"被害件数が９０件で、こちらも令和元年に比べて３９件減少しているということで、比較的良好な治安状況が保てているものと考えております。昨年、１,４００万円をだまし取られるという事案も発生しておりまして、依然として厳しい状態にあるものと認識しています。","id":"exchange-017"},{"speaker":"松澤委員","kind":"質問・要望","question":"昨年も質問いたしましたが、抑止効果の高い自動通話録音機を増やしてほしいとの要望に、努力していますが難しいとのご答弁がありました。この新型自動通話録音機が導入に至った経緯と、仕組みについてご説明をお願いいたします。","respondent":"黛生活安全担当課長","answer":"しかしながら、この効果がいつまで続くのかが、なかなか難しいというふうに考えております。万一の際は、私どもや警察からもご本人様に注意喚起を行うという独自のスキームをつくって運用していく予定です。","id":"exchange-018"},{"speaker":"松澤委員","kind":"質問","question":"今、１つ気になったのですが、生活安全担当に通話が行くとするではないですか。そうすると、逆にその電話が、詐欺かなと思われたりしないのかとふと思ったのですけれども、そのような観点はいかがか尋ねました。","respondent":"黛生活安全担当課長","answer":"そのようなことも十分考えられると思います。まさに警察に、さらにバックアップ体制として入っていただいて、必ずその方の安全が確認できるようなスキームを構築してまいりたいと考えています。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"この新型自動通話録音機ですが、これは国や都からの助成金事業ではないのでしょうか。特殊詐欺犯がよく使う用語を学習されると先ほどお聞きしましたが、応用して、そのような活用ができるか等が分かりましたらお願いします。","respondent":"黛生活安全担当課長","answer":"しかしながら、必ずやこの有効性を実証いたしまして、補助の対象となるように担当として努めてまいりたいと考えております。現状直ちにということは、非常に難しいところはあるのかなというふうに考えておりますが、調査・研究をさせていただきたいと考えております。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問","question":"どのようなプランに加入して、また、このアカウントを取得する際にどれくらい時間がかかるのでしょうか。説明を求めました。","respondent":"大澤広報広聴課長","answer":"品川区では、月額の固定費は無料となっておりまして、無料で送れるメッセージについても制限なしという契約になってあります。こちらのアカウントの取得までは、やはりＬＩＮＥ株式会社とのやり取りがございましたので、数か月かかっております。","id":"exchange-021"},{"speaker":"松澤委員","kind":"質問","question":"例えば各町会長が集まる区政協力委員会の会議など、そういったところでのご案内、また、高齢者クラブへのご案内などを個別に行っているのでしょうか。説明を求めました。","respondent":"大澤広報広聴課長","answer":"ＬＩＮＥの周知につきましては、これまで広報紙やホームページ等での周知が主でございましたので、引き続き従来の媒体を活用するとともに、委員のご提案にありましたような、ピンポイントでの周知というものも、今後検討してまいりたいと考えています。","id":"exchange-022","title":"町会・自治会支援"},{"speaker":"松澤委員","kind":"質問・要望","question":"ホームページと違い、ＬＩＮＥは、やはり区民がどの情報を求めるか、そのようなところにピンポイントで配信できる強みがあるかなと考えています。そういった視点で、どのような方向性を考えているのか、ご見解を説明を求めました。","respondent":"大澤広報広聴課長","answer":"次にＹｏｕＴｕｂｅの配信ですが、これまでも実績がありますので、より有効な動画を配信するように、積極的に努めてまいりたいと考えています。登録者の属性や希望によるセグメント配信を実施しておりますので…","id":"exchange-023"},{"speaker":"松澤委員","kind":"提案","question":"そこでＬＩＮＥの活用や拡充の方法として、１点だけ提案します。情報格差を少なくする取組、情報発信の拡充という部分において、ご見解を説明を求めました。","respondent":"大澤広報広聴課長","answer":"今のところ区からの貸出しは考えておりませんが、必要だと認識しておりますので、どのような方法が有効か検討してまいりたいと思います。情報格差ですが、ＬＩＮＥ等の新しい媒体と同時に、これまでの紙媒体での周知というものも…","id":"exchange-024"},{"speaker":"松澤委員","kind":"質問","question":"度々の質問になってしまいますが、東京２０２０大会のためにつくられましたけれども、本当にすばらしいレガシー施策だと考えています。そのようなものの案内、ワークショップなどをしっかり周知することも可能だと思いますが、ご答弁。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"「しな助」に関しましては、東京２０２０大会に向けてボランティアを募集しておりますので、この終了後は一旦解散する予定です。その中のツールの１つとして、ＬＩＮＥも活用するということは考えられるかなと考えていますので、今後はいろいろ検討していきたいと考えています。","id":"exchange-025"},{"speaker":"松澤委員","kind":"質問・要望","question":"ぜひこの品川区独自の、本当にすばらしいボランティアレガシーを残してほしいと求めました。これがピンポイントに伝わり、品川区のこのＬＩＮＥが行政と区民をつなぐ新しいネットワークの中心になるように要望して、質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"１７３ページの男女共同参画推進事業より、１９９ページのオリンピック・パラリンピック開催周知事業より、それぞれ伺いたいと思います。そこで今回の女性蔑視発言に対し、なぜここまで多くの方が声を上げたと思うのか、区の見解を伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"区は、人権尊重都市品川を宣言しております。マイセルフ品川プランを進めている中で、とても残念な発言だったと思いますし、一層推進を進めてまいりたいと考えているところです。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"これまで組織の中で、また社会や家庭の中で、どれだけ女性は口を出すなという言葉が繰り返されてきたでしょうか。改めて、森前会長の発言は明らかに女性蔑視であり、社会のあらゆる場面で克服されるべきだと思いますが、改めていかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"残念ながら今年度ですが、コロナ禍の影響で開催することができませんでしたけれども、また新たな委員を募集しています。一層推進してまいりたいと考えているところです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ一層推進いただきたいと考えていますし、この根強い差別を克服する、この取組を力強く進めてほしいと求めました。改めてこれは性差別だと、女性差別だと私は思いますが、この点ははっきりとご答弁ほしいと求めました。","respondent":"島袋人権啓発課長","answer":"あるいは能力を発揮できる社会が重要ということで、やはりしっかりと全ての区民の方にジェンダー平等意識を持っていただけるように、推進してまいりたいと考えているところです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひジェンダー平等の意識の醸成をより進めてほしいと求めましたし、女性蔑視だとしっかりと発言していただきたいと考えています。日常のあらゆる場面での克服が一層広がっていると思いますが、同じ角度の質問にはなりますけれども、ご見解を伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"あるいは、成長のエネルギーにしてきたという今までの積み重ねがあるかと思います。様々な機会を捉えて推進をしていくことが重要だと思いますし、それをすることが人権尊重都市品川を一層進めることにつながると考えております。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかし、新型コロナウイルス感染症が世界中に広がる中、開催中止を求める声は、日本だけではなく各国に広がっております。そこで、安全・安心とはどのような条件が整う場合を指すのか、その基準を伺いたいと思います。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京２０２０大会を安全・安心に開くということの協議を東京都、その中で安全・安心は一体どのような基準があるかというようなご質問かと思います。そもそも東京２０２０大会に向けた東京都安全・安心推進会議というものを東京都でやっておりまして…","id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"今のお話ですと、健康の維持、あと社会の安定が維持されない下では、東京２０２０大会は開催すべきではないと。私はそう思うのですけれども、品川区はいかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、社会機能が維持された状態を目指すために、その状態で開けるように、今、順次準備を重ねているところです。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"選手間のフェアな環境が整わず、安全・安心もないままに開催が前提ということは改めるべきだと思います。改めて今年夏の東京２０２０大会の開催中止を品川区として求めていただくよう要望して、終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問","question":"１６９ページ、１７３ページ、男女共同参画推進事業についてお伺いいたします。少なくとも私はあまり知らなかったのですが、どのような方法で周知をされていたのか尋ねました。","respondent":"古巻文化観光課長","answer":"ちょっといろいろなタイミング等も図りながら進めていたところですが、大森の映画館になりますけれども、そちらでマスコミに対して広報した経緯です。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"今後はもっともっと伝わる周知やＰＲをしていっていただきたいと考えています。ではこの１１か所のロケーション、伝わる周知をしていただきたいのですけれども、その点のお考えはいかがか尋ねました。","respondent":"古巻文化観光課長","answer":"３月の上旬までは都内の映画館、４館になりますが、ロケ地マップの配布もしておりました。今後につきましては、ＹｏｕＴｕｂｅ等へ掲載、登録をさせていただいて、しなロケのホームページでも紹介をしていきたい、このように考えてあります。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問","question":"その広報しながわについてお伺いしますけれども、新聞を取っていない方には届かないということで、それで広報力が落ちてしまうのかなと。これ、私も、ほかの委員の方も結構定期的におっしゃっていることなのですけれども、今後の新聞購読者減に伴う対応はいかがお考えなのか尋ねました。","respondent":"大澤広報広聴課長","answer":"令和３年度からスポーツ紙への折り込みを新たに始める予定がございまして、それを合わせるとこれまでの水準を保てるかと考えています。５００ほどの登録がございまして、月の平均で２,５００件ほどありますので、皆さんに見ていただけるように努めてまいりたいと考えています。","id":"exchange-036"},{"speaker":"筒井委員","kind":"質問","question":"先ほどから話に出ている品川区のＬＩＮＥ公式アカウント、こうしたものも活用していくのも手かなと思います。これは結局、品川区のＬＩＮＥ公式アカウントだよという周知方法も考えられると思うのですけれども、そうしたことをいかがお考えか尋ねました。","respondent":"大澤広報広聴課長","answer":"現在広報紙の発行日には、引き続きＬＩＮＥも含めて、ＳＮＳでの周知も図ってまいりたいと考えています。ＬＩＮＥ公式アカウントにつきましては、委員のご提案も含めまして、できるだけ様々な方法で周知に努めてまいります。","id":"exchange-037"},{"speaker":"筒井委員","kind":"質問・要望","question":"よろしくお願いします。残りの２７０度、ぜひ拡張していただきたいのですけれども、その点いかがお考えか尋ねました。","respondent":"山本情報推進課長","answer":"設置しているアンテナの性能で決まっておりまして、今、利用しているのが最大で７０ｍ程度となっています。ケーブルの敷設工事等が必要になりまして、設置できる場所というものはかなり限定されておりますので、今のところ増設が難しいという現状です。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"１つ気になったのが公園で、品川区の観光の１つの名所となっておりますし、しなロケにも掲載されている公園です。ぜひ池田山公園にもＷｉ－Ｆｉを設置していただきたいのですけれども、その点についていかがお考えか尋ねました。","respondent":"山本情報推進課長","answer":"公園での整備についてですが、今、災害時の通信手段の確保という観点から広域避難場所等、あとは大規模な公園にＷｉ－Ｆｉを整備しています。池田山公園は、観光地として非常に人気があるスポットというふうには考えてありますので、関係課とともに考えていきたいと思ってありま…","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"いわゆる同性パートナーシップ制度についてお伺いしたいと思うのですけれども、その足立区でも令和３年度から同性パートナーシップ制度を導入されるということなのですけれども、ご検討というものはされているのか尋ねました。","respondent":"島袋人権啓発課長","answer":"同性カップルについての婚姻に相当する行政証明、いわゆるパートナーシップ制度ですが、これは各自治体によって対応が異なっているところです。この中でどのような報告が上がってくるか、またその報告を鑑みながら、検討を進めてまいりたいと考えているところです。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"私もそのＬＧＢＴ当事者の方が知り合いでおりますけれども、やはり「品川区に、なぜ同性パートナーシップ制度がないのだ。そうした会議や有識者の方のお声など聞いて、ぜひそうした制度の導入の検討をしていっていただきたいと思うのですが、その点いかがお考えか尋ねました。","respondent":"島袋人権啓発課長","answer":"この１２月に品川区職員・教職員向け性自認・性的指向に関する行動指針を作成しまして、ホームページ上でも公開しています。一層の理解推進が進んだ中で、検討してまいりたいと考えているところがあります。","id":"exchange-041"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ議員からの事前要望には応えていただきたいのですが、いかがでしょう。委託業者の問題なのか、その辺について伺います。","respondent":"品川財政課長、中山会計管理者","answer":"前年度の業者から、今年度、業者を替えてしまったというところがございました。公会計レポートは、作成を急いでいるところですので、一刻も早く出していきたいというふうに考えております。 現在ホームページに、各会計別の財務諸表、それから注記につきましては、合算分の注記ということで載せております。概要版も作成いたしまして、そちらも併せて載せておりますので、ご覧いただければと考えています。","id":"exchange-042"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えばこのような資料も欲しいという要望には応えていただきたいと思うのですが、その点についてお答えがなかったので、もう一度伺います。この審議会の結論も尊重されるべきと考えますが、見解を伺います。","respondent":"中山会計管理者、大澤広報広聴課長","answer":"注記につきましては、来年度の決算、令和２年度の決算のときに併せて、しっかり財務諸表と出せるようにしていきたいと考えております。よろしくお願いします。 実施機関に公開の請求をした場合、請求を受けた実施機関は、原則として公開する規定となっています。画一的な対応は難しく、資料の作成について、情報公開制度として規定するのは難しい部分があります。","id":"exchange-043"},{"speaker":"吉田委員","kind":"提案","question":"区として公開できる内容の文書を、区民に対する説明の文書を用意してほしいと求めましたが、もう一度見解を伺いたいと思います。それから３か国語対応の表示、その他１０言語対応可能という表示があるとベストだと考えますが、いかがか尋ねました。","respondent":"大澤広報広聴課長、山本情報推進課長","answer":"情報公開に関してですが、広報広聴課には、各所管から様々相談がありますので、ケースに応じて丁寧に対応していきながら、制度の趣旨を伝えてまいりたいと考えています。 窓口でのサービスのご案内ですが、こちらは各窓口に掲示するよう対応しています。１３言語対応ということで、１３言語でサービスができますというところをご案内しているということと、あと手話マーク等々も記載をしています。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問・要望","question":"それからタブレットですが、昨年の決算特別委員会の後、表示がないから早く表示してくださいというように求めました。拡充は評価したいと思いますけれども、前年の成果、あわせて次年度の意気込みなどを伺いたいと思います。","respondent":"山本情報推進課長、島袋人権啓発課長","answer":"通訳タブレットの掲示ですが、繰り返しの答弁になりますけれども、こちらのほうはもう既に窓口に掲示をしていると認識しています。その際には障害者福祉団体にも、内容は確認をしてもらっているところです。 今年度実施しました１２月１２日分は、応募者１０名、参加者６名でございました。今後は、令和３年度ですけれども、自主グループ活動につなげることを主な目的として、アライも対象とした内容にしていきたいと考えているところです。","id":"exchange-045"},{"speaker":"吉田委員","kind":"確認","question":"簡易型プロボーザル方式要領についている想定業務仕様を確認しましたけれども、基本構想検討だけでも６項目にわたって相当な内容です。少し急ぎ過ぎではないかと思いますが、見解を伺います。","respondent":"濱中庁舎計画担当課長","answer":"私から新庁舎整備の進め方について、ご説明を差し上げたいと考えています。これまで様々な庁舎機能検討委員会の議論であったりですとか、庁内での議論を重ねてまいりましたので、９月には答申をいただきたいと考えています。","id":"exchange-046"},{"speaker":"木村委員","kind":"質問・要望","question":"私からは１６３ページの上から４行目、しながわテレビ・プッシュ普及促進事業、１７５万円余からです。なぜこの名前を使用したのか、私的には「えっ」と思いましたが、特別な意味があれば教えてほしいと求めました。","respondent":"佐藤企画調整課長","answer":"緊急度の高い情報については、自動的に立ち上がってお知らせするというところでプッシュというような表現を使っていると捉えております。それ以外にも、電車の運行情報でございましたり、自治体が発信する生活情報等もお知らせする、幅広いサービスとなっております。","id":"exchange-047"},{"speaker":"木村委員","kind":"質問","question":"これといった的確なあれはなかったのですけれども、面白さを選んだというようなことであろうと思います。ＦＭしながわ広報番組制作費１,２００万円ですが、品川区の専門チャンネルではなく、時間帯を使用しているということでよろしいのか尋ねました。","respondent":"大澤広報広聴課長","answer":"夜１０時、２２時から３０分間の枠で、区の広報番組を流しています。その経費です。","id":"exchange-048"},{"speaker":"木村委員","kind":"意見","question":"年間の使用料が１,２００万円ということですが、失礼な言い方ですけれども、どれだけの価値があるのかなと、このように思います。お答えくださいとの意見を述べました。","respondent":"大澤広報広聴課長","answer":"ＦＭしながわの役割ですが、まず第一には、災害時に避難情報や被害情報を発信できるということで考えております。感染症予防について区長のメッセージを放送したときには、一定のリスナーの方からの評価はいただいているというふうに考えてあります。","id":"exchange-049"},{"speaker":"木村委員","kind":"質問・要望","question":"品川区はこのような区なのだと、品川区のよさをアピールするための手段と考えますけれども、それでよろしいのかどうか。そしてまた、これからもこの番組を長く続けてほしいと求めましたけれども、お願いをしたいと思います。","respondent":"大澤広報広聴課長","answer":"番組の中では、教育長が出演して品川区の教育制度の説明などもしております。そのようなことも含めて、区外の方にも番組を聞いていただいているようですので、区の情報発信という役割を今後も果たしてまいりたいと考えています。","id":"exchange-050"},{"speaker":"木村委員","kind":"質問","question":"年間１,２００万円の費用でありますが、妥当とお考えでしょうか。説明を求めました。","respondent":"大澤広報広聴課長","answer":"１,２００万円の内訳ですけれども、制作費として約４万６,０００円の２６０日分ということで計上しています。こちらの金額は妥当な金額というふうに考えてあります。","id":"exchange-051"},{"speaker":"木村委員","kind":"質問","question":"次に１６７ページの上から２行目、今品川区には約五、六千名ほどの外国人が住んでいるということをお聞きいたしました。それとも視聴率は関係なく、品川区のことをできるだけよく知ってもらうためにこの放送を流しているということか尋ねました。","respondent":"大澤広報広聴課長","answer":"インターＦＭの内容につきましては、広報紙の情報を中心に区からのお知らせということで、英語、中国、韓国語、タガログ語で流しております。ラジオは視聴率が取れませんので、それへのアクセスが月８,６００件ありますので、ある程度の参考になるかと考えています。","id":"exchange-052"},{"speaker":"木村委員","kind":"質問","question":"聞くところによりますと、小学生のほとんどはこの曲を知っているともお聞きをいたしました。これは音楽の授業などで使用しているということでよろしいのかどうか、そこのところを説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"松本委員","kind":"質問・要望","question":"時間が間に合えば１８３ページ、１８５ページ、生活安全推進事業について伺います。啓発というように言っているわけですから、オリンピック憲章の理念を盛り込んでいくべきだと考えますが、区の見解をお願いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"文化事業をやるとき、または教育の場、あらゆる場でオリンピック憲章というのは有効に活用することができる内容だというふうに認識しております。オリンピック・パラリンピック教育はもちろんやっておりますし、その中で…","id":"exchange-054"},{"speaker":"松本委員","kind":"提案","question":"様々な委員から提案がありますので、１つ申し上げたいと思うのが、オンラインショー型の花火「レッツゴー万博２０２５」が開かれる予定です。ドローン活用に積極的な品川区だからこそ、こういったドローンを活用したイベントを検討されてもいいのではないかと思いますが、いかがか尋ねました。","respondent":"古巻文化観光課長","answer":"近年かなり進歩が目覚ましいのかなというふうに考えておりますし、使用するシーンも増えてきているなということで、関心は持っているところです。うまく活用していくことも１つの発信の手段かなというふうに考えますので、十分に研究してまいりたいなと、そのように考えておりま…","id":"exchange-055"},{"speaker":"松本委員","kind":"質問","question":"２月７日に、報道によっては３,０００人ぐらい人が集まったのではないかというようなデモがありました。抗議デモで既に５０名程度ですか、その安全面での対応がどうなっているのか、お願いいたします。","respondent":"宮澤協働・国際担当課長、黛生活安全担当課長","answer":"ミャンマー大使館の件です。デモ等が行われていることは把握しておりますが、その件についての大使館との連絡等はしておりません。 本件につきましては、所轄の品川警察署と情報を共有し、的確に対応してまいります。","id":"exchange-056"},{"speaker":"松本委員","kind":"意見","question":"これからまたいろいろと活発になる可能性があるので、ご留意ほしいと求めました。過去のデータを見るとミャンマーご出身の方が２００人以上いらっしゃるということで、こちらにまた、しっかりとご対応ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"芹澤委員","kind":"質問","question":"私からは１９８ページ、オリンピック・パラリンピック開催周知事業についてお伺いいたします。全力を挙げてできる限り尽くすということが、まず我々の役割だと思いますけれども、初めにそれについてご見解を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"聖火リレーをどのように安全に実施することができるかということで、新型コロナウイルス感染症の状況も見ながら実施するというふうに聞いております。一番の大事なことだと考えていますので、議会の皆様や区民の皆様、開催の形をしっかりつくっていきたいと思っているところです。","id":"exchange-058"},{"speaker":"芹澤委員","kind":"質問","question":"今民間サイトで、東京２０２０大会だけではなくて、五輪の無料のストリーミングサイトというものが幾つかあると伺っています。子どもたちや大人全員が、みんなで一斉に区内競技を応援するという仕組みづくりを検討されてはと思いますが、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"１つはパブリックビューイングという大きな画面で見るものに関しては、学校でテレビを使ってみんなで見ようとか、そういったことは可能かと思います。委員ご指摘のとおり、やはり放映権の関係がございまして、多少難しいところがあるかなというふうな認識です。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"質問・要望","question":"レガシーについても伺います。「しな助」では、今年どういった事業を行う予定なのかも説明を求めました。","respondent":"中元スポーツ推進課長、辻オリンピック・パラリンピック準備課長","answer":"東京２０２０大会後のレガシーの障害者スポーツの予算の枠組みですが、１９５ページのほうに障害者スポーツの充実という項目がありますので、そちらに入ってくる可能性が高いかと思われます。 来年度は、年度が明けましたら、まず大会のときの運営補助に関わっていただく方への説明会等を予定しております。今年度中にオンラインで「しな助」の心構えですとか、ユニバーサルマナー研修などを開く予定です。","id":"exchange-060"},{"speaker":"芹澤委員","kind":"提案","question":"東京２０２０大会が開催される前から予算というものはあったのですから、ぜひより大きな額でレガシーとして残してほしいと求めました。何というか楽天などのショッピングサイトなどだと、利用するとどんどんメルマガが増えていくという感じか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"「しな助」の活動や今後の展開方法については、柔軟にいろいろな方面で展開していきたいと考えています。","id":"exchange-061"},{"speaker":"新妻委員","kind":"質問","question":"１７８ページ、そして２０３ページ、順不同で伺ってまいります。このことについて、なぜなのか、まずお伺いいたします。","respondent":"川島地域活動課長","answer":"令和２年度につきまして、それからイベントが飲食を伴うということで、今年度の事業は中止しています。こちら、コロナ禍の終息の見込みが立たないというところもございまして、令和３年度の予算要求は休止という形で、予算要求していないというものです。","id":"exchange-062"},{"speaker":"新妻委員","kind":"提案","question":"コロナ禍であればこそ、できるやり方というものを提案していただくのが事業者ではと考えています。このような中だからこそ、行政の支援というものが非常に大事だと考えておりますが、見解を伺いますとの意見を述べました。","respondent":"川島地域活動課長","answer":"オンライン開催だと、品川区がやる意味がないのではないかということも含めて、今回予算要求を見送ったです。ほかの自治体でやっている様々な手法ですとかを、事例収集などをしながら、新しい企画の研究もしていきたいというふうに考えてあります。","id":"exchange-063"},{"speaker":"新妻委員","kind":"質問・要望","question":"続いて、ＬＩＮＥ公式アカウント運用と在住外国人向けのＬＩＮＥ情報発信について、一緒に伺わせていただきます。午前中の質疑の中で、このＬＩＮＥの件は多々確認をさせていただきました、もう少しまだ登録者の人数を増やす余地があるというお話も伺いました。","respondent":"大澤広報広聴課長、宮澤協働・国際担当課長","answer":"ＬＩＮＥの登録数につきまして、全体を調査してはございませんけれども、活用がかなり進んでいると言われている渋谷区では、今２万を超えていると聞いておりますので、品川区も目標にして頑張っていきたいと考えています。 在住外国人向けのＬＩＮＥの情報発信についてお答えいたします。こちらは品川区の公式アカウントとは別に、やさしい日本語、また英語で配信するためのアカウントを取得して、情報を配信していく予定です。","id":"exchange-064"},{"speaker":"新妻委員","kind":"確認","question":"やさしい日本語、また英語ということは、英語がまず前提であって、そこから多言語も検討されるのでしょうか。品川区には約１万３,０００人ちょっとの在住外国人がいらっしゃると思いますが、英語がベースであったとしても、いかがか尋ねました。","respondent":"宮澤協働・国際担当課長","answer":"在住外国人向けのＬＩＮＥの発信におきまして、やさしい日本語、英語で発信していきます。配信していく中で、登録者数、また、ニーズ等を検討しながら、考えていきたいと考えております。","id":"exchange-065"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、次に住民異動届書作成ツール利用料について、確認、お伺いをします。昨年の９月から運用開始されて、本格運用がこの２月からということでよろしいか尋ねました。","respondent":"木村戸籍住民課長","answer":"２月の利用ですが、合計で約１００件、１日５件程度ご利用いただいているところです。お引っ越しに伴う届けで活用されているというところでございまして、こちらの意図がうまく伝わったのかなというふうに評価しております。","id":"exchange-066"},{"speaker":"新妻委員","kind":"質問","question":"４月は、一層活用いただけますように周知をお願いしたいと思いますが、ちょっとどのような機械なのかがやはり分かりにくいなと思っています。このような中でも、ぜひこのような高齢者の皆様にもアピールをしていただくということも１つの周知になると思いますが、いかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"今、委員からご指摘のありましたことも踏まえまして、アピール強化、関係課と連携して進めたいと思います。","id":"exchange-067"},{"speaker":"新妻委員","kind":"確認","question":"午前中にも参加状況等の確認をさせていただきました。先ほどからもお伺いしておりますが、今後の具体的な取組をもう少し詳しく説明を求めました。","respondent":"島袋人権啓発課長","answer":"こちらは、今年度実施しました２回と同じく、令和３年度も２回予定しています。先ほどありましたように、アライの方も含めてもっともっと広めていくように、そしていろいろな年代の方々が参加できるような形で進めてまいります。","id":"exchange-068"},{"speaker":"横山委員","kind":"質問・要望","question":"分かりやすく載せていただきたいと要望いたしますが、区のご見解をお聞かせください。３点目ですが、文化活動支援事業についてお伺いいたします。","respondent":"島袋人権啓発課長、川島地域活動課長、古巻文化観光課長","answer":"関係各課との連携を進めているところでございまして、件数等が上がってきているといった報告はいただいてございません。それと女性の人権に関する問題… 社会を明るくする運動につきましては、法務省が主唱しております全国運動ということで、啓発活動と、それから青少年の表彰を実施しているものです。… 新型コロナウイルス感染症等の様々な影響によって、なかなか思い切った活動ができないような状況が続いている形になっております。…","id":"exchange-069"},{"speaker":"横山委員","kind":"質問・要望","question":"社会を明るくする運動についてなのですけれども、昨年１０月にドキュメンタリー映画『記憶』の中村すえこ監督にお話を伺いました。４点目なのですけれども、協働推進経費についてお伺いをいたします。","respondent":"川島地域活動課長、宮澤協働・国際担当課長","answer":"今、そうした啓発イベントや、それから機関紙のようなものを作りまして活動したりというようなことをやっております。様々な活動の中に、活動の幅を広げるという意味では有効なことではないかと考えていますが… 区ではＮＰＯをサポートする中間支援団体に相談業務を委託しておりまして、専門的な知識から相談等を受けております。広報戦略であったり、または団体の活動するミッション自体の相談というものも受けていきながら…","id":"exchange-070"},{"speaker":"横山委員","kind":"質問・要望","question":"最後にＩＣＴ推進経費についてお伺いいたします。スマホからの電子申請しかできないような若者たちがいるという状況につきまして、区としてはどのように捉えておられますか尋ねました。","respondent":"山本情報推進課長","answer":"ＩＣＴ化の進め方ですが、確かに年代によって様々、使い方、使う媒体等が変わってくるというふうには考えてあります。区といたしまして、若い方から高齢者の方まで様々活用いただけるよう、デジタル化は推進していきたいというふうに考えてあります。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"策定費から、庁舎の建て替えについて伺いたいと思うのですけれども、庁舎機能検討委員会で議論をされてきました。議論としては、とても不十分だと思っていますけれども、３月の５回目で答申を出して終了ということなのでしょうか、伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"私から、庁舎機能検討委員会の状況と今後の策定委員会について、ご説明差し上げたいと考えています。庁舎機能検討委員会のまとめとして、こちらのほうはホームページ等に掲載いたしまして、区民の意見の聴取をしていきたいと考えています。","id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"新たな庁舎がどうあるべきかということが話し合われるというか、８,３００m2ですが、これが敷地の前提になって検討されている。そして、ＪＲ東日本の開発と一体となっていることなどから、Ｄ案を前提に進めるべきではないということを繰り返し求めてきました。","respondent":"濱中庁舎計画担当課長","answer":"新庁舎の規模ですが、委員から７万m2、８万m2といったご発言がありましたけれども、新庁舎の面積、こちらも今後検討していくようなところです。その中で、高層の場合どういったメリット、デメリットのようなものがあるかということも…","id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"一般質問でも否定していないわけですから。ですので、超高層になることでのメリット、デメリット、これを想定しておくのは当然のことではないかなと思うのですけれども、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"高層の場合と低層の場合といったものを、今後機能の規模を決めていく中で、高層にした場合、低層にした場合、どういったメリット、課題等があるのかというものを、また基本構想や基本計画段階等で専門の業者等の知見を生かしながら、議論をするです。","id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"では、そうしましたら、低層型の庁舎というものも検討されるということでよろしいか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"機能のほうを決めまして、想定規模の面積を決めます。そういった、どのような構造の庁舎になってくるかを検討していくことになります。","id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この大地震のときの、こうした避難イメージ、そうした基準も出ているのでしょうか。伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"今後、面積は検討事項になってくるかと思っています。国土交通省からも、そういったものを見ながら、安全性の高い庁舎を計画していきたいと考えています。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりＤ案という狭い敷地に超高層の庁舎という前提はやめていただいて、区民のための安全な防災の拠点として、しっかり機能する庁舎の建設を強く求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"田中委員","kind":"質問","question":"区民意見の反映やこの２つの業務委託と整合性をつけることを考えると、少しじっくりと進めるべきだと考えますが、見解を伺います。床面積の部分なのですけれども、検証というのは、それとも全てひっくるめてプロポーザルで公募しているのかという部分についてお知らせください。","respondent":"濱中庁舎計画担当課長","answer":"１点目のオフィス環境の調査ですが、そういった検証も含めて、まず検討をしていただきます。基本構想・基本計画の検討委託のほうでも、そういったものも新庁舎整備基本構想・基本計画策定委員会のほうで審議をしていただきたいと考えています。","id":"exchange-078"},{"speaker":"田中委員","kind":"提案","question":"今のご答弁だと、今大体の床面積のことについて、区として提案はしていない。大体もう区としてこのような庁舎をつくりますよといったものがあるのかどうかというところも確認したいのですが、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"現在床面積に関しましては、庁内検討等でどのような機能が必要なのかというところも考えておりまして、そういった議論を進めながら、こうした業者の知見を使って、必要な規模等を算定していきたいと考えております。","id":"exchange-079"},{"speaker":"田中委員","kind":"質問・要望","question":"ということは、まだ全然決まっていないということでいいですか。先日の庁舎機能検討委員会も書面開催でしたし、どうにか区民の方の声が届く、きちんと聴取されて反映される形を求めたいのですが、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"今までの庁内検討のものをベースに、今後、床面積等を算定していただくということを基本構想でやっていきたいと考えています。今回庁舎機能検討委員会で様々議論いただきまして、７つの項目、新庁舎整備基本構想・基本計画策定委員会のほうでも出していきたいと考えています。","id":"exchange-080"},{"speaker":"田中委員","kind":"質問・要望","question":"私たちが求めたいのは、変えられる段階で区民の意見を聞いてほしいということを求めています。そこに対してご答弁いただけたらと思います。","respondent":"濱中庁舎計画担当課長","answer":"区として案をつくらせていただいて、新庁舎整備基本構想・基本計画策定委員会でご審議いただきたいと思っています。区民の意見を募集したものを随時ご提示しながら、そちらを参考に議論を深めていただければと考えております。","id":"exchange-081"},{"speaker":"小芝委員","kind":"確認","question":"初めに、男女共同参画推進事業についてお伺いいたします。まず確認を致したいのですが、この登録団体の数、できればその地域ごとの数について説明を求めました。","respondent":"島袋人権啓発課長","answer":"２月の後半に、４９団体の方々に移転のお知らせをさせていただいたところです。仮移転のことに関してお伝えしましたが、今のところ苦情をいただいている状況はございません。","id":"exchange-082"},{"speaker":"小芝委員","kind":"質問・要望","question":"一般質問の中で質問させていただきました、品川区の中におきます、地域コミュニティの活性化に向けて質問させてほしいと求めました。まず確認をいたしますけれども、町会・自治会の中でオンラインでの交流を行っている団体は大体どのぐらいあると認識されているか、確認をいたします。","respondent":"川島地域活動課長","answer":"リモートの会議を開催しているというお話は聞いているところですが、まだまだ普及というか、活用は進んでいない状況だというように把握しています。","id":"exchange-083","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問","question":"来年度で７年目を迎えますしながわＷｉ－Ｆｉスポット事業を振り返りまして、どのように評価されておりますでしょうか。説明を求めました。","respondent":"山本情報推進課長","answer":"こちらの事業は平成２７年度から、平時における区民の利便性の向上ということを目的に、整備を進めてきたところです。年間で大体１５０万件ほどの利用、昨年度が２２０万件ほどというところで、かなり多くの方にご利用いただけている事業だというふうに考えてあります。","id":"exchange-084"},{"speaker":"小芝委員","kind":"確認","question":"地域の方々とのリモートでの交流、会議にも運用できるのではないかなと考えております。まず確認をいたしますが、仕組みといったものはあるのかどうか、ご答弁をお願いします。","respondent":"川島地域活動課長","answer":"現状、多分その改修費用というのはそれほど高いものではないので、それで使ってしまうとほかの設備改修ができないような場合も出てまいります。ただ、使うことは可能です。","id":"exchange-085"},{"speaker":"小芝委員","kind":"提案","question":"今後もＷｉ－Ｆｉスポットの拡大が進んでくると認識しておりますが、地域コミュニティの中心とも言えます、この町会・自治会会館の中にもネット環境と整えていく、その発端としてこのＷｉ－Ｆｉの整備を提案したいと考えますが、いかがお考えか尋ねました。","respondent":"山本情報推進課長","answer":"ＳＨＩＮＡＧＡＷＡ ＦＲＥＥ Ｗｉ－Ｆｉにつきましては、これまでも人が多く集まる場所を中心に整備を進めてきたところです。関係課、また、区民ニーズ等も捉えながら検討していければと思ってあります。","id":"exchange-086","title":"町会・自治会支援"},{"speaker":"小芝委員","kind":"質問・要望","question":"ぜひ検討してほしいと求めました。今後も地域がつながりますよう、全庁的に取り組んでいただきたいと思いまして、質問を終わらせていただきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"私からは１９９ページ、それから１９１ページ、文化コミュニティ施設経費についてお伺いしていきたいと思います。こういったことについては、どのように協議をされ決定されていくのか、最初にお伺いします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"日本ブラインドサッカー協会のほうもまだプレスリリースをしていない状況ですので、今この場ではっきりとお伝えすることはできない状況です。ウィズコロナの中でも、どのようにして安全に安心して大会をできるかということをきちんと考えているところですので…","id":"exchange-088"},{"speaker":"塚本委員","kind":"意見","question":"ぜひご努力をお願いしたいのですけれども、開催するにあたっては、感染防止対策というものは徹底していくということは当然のことかと思います。ある種すごい対策が取られていたというようなことも１つ参考にしながら、この感染防止対策はどのように考えていらっしゃるのか…","respondent":"辻オリンピック・パラリンピック準備課長","answer":"関係者、前２週間は全て検温やチェックシートを記入していただいて、徹底的に外部との交流に規制をかけて大会に臨むということをしておりました。全豪オープンテニスのときも多分そうだったと思うのですけれども…","id":"exchange-089"},{"speaker":"塚本委員","kind":"質問・要望","question":"どこのシステムを使っているのかを教えていただきたいということと、この振込手数料はどのようなところで発生するのかを教えてください。住民票なら窓口だと３００円でしたか、この辺の手数料は、特に変更があるのかないのか、以上、お伺いしたいと思います。","respondent":"木村戸籍住民課長","answer":"それから前後いたしますけれども、住民票そのもの、戸籍等の手数料は、一切変える予定はございません。内部的なところで発生するお金と考えておるところです。","id":"exchange-090"},{"speaker":"塚本委員","kind":"質問","question":"戸籍住民課のほうは交通系ＩＣカードのＳｕｉｃａ、ＰＡＳＭＯと、それぞれ違う手段を使っております。ここに決め打ちで決めざるを得なかったというか、なぜこのキャッシュレス会社が違っているのかについて、ご説明をお願いします。","respondent":"山本情報推進課長","answer":"まず戸籍住民課のほうは窓口のキャッシュレスということで、利用者数が最も多い交通系のＩＣカードを試験導入したです。窓口のキャッシュレスではなくて納付書払いで、ＱＲコード決済でお支払いいただくという形で、そういった理由でサービスが異なってあります。","id":"exchange-091"},{"speaker":"塚本委員","kind":"意見","question":"３.５％という手数料を区として負担していくというような原則で。そういったことも含めて、今後広げていくにあたっての区の考え方、区民サービスの向上という視点からというところなのですが、説明を求めました。","respondent":"山本情報推進課長","answer":"それから窓口のキャッシュレスにつきましても、交通系ＩＣカード以外のもの、ＱＲコード等の対応をしていきたいというふうに考えてあります。それから手数料等の問題もありますが、なるべく利用件数が多く見込まれるようなところについては…","id":"exchange-092"},{"speaker":"塚本委員","kind":"質問・要望","question":"今２週間の延長ということが出ていますが、この緊急事態宣言が解除された後、こういったコミュニティ施設の運用をどうするのか。この緊急事態宣言解除後、どういった形でコミュニティセンターを運用していくお考えがあるのか、お聞かせほしいと求めました。","respondent":"古巻文化観光課長","answer":"区全体の方針ということもありますけれども、緊急事態宣言が明けた後に関して、夜間の貸出しはできるだけ再開したいなというところはあります。定員に関しましては、すぐにスイッチを切り替えるように…","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"今のお考えを伺いました。今のような情報の提供というものを、区としてこれは丁寧にやっていただければということをお願いして質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-094"},{"speaker":"くにば委員","kind":"質問","question":"１８５ページ、生活安全推進事業より、声の防犯プロジェクトについてお伺いします。どこで放送されているかなど、現在の実施状況を説明を求めました。","respondent":"黛生活安全担当課長","answer":"そこで、その代替事業として、広く区民に防犯を呼びかけることはできないかということで、企画したものです。実施状況につきましては、現在６つの商店街と２つの店舗、広報を行っているところです。","id":"exchange-095"},{"speaker":"くにば委員","kind":"質問・要望","question":"ぜひともこのプロジェクトを区内全域隅々まで広げていただきたいと考えますけれども、いかがでしょうか。区内警察署や防犯協会、商店街などとの連携、告知、広報などの計画や意気込み等を説明を求めました。","respondent":"黛生活安全担当課長","answer":"今後ですが、広報しながわでの募集を呼びかける予定となっております。さらには様々な広報媒体を活用し、広く、そして継続的に募集を続けていきまして、プロジェクトを拡大させるように努めてまいりたいと考えております。","id":"exchange-096"},{"speaker":"くにば委員","kind":"質問","question":"品川区でもこの事業を取り入れて、さらなる声の防犯プロジェクトを推進してはいかがでしょうか。見解を説明を求めました。","respondent":"黛生活安全担当課長","answer":"ご提案の件につきましては、実は区内の警察署からも同様の提案がございまして、現在担当で調査・研究を進めているところです。皆様方からご意見を頂戴し、また我々も様々なアイデアを出して、事業を展開してまいりたいと考えております。","id":"exchange-097"},{"speaker":"くにば委員","kind":"質問","question":"広報広聴課は、ウェブ運用においてはごく基本的な問題点について、まず認識はしていますでしょうか。もし認識しているとしたら、なぜこの問題を放置しているのか尋ねました。","respondent":"山本情報推進課長、大澤広報広聴課長","answer":"ブラウザの件ですが、委員ご指摘のとおり、ＩＥは１０までサポート期限が終わっており、今１１が使われているということで、こちらも将来的にはサポート期限がなくなるというところは聞いているところです。 ホームページの問題点については、今後区として検討していきたいと考えています。","id":"exchange-098"},{"speaker":"くにば委員","kind":"質問・要望","question":"これらの媒体なら放置せず、修正の指示をするのではないでしょうか。修正と運用ルールの制定を求めますが、ご答弁ください。","respondent":"大澤広報広聴課長","answer":"各ページの管理は各部にお任せしているところではありますが、広報広聴課として、全庁的な調整が必要だというふうに認識はしています。令和３年度につきましては、より見やすく、適正なホームページにするように努力してまいります。","id":"exchange-099"},{"speaker":"くにば委員","kind":"質問・要望","question":"公共機関に対して年に１回試験結果の公表を求めていますけれども、品川区は、最後にウェブアクセシビリティ試験をしたのはいつでしょうか。今後の方針についても説明を求めました。","respondent":"大澤広報広聴課長","answer":"今更新があったり、新規のものは、全てＰＤＦのほかにテキスト文書もつけております。過去に遡ってはまだ全部は終わっておりませんが、今後も進めていきたいというふうに考えております。","id":"exchange-100"},{"speaker":"のだて委員","kind":"質問","question":"私からは、１７１ページの非核平和都市品川宣言事業に関わって、核兵器禁止条約について伺います。非核平和都市品川宣言をしている自治体として、核兵器禁止条約の発効を歓迎しているのかどうか、歓迎してほしいと思いますが、いかがでしょう。","respondent":"立川総務課長","answer":"これまでも答弁してまいりましたけれども、区独自の平和事業を継続して実施することで、恒久平和確立の意識啓発を区の内外に向けて発信しています。したがいまして、核兵器禁止条約に関しまして、区として改めて態度表明等を行う考えはありません。","id":"exchange-101"},{"speaker":"のだて委員","kind":"質問・要望","question":"新たにこの核兵器禁止条約というものが発効されたわけですから、被爆者が非人道性を訴え続けて、ようやくこの核兵器禁止条約として実を結びました。その品川区が核兵器禁止条約を歓迎しないのか、伺います。","respondent":"立川総務課長","answer":"区独自の恒久平和確立に向けての意識啓発等を実施していますので、区として、核兵器禁止条約に関しまして態度表明を行う考えはございません。","id":"exchange-102"},{"speaker":"のだて委員","kind":"質問","question":"長崎や広島の悲劇を繰り返してはならないと思いますけれども、いかがでしょうか。改めて伺います。","respondent":"立川総務課長","answer":"区といたしましては、非核平和都市品川宣言に基づき、今後とも事業を実施してまいりたいと思います。","id":"exchange-103"},{"speaker":"のだて委員","kind":"質問","question":"自治体として、しっかりと態度表明をしていく、せめて繰り返してはならないということは言っていくべきなのではないでしょうか。伺います。","respondent":"立川総務課長","answer":"広島、長崎に関しましては、区として毎年夏に中学生の広島平和使節派遣、また、長崎に対します青少年平和使節派遣をしています。こういった地道な事業を継続していきたいと考えているところです。","id":"exchange-104"},{"speaker":"のだて委員","kind":"質問・要望","question":"この宣言をしている自治体として、こうした立場にぜひ立ってほしいと求めました。この非核平和都市品川宣言と、核兵器禁止条約は同じ方向性だと思いますが、いかがか尋ねました。","respondent":"立川総務課長","answer":"繰り返しになりますけれども、品川区といたしましては、非核平和都市品川宣言に基づき、事業を実施してまいります。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"同じ方向性だと言えないのでしょうか。伺います。","respondent":"立川総務課長","answer":"同じ方向性であるかどうかは、それぞれ解釈していただければというふうに考えております。","id":"exchange-106"},{"speaker":"のだて委員","kind":"質問・要望","question":"国内でも、核兵器禁止条約に参加をすべきだと７割の方が答えています。この態度表明が核兵器廃絶への後押しになるとは考えないのか、伺います。","respondent":"立川総務課長","answer":"区は非核平和都市品川宣言を基にした事業を実施しています。それぞれよりどころと言ってはなんですけれども、その辺は異なりますが、地道に努力していきたい、そのように考えております。","id":"exchange-107"},{"speaker":"のだて委員","kind":"質問","question":"つまりは核兵器禁止条約とは立場は違うということですか、伺います。区は、この核兵器禁止条約が核兵器廃絶への力になると考えているのか、伺います。","respondent":"立川総務課長","answer":"何回も同じ質問をされておりますので、また同じ回答をいたします。核兵器禁止条約に関しましては、区として態度表明を行う考えはありません。","id":"exchange-108"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ宣言をしている自治体として、まだ、この参加をしていない日本政府にも署名、批准を求めてほしいと求めました。そうしたことが、やはり核兵器廃絶へとつながっていくと思いますので、強く要望したいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"最初に、１７７ページの総合庁舎緊急対応改修工事についてお聞きいたします。緊急の対応改修工事が９,２００万円余ということなのですけれども、具体的にどういった工事をするのか、お知らせほしいと求めました。","respondent":"東野経理課長","answer":"緊急対応改修工事ですが、こちらは令和２年度に予算計上していたところなのですけれども、コロナ対策ということで令和３年度に見送ったものです。ＬＥＤ工事、それから総合庁舎につきましては、空調設備のダンパー更新工事、こちらがこの予算の中身です。","id":"exchange-110"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そうすると、工事はどのぐらいの期間を見ているのか。これは第３庁舎の工事が一番主立った内容だと思うのですけれども、工期についてお知らせほしいと求めました。","respondent":"東野経理課長","answer":"工事期間につきましては、今後調整という形になるのですけれども、大体３か月程度というふうに見ているところです。","id":"exchange-111"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続きまして１８１ページ、区民活動情報サイトについてお伺いいたします。あるいはイベント案内ですか、やはり何というのですか、そういうことがあることを見通してリニューアルということなのです。","respondent":"宮澤協働・国際担当課長","answer":"特にスマートフォンやタブレットに対応していないというところがありますので、画面の表示の最適化をするような形になります。運用を開始しまして、この１０年間、月のアクセスというのが、大体月に１万件から１万２,０００件という形で推移してきております。","id":"exchange-112"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そういうことを含めてできると思うのです。来週ですか、３月８日の月曜日と火曜日に、今の現状をお知らせください。","respondent":"宮澤協働・国際担当課長","answer":"リニューアル後のシステムの操作説明会というものを予定しております。この説明会の内容というのを動画で記録しまして、新しいすまいるネットのサイト上でも見ていただけるような形で配信するとともにマニュアルを載せる。","id":"exchange-113"},{"speaker":"高橋（伸）委員","kind":"質問","question":"１８３ページ、地域センター等管理運営費についてお伺いいたします。私がちょっとお聞きしたいのが、やはり何というのですか、どのようにお伝えしているのかということをお聞きしたいと思います。","respondent":"川島地域活動課長","answer":"様子をうかがって、それから窓口が混んでいるか、混んでいないかというところも気にかけながら接しています。","id":"exchange-114"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"何で扱っていないの」など、住民の方、これから転入されている方で納得いかない方もいらっしゃると思うのです。より足を運んでもらえるよう、どのようにされているのかどうかを、ちょっともう１回教えてほしいと求めました。","respondent":"川島地域活動課長","answer":"トラブル対応の大切なところというようなことだと思いますけれども、やはりお客様の言い分というか、言うところをまずしっかり聞くと。傾聴した上で丁寧な対応をするというようなことが基本になるということで、日頃から指導しています。","id":"exchange-115"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１９７ページ、ジュニア二極化解消事業等についてお聞きいたします。二極化、具体的な内容、やられている内容をお知らせほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"親子スポーツ教室、こちらは令和３年度はヨガ教室を予定しています。２つ目として、チャレンジスポーツ教室、こちらは駆けっこ、縄跳び、跳び箱、ボール投げなど、運動の基本的動作の基礎を培う教室を予定しています。","id":"exchange-116"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"チャレンジ親子スポーツ教室など、いろいろやられていて、令和２年度の予算ですと１３１万円余、来年度の予算が１９９万円余なのですけれども、増額になって、何かまた別に、今課長がおっしゃったように、改めて令和３年度も計画しているのかどうか、お知らせほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"８種目スポーツ体験教室を令和２年度は予算化を見送っていたところです。令和３年度につきましては、新しくジュニアダンス教室をオンラインで始めるということで、少し金額を増やして要求をさせていただいたものです。","id":"exchange-117"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続いて、同じく１９７ページの、親子ジュニアスポーツフェスタについてお伺いいたします。今回３月１日に広報しながわに載っていたこのイベントが親子ジュニアスポーツフェスタの部類に入るのかどうか、お知らせほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"体育館内でやることもちょっと難しいということで、キッズオンラインイベントということで、今回は広報しながわに載っているものに切り替えて実施をするというものです。","id":"exchange-118"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これが今月の３月２８日の日曜日に午前９時から午後２時半まで、１４時半までやるということで、６項目ぐらいいろいろあります。取組内容としてそれぞれ６項目あり、どれぐらい、バランスよく振り分けてやっていかれるのかということをお知らせほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"それぞれ３００組です。１組で６種目全てを申し込むということでも大丈夫ですが、ただ、そこを超してしまうと受けられないということになってきます。","id":"exchange-119"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"６７０万円余という予算づけ、令和２年度と比べて減額されているのですけれども、数字が少し落ちたのかどうかということをお知らせほしいと求めました。","respondent":"中元スポーツ推進課長","answer":"来年度につきましては、区立総合体育館での開催を予定しています。３密を防ぐイベント運営に内容を工夫したり、そのような、地域のスポーツ習慣の定着化につなげていきたいというものに少し内容を変えるものです。","id":"exchange-120"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひとも未来ある少年・少女のスポーツ普及にこれからも取り組んで、未来ある子どもたちのためにやってほしいと求めました。終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-121"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから１７３ページ、男女共同参画、時間があれば、新庁舎についても少しお伺いいたします。現在の感覚に合ったものに見直しを検討してはいかがかと思いますが、いかがか尋ねました。","respondent":"島袋人権啓発課長","answer":"ただ時代に合わせ、やはり検討が必要だということも認識しておりますので、次回はまた少し内容等を検討させていただきたいと考えております。よろしくお願いします。","id":"exchange-122"},{"speaker":"あべ委員","kind":"提案","question":"午前中も同様の議論があったと思いますけれども、まず集会室の使用料支払いについてお伺いいたします。昨年の予算特別委員会でキャッシュレス対応するよう提案したところ、ベンダーと検討していただけるということでしたとの意見を述べました。","respondent":"山本情報推進課長","answer":"来年度サービスコーナーや税務課の窓口でも拡大をする予定ですが、令和４年度対応できるように検討を進めているところです。その中で施設の使用料につきましても、キャッシュレス化対応していくかは考えていきたいと思ってあります。","id":"exchange-123"},{"speaker":"あべ委員","kind":"質問","question":"それは土日も料金収受ができるという意味でよろしいか尋ねました。","respondent":"山本情報推進課長","answer":"土日の対応も含めまして、今後考えてまいります。","id":"exchange-124"},{"speaker":"あべ委員","kind":"質問","question":"令和４年度からということで、ちょっとまだ時間はかかるかなとは思うのですけれども、ぜひよろしくお願いしたいと思います。平時の働き方改革のためにも、品川区ではまず実証実験に参加しているのかどうか、そして現在の活用状況などについても説明を求めました。","respondent":"山本情報推進課長","answer":"あわせまして、昨年９月補正で在宅勤務ができるテレワークシステムというものを導入していまして、こちらも１００ライセンス分用意しております。こちらは、インターネット経由になりますが、こちらも活用して、今在宅勤務等を行っているところです。","id":"exchange-125"},{"speaker":"あべ委員","kind":"質問","question":"そちらの活用状況はいかがでしょうか。品川区の職員の方々の活用状況はお分かりか尋ねました。","respondent":"山本情報推進課長","answer":"１年間自治体が無償で使えるというところで、今年度実証実験という意味合いを含めまして、今利用しています。それから、現在の達成度ですが、ウェブ会議、テレワーク含めて、まだ検証の段階だというふうに考えてあります。","id":"exchange-126"},{"speaker":"あべ委員","kind":"質問","question":"品川区では、５年後の自治体の姿をどのように描いているでしょうか。今後自治体のデジタル化を進めていく上で、一番大切なことは何だというふうに、品川区では考えているでしょう。","respondent":"山本情報推進課長","answer":"国のほうでも昨年末、自治体ＤＸ推進計画を策定しまして、自治体として取り組むべき重点事項というものが示されているところです。そういった意味で区民サービスの向上、それから業務の効率化が図れるようなデジタル化というものを推進していきたいというふうに考えてあります。","id":"exchange-127"},{"speaker":"あべ委員","kind":"意見","question":"やはり情報公開、そして住民参画が進んでいく、このことがセットになっているのではないかと思います。デジタル・トランスフォーメーション、ＤＸを進めていく中で、品川区として、情報公開や行政の透明性をどのように認識しているかお答えくださいとの意見を述べました。","respondent":"山本情報推進課長","answer":"確かにデジタル化を進めるにあたりまして、区としても、区民の様々な情報を取り扱っていくことになると考えています。その辺りで、セキュリティ対策等も含めまして、区の取組はきちんと区民の方に説明していく必要があるというふうに考えてあります。","id":"exchange-128"},{"speaker":"こんの委員","kind":"質問・要望","question":"１８７ページ、２０５ページ、マイナンバーカード普及促進をお伺いしたいと思います。しかし、実際交付受付窓口では、申請者ご本人の顔写真つきの確認書類や診断書が求められたりする。","respondent":"木村戸籍住民課長","answer":"そのような対応も行っておりまして、どうやったらできるだろうかというところをお聞き取りしながら、ケース・バイ・ケースで対応しています。そこに寄り添って交付していけるよう私どもも考えたいと思いますし、今、何とか緩和をしてもらいたいなです。","id":"exchange-129"},{"speaker":"こんの委員","kind":"提案","question":"１つの提案というか、ご存じかどうか確認したいのですが、代理人による受け取りができるとしております。こうした他区等の事例も踏まえて、品川区でも対応が必要ではないかと思われますけれども、いかがか尋ねました。","respondent":"木村戸籍住民課長","answer":"他区等の事例については、認識をしているところではございまして、私どもとしても、より分かりやすいお知らせの仕方、運用を考えてまいりたいと考えています。","id":"exchange-130"},{"speaker":"こんの委員","kind":"質問","question":"成人式経費についてお伺いしたいと思います。してほしいと願うところですが、こうしたことも開催方法として考えられるのではないかと思いますけれども、いかがか尋ねました。","respondent":"立川総務課長","answer":"きゅりあんが使えない再来年からですけれども、代替会場とともに、いわゆるオンラインでの開催を併用して実施する、今年もそういうつもりで考えていたところがありますので、委員ご提案の内容も踏まえまして、検討していきたいと思います。","id":"exchange-131"},{"speaker":"鈴木（真）委員","kind":"質問","question":"新年度予算が２,９００万円余を計上していらっしゃいますが、今年度の実績としてはどのようになっていたか、その辺を教えてください。現長期基本方針における国際交流の考え方について、改めてお聞きしたいと思います。","respondent":"川島地域活動課長、宮澤協働・国際担当課長","answer":"令和２年度の市町村交流の実績です。令和元年度が１,４００名ほどだったものが、令和２年度につきましては２７８名ということで、かなり少ない実績になってあります。 新しい長期基本計画で、平和で人権が尊重され多様性を認め合う社会の実現ということで、その中で国際交流の事業を進めているところです。各都市との交流を進めてきたというところと、区民へのそういった啓発活動を進めていく中で…","id":"exchange-132"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そういう中で、区民の方が市町村交流をどの程度知っているかというのを調査したことがあるのかどうか、その辺をお聞きしたいと思います。その辺についてお考えを説明を求めました。","respondent":"川島地域活動課長、宮澤協働・国際担当課長","answer":"山北町につきましては昭和６３年に協定を締結しまして、早川町も平成２年から協定を締結してお付き合いが始まっているということで、かなり定着してきているのではないかと認識しています。 その中で、毎年４月になりましたら、各大使館を回るなどして連携を強めているところです。各姉妹友好都市とも５年ごとの交流というのがありますので、そういった機会を捉えてしっかり交流を進めていくです。","id":"exchange-133"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その辺についてお考えをお聞きしたいと思います。当然この辺については、今までどおり行ってもらいたいと思うのですが、改めてそこについてもお聞きしたいと思います。","respondent":"川島地域活動課長、佐藤企画調整課長","answer":"この交流都市を事業で使っていただけるように、庁内連携の意味でも、交流都市を知っていただくような工夫をしていければと考えています。 組織改正のご質問ですので、私からご答弁いたします。より積極的に進めていくというところで、また区内全般的にわたって、そういった事業をこれまでより力を入れてやっていくです。","id":"exchange-134","title":"町会・自治会支援"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、今後の活用ですとか、それから、マウントしながわをどうやって活用していくのか、その点についてもう１回お答えをお願いしたい。その辺も踏まえてもう１回、国際的なものの考え方をお願いいたします。","respondent":"川島地域活動課長、宮澤協働・国際担当課長","answer":"より多くの方に知っていただく工夫というのは、委員のご指摘も踏まえて考えていく予定です。 姉妹都市、友好都市の３都市との交流を進めているのを中心にしています。例えば産業、教育であったり、そういった分野に特化した形の交流という考え方もありますので、在住外国人の動向等を注視しながら研究してまいります。","id":"exchange-135"},{"speaker":"西本委員","kind":"質問・要望","question":"区民の皆さんの財産ですから、それは非常に学ぶべきところがあるのではないかと思いますが、お考えをお聞きします。倍以上のお金を使っているわけですから、減免という形でコロナ禍の期間だけでも配慮していただきたいと要望しますが、いかがか尋ねました。","respondent":"佐藤企画調整課長、古巻文化観光課長","answer":"このシートに関しましては、それ以外の見直しとあわせて、今検討しておりますので、早々に見直しを図りたいと思っているところです。成果指標に基づいた実施計画をつくりまして、収支の観点も入れながらご報告をしたいと考えており… Ｗｉ－Ｆｉについては、使えると認識しておりますので、そのようにお申し出いただければＷｉ－Ｆｉは使えるはずですけれども。私はＷｉ－Ｆｉが使えるという認識で、その辺については確認させていただいて…","id":"exchange-136"},{"speaker":"西本委員","kind":"提案","question":"区民の人たちが不便だ、利便性がないというのがあるならば、なぜそこの指定管理の方々が考え、提案をして、変えようとしないのでしょうか。今、コロナ禍において大変な思いをして、苦慮しているわけですから、減免というか、少しは考慮してもいいのではないか尋ねました。","respondent":"古巻文化観光課長","answer":"いろいろとお客様のご要望をしっかり受け止め切れていないというところなのかなと考えて、そのように発言をしたものです。今回、きゅりあんだけが何かできないということではないと認識をしておりますので、今後はきちんと考えていきたいと思います。","id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３００円の手数料は無料にすべきだと共産党としても一貫して求めてきましたので、改めて手数料の無料化を要望しておきたいと思います。１４０円というのは高過ぎると思うのですけれども、ぜひコピー代の引下げもしていただきたいと思うのですが、いかがか尋ねました。","respondent":"大澤広報広聴課長","answer":"白黒のコピー代については、国や都、他区と比較しましても、妥当な金額だと考えております。ただ、カラーのコピー代につきましては、現在の状況と照らし合わせまして、妥当であるかの検証は必要であると認識しています。","id":"exchange-138"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これを求めて質問したいと思います。作成されるとしたら、いつできるのかについても伺います。","respondent":"佐藤企画調整課長","answer":"１点目の方針の見直しにつきましては、委員ご指摘のとおり、平成３０年の後半ぐらいから進めてまいりました。今、鋭意作業を進めておりますので、来年度の早い段階で方針を改定いたしまして、また議会にご説明できると考えております。","id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"企画調整課だけで、なぜこんなにかかっているのかなと思うのですが、新年度の早い時期にできるということで確認させていただいていいでしょうか。その改善というのは、今回の運営指針とかガイドラインの中でどう改善されるのか、教えてほしいと求めました。","respondent":"佐藤企画調整課長","answer":"１点目の方針等はいつできるのかというのは、先ほどご答弁したとおり、来年度早々には策定を完了したいと考えています。私どもも課題と考えておりますので、各所管への徹底に関しましては、研修等も行ってやっていきたいと考えております。","id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"選定委員会の会議録もぜひ公表の項目に入れていただきたい、議会への資料に入れていただきたいと思うのですけれども、いかがでしょうか。これをぜひ資料として議会へ提出していただきたいし、公表もしていただきたいと思うのですが、いかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"基本的に氏名等の公表が必要であると今のところは検討しているところで、最終的に判断していきたいと考えております。その辺の徹底と、文章の記載、その辺を今、検討しています。","id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"その提案した事業への実施状況を、報告書という形で出していますので、それについても資料で出せるようにしていただきたい。以上３点の改善を求めますが、いかがか尋ねました。","respondent":"佐藤企画調整課長","answer":"市区町村でこういった情報を公表しているのは５０％と、全国的にそういった面で苦労しているのだと理解をしているところです。しかしながら、その辺の項目というのはできるだけ出していきたいと区としても考えておりますので、その辺を配慮して進めていきたいと考えております。","id":"exchange-142"},{"speaker":"たけうち委員","kind":"質問","question":"１８５ページの自動通話録音機等の特殊詐欺対策、それから２０３ページで住民基本台帳関係費に関連して伺います。これが何件ぐらいあったか説明を求めました。","respondent":"黛生活安全担当課長、宮澤しながわ活力応援給付金担当課長","answer":"被害総額につきましては約１億３,５００万円で、これも昨年に比べましてマイナス５,９００万円となっております。被害が減少した要因ですが、それだけではなく… 申請されていない世帯に対しまして、９月３０日に勧奨通知を発送しました。その戻りは１５１件というところでございました。","id":"exchange-143"},{"speaker":"たけうち委員","kind":"質問・要望","question":"２週間ぐらい前ですか、それで私の妻が出たのですが、「荏原警察署の何々です」と。私が思ったのは、勝手に電話番号を調べて連絡するわけにはいかないのだろうなと思うのですけれども、どういう策が打てるのか説明を求めました。","respondent":"黛生活安全担当課長、木村戸籍住民課長","answer":"特殊詐欺被害防止に関する警察との連携状況についてお答え申し上げます。引き続き、こうした活動を積極的に展開してまいりたいと考えております。 全貌については分かりませんけれども、手続きのやり方についてはそのような形です。それと、電話番号については、届け書にはお書きいただくのですけれども、いわゆるデータとして保存してはいないです。","id":"exchange-144"},{"speaker":"たけうち委員","kind":"質問・要望","question":"あまりいろいろなメールが来過ぎてしまって、かえってどうなのかなと思うのですけれども、そういうもう一重の取組についてお聞かせいただきたい。そういうことが防げないかなと思うのですけれども、一応ご感想というか、説明を求めました。","respondent":"黛生活安全担当課長、木村戸籍住民課長","answer":"ただ、大変有効な手段であるのではないかと考えております。どういうときにこれが使えるのか、また使わなければいけないのかにつきまして、これから関係課と調査・研究を進めてまいりたいと思います。 受付の際に、郵便物が必ず届くようにというご案内を一つ添えたような形で、それを徹底してまいりたいと考えています。","id":"exchange-145"},{"speaker":"たけうち委員","kind":"質問・要望","question":"実験的にやっていくということなので、そういうものも含めて複合的に、ぜひさらに減少していただくように要望します。それから住民基本台帳は、これから、特にワクチンなども含めて出てくるので、何かできないか、また引継ぎも含めて、ぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-146"},{"speaker":"本多委員","kind":"質問","question":"１７１ページの危機管理経費について質問します。それ以来、１５年経ちましたけれども、充実されてきた点ですとか、あるいは積み上げてきた点などについて説明を求めました。","respondent":"立川総務課長","answer":"様々対応してきたところですけれども、平成２３年には東日本大震災の関係ですとか、初動体制をつくるということでやってまいりました。年々対応に熟度が増してきたと考えているところです。","id":"exchange-147"},{"speaker":"本多委員","kind":"意見","question":"分かりました。総務部と災害対策担当のそれぞれの組織の役割について、どう発揮をされてきたのか、その点を説明を求めました。","respondent":"立川総務課長","answer":"危機管理におきまして、災害対策担当部長におきましては、危機管理監としての役割を担っていただいております。それ以外のところを総務課、また総務部長が中心にやっている、そういった切り分けです。","id":"exchange-148","title":"町会・自治会支援"},{"speaker":"本多委員","kind":"質問","question":"複合災害で、多重防御について伺います。そうした備えや心構えについて、危機管理宿直室としてはいかがお考えか尋ねました。","respondent":"立川総務課長","answer":"自然災害における品川区の危機管理宿直という視点ですけれども、この辺につきましては、宿直の職員として、管理職が日々交代で対応していますので、連絡網等を整備いたしまして、災害時、即座に連絡が区長をはじめ行き渡るように、体制を取っているところです。","id":"exchange-149"},{"speaker":"本多委員","kind":"質問・要望","question":"そして、組織強化について質問するのですが、現在品川区内には自衛隊出身の方、任期付採用２名、会計年度任用職員１名になります。自衛隊を退官された方の採用を強化し、組織のさらなる強化を図る点について、区のお考えを説明を求めました。","respondent":"黒田人事課長","answer":"災害対策でありますとか、危機管理に対応する組織をどのように運営していくかという中で、必要な人材について執行体制を整えてまいりたいと考えています。","id":"exchange-150"},{"speaker":"本多委員","kind":"質問・要望","question":"あるいは警察の出身の方、消防出身の方、それで日本全国の自治体の組織強化をするべきだという活動をしております。ぜひその点について改めて教えていただきたいのと、今現在、もう少し区民に知っていただくＰＲについてはいかがか尋ねました。","respondent":"黒田人事課長","answer":"そういった中で、どのような体制でどのような専門的な知見をいただくかというところも含めて、今後執行体制について考えてまいりたいと思います。２３区で初めて部長として採用したときにはプレス等もしておりますので…","id":"exchange-151"},{"speaker":"本多委員","kind":"質問・要望","question":"もう少し区民に、こういう取組をして、こういう方を採用をしているので、区の組織が強化したのだということをＰＲしてほしいと求めましたし、現実的に組織強化ということでうたって取組をしていますので、組織強化になったという部分を改めて教えてほしいと求めました。","respondent":"黒田人事課長","answer":"事業を執行する上での今まで気がつかなかった視点というところが当然出てまいりますので、そういったところで、全体的な組織強化につながっているものと考えているところです。","id":"exchange-152"},{"speaker":"本多委員","kind":"質問","question":"例えば、この間の２月の地震のときにも、テレビで２３区の震度は、最初は４と出たけれども、最終的に品川区は３と修正されました。それは突発的なことですから、品川区が３というのが出るのは防災課任せなのか、その辺を説明を求めました。","respondent":"立川総務課長","answer":"この間、地震がありまして、実際、品川区役所の庁舎の震度計は２.９でございました。それは東京消防庁、そういった機関で把握しているものと、気象庁等が把握しているものと認識しております。","id":"exchange-153"},{"speaker":"本多委員","kind":"質問・要望","question":"もし分からなければ結構なのですが、品川ふ頭に、都の港湾局が管理している敷地内に、品川地震観測所がありまして、その辺の把握というか、どうなのかなと思って、素朴に教えていただきたいと。","respondent":"立川総務課長","answer":"総務課としては、港湾局の震度計については認識しておりません。","id":"exchange-154"},{"speaker":"本多委員","kind":"質問・要望","question":"引き続き、組織強化に向けて取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-155"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１６３ページですけれども、指定管理者の設定について、以前から議案として提出していただきたいという観点からお伺いします。今でも単年度協定を利用とする場合は、その根拠と総務省の見解に誤りがあるならば、その理由をお尋ねします。","respondent":"佐藤企画調整課長","answer":"指定管理者における債務負担行為の設定に関しましては、委員ご紹介のとおりの認識を私どもも持っております。様々な対応、また考え方があると思いますので、その辺に関しましても、今検討しています。","id":"exchange-156"},{"speaker":"高橋（し）委員","kind":"提案","question":"その指定の議決を、つまり予算措置のないまま議決してくださいと、議案として提案されているわけであります。そういった観点からも必要だと思いますが、改めてもう一度お願いしますとの意見を述べました。","respondent":"佐藤企画調整課長","answer":"指定管理者に関する債務負担の関係ですが、委員にこれまでご指摘いただいた内容は、区としても把握をしています。私どもの区のように設定していない自治体もございまして、そういった場合の理由や根拠等も精査しながら、今後検討を進めたいと思います。","id":"exchange-157"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その根拠を伺うことができませんでしたが、債務負担行為も含めて、予算として出てくることを要望いたします。少し検討させてほしいということでしたが、もし可能ならば、企画の部署にお答えほしいと求めました。","respondent":"山本情報推進課長","answer":"長期基本計画のＳｏｃｉｅｔｙ５.０の視点というところに沿いながら、ＩＣＴ化というのを進めていきたいと考えているところです。自治体として、重点的に取り組むべき事項というのが挙げられておりますので、それぞれ基本的な方針と内部の進め方等は考えていきたいと考えていま…","id":"exchange-158"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"その検討を進めていってほしいと求めました。先日もほかの委員のご質問にありましたけれども、接種管理などでＲＰＡの活用等も考慮すべきだと思うのですが、いかがか尋ねました。","respondent":"山本情報推進課長","answer":"システムの連携、データの連携等がありますので、それに沿って着実に進めていきたいと考えています。委託のほうでデータ入力等もすると聞いてありますので、もし活用という場面になりましたら、こちらも全面的にサポートはしていきたいと考えています。","id":"exchange-159"},{"speaker":"大倉委員","kind":"提案","question":"１６７ページ、ＬＩＮＥ公式アカウント運用、１７１ページ、企業・大学との連携、１７５ページ、庁舎管理費について伺います。庁舎を利用される方への周知の取組についてご提案したのですが、その答弁としては、いろいろ検討していきますということでありましたとの意見を述べました。","respondent":"山本情報推進課長、東野経理課長","answer":"チャットボットの利用方法についてですが、区といたしましても、利用方法について改善の余地もまだあると考えていますので、委員からご指摘いただいた点も含めまして、より使いやすいものになるよう工夫してまいります。 庁舎入り口へのサーモグラフィーの設置なのですけれども、第３庁舎等、かなり多岐にわたってあるような状況です。今後も新型コロナウイルス感染症の対策としては、そういった面につきましても検討していきたいと考えています。","id":"exchange-160"},{"speaker":"大倉委員","kind":"質問・要望","question":"２階、３階、もう検討されているのかどうか教えてください。アンケートや、学生の皆さんから意見などを聴いていただいて、何か支援につながればいいなと思っているのですが、お考えを説明を求めました。","respondent":"東野経理課長、立川総務課長","answer":"改めて考えないといけないと考えていますので、複数の入り口がある場合の対応につきまして、少し研究をしていきたいと思います。熱がある方への対応なのですけれども、３階、２階の受付、また警備で回っている方もいらっしゃいます。 総務課が所管しております大学等との連携ですが、地域社会において大学と地域がどういった連携を図って、また社会貢献活動を進めていけるかです。ただいま委員からありました大学生への支援ということに関しましては…","id":"exchange-161"},{"speaker":"大倉委員","kind":"質問・要望","question":"大学生への支援なのですが、所管はどこになるのでしょうか。今、分からなかったので、大学との連携で伺ったので、分かれば教えていただきたいのと、ぜひアンケート等も含めて大学生の声を。","respondent":"立川総務課長","answer":"大学生ですので、青少年対策ということになるかなと考えております。","id":"exchange-162"},{"speaker":"藤原委員","kind":"確認","question":"だから予算書に載っていないのですか。その確認をさせてもらいます。","respondent":"黛生活安全担当課長","answer":"今後は業界団体を通じての働きかけを継続するとともに、様々な広報手段等を活用して、周知と啓発に努めるようにしてまいります。引き続き工夫をしながら実施をしてまいる所存です。","id":"exchange-163"},{"speaker":"藤原委員","kind":"質問","question":"３点伺って、それで財政課長、こういうところこそわんわんパトロールという項目を入れないと駄目でしょう。それが、こうやって出ていないで、どこかとまとめてしまうのは、どうなのか尋ねました。","respondent":"品川財政課長","answer":"予算書の表記につきましては、いろいろとご意見等があるかと思います。こういうご指摘を受けまして、来年予算書等を作成するにあたって、所管課とも連携しながら、引き続き、表記については考えていきたいと思います。","id":"exchange-164"},{"speaker":"藤原委員","kind":"質問・要望","question":"生活安全担当課長、区民の安心・安全を守っていきましょうと、この場で質問してお願いをしているわけです。今度は１,２００万人の東京都民のために、ぜひこの経験を活かしていっていただきたいと思うのですけれども、何かあれば答弁いただけますか。","respondent":"黛生活安全担当課長","answer":"安全で安心して暮らせるまちづくりに、警察と行政の連携が重要であることを、こちらに来て本当に勉強させていただきました。感謝の気持ちを常に持ちながら、１人の警察官として、首都東京の良好な治安の確保のために全力を尽くしてまいる覚悟です。","id":"exchange-165"},{"speaker":"藤原委員","kind":"質問","question":"次は、１７５ページの食堂と、あと、職員給与費という意味で、ちょっと前に出ていた職員の方の定年延長、それと役職定年。食堂に関しては、十何年前はプロポーザルに、結構業者が来ていたと思うのですけれども、現状はどうなっているのか尋ねました。","respondent":"黒田人事課長","answer":"大体１４０食ぐらいということで、座席数が椅子の数で１２９ありますが、大体２回転しないような状況です。そういったところで、収支については現在も厳しい状況が続いているです。","id":"exchange-166"},{"speaker":"藤原委員","kind":"意見","question":"職員の方の定年延長と役職定年はどうなったのか。食堂のことは大事だと思うのですけれども、との意見を述べました。","respondent":"黒田人事課長","answer":"失礼しました。６０歳で役職を定年とする改正法案が提出されておりましたが、地方公務員法改正案は継続審議となっているですが、制度については未成という状況です。","id":"exchange-167"},{"speaker":"藤原委員","kind":"質問","question":"３点、質問したのですけれども、課長ご自身は食堂へ行かれているのですか。質問します。","respondent":"黒田人事課長","answer":"私は、できる限り食堂で昼食を取るようにしております。","id":"exchange-168"},{"speaker":"藤原委員","kind":"質問","question":"それと、１７１ページの新年賀詞交歓会を伺います。とてもがっかりしたと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"立川総務課長","answer":"１１月の時点で城南地区、５区ありますけれども、品川区だけが実施するということで頑張っておりました。１２月に入りまして、実施するのは適切ではないということで、中止の決定をさせていただきました。","id":"exchange-169"},{"speaker":"藤原委員","kind":"質問","question":"本当にがっかりしましたよねと伺ったので、その辺のことを伺いたいのと、ああいう形で開催できなかった。行政として停滞していってしまうのではないかと私は心配しているのですけれども、その面も含めていかがか尋ねました。","respondent":"立川総務課長","answer":"新年賀詞交歓会の意義というものですけれども、呼んでいる皆さんは、区と関わりの深い地域の団体、また各種団体、それから官公署です。毎年お願いする場ですので、そういったことができなかったということに関しましては、区民の皆様に対しても大変申し訳なかったと考えておりま…","id":"exchange-170"},{"speaker":"藤原委員","kind":"質問","question":"課長、申し訳なかったという答弁ではなくて、行政にとって多大なマイナスになったのですかという質問なので、その辺について明確にお答えいただけますか。","respondent":"立川総務課長","answer":"新年賀詞交歓会を楽しみに来ていただいている方がかなりいらっしゃるということは聞いているところですので、そういった意味では、モチベーションが低下したのかなとは考えているところです。","id":"exchange-171"},{"speaker":"藤原委員","kind":"質問","question":"新年賀詞交歓会はやりませんでした。新年賀詞交歓会がなくても行政はきちんと回りますということを言っているのかなと思うのですけれども、その辺について、いかがか尋ねました。","respondent":"立川総務課長","answer":"新年賀詞交歓会を実施することによりまして、区民の皆様に１年間気持ちよく区政に協力していただけるということで、これからも実施していきたいとは考えているところです。","id":"exchange-172"},{"speaker":"安藤委員","kind":"質問","question":"１７２ページ、１８５ページ、大崎駅西口の喫煙所について伺います。天下りについてですが、まず、区職員の定年退職の規定はどうなっているのか伺います。","respondent":"黒田人事課長","answer":"区職員の定年の規定ですが、該当年度に６０歳に到達した場合に、３月、年度の末日で定年退職となるというものです。再任用職員につきましては、それぞれの級において月額給与が決まっておりまして、大体定年退職前の６割程度という設定になっているところです。","id":"exchange-173"},{"speaker":"安藤委員","kind":"質問","question":"区の関連団体あるいは関連企業に再就職している、いわゆる天下りしている方というのは、現在何人いらっしゃるのか伺います。再就職先の企業・団体名とあわせて、それぞれ何人いらっしゃるのか伺います。","respondent":"黒田人事課長","answer":"品川区国際友好協会にはＯＢ１名、品川区スポーツ協会にはＯＢが２名、以上です。そのほかの公益的な法人ですが、社会福祉法人等々合わせまして１０団体ございまして、こちらには管理職のＯＢが８名行っているという状況です。","id":"exchange-174"},{"speaker":"安藤委員","kind":"質問","question":"そうした方の待遇というのは、賞与もあるなど、ほとんど常勤待遇だと思うのですけれども、どうなのでしょうか。伺います。","respondent":"黒田人事課長","answer":"品川文化振興事業団につきましては、理事長が元副区長というところは、こちらでもきちんと把握しています。各企業については、各団体でそれぞれの規定で定めておりますので、こちらで詳細について把握してございません。","id":"exchange-175"},{"speaker":"安藤委員","kind":"質問","question":"地方公務員にはこのような法規制はあるのか、それともないのか、伺います。あわせて、品川区として独自に天下りに関する自主規定やルール、指針などは設けているのでしょうか、伺います。","respondent":"黒田人事課長","answer":"退職前５年間に在籍した職に関することに、退職後２年間は働きかけをしてはならないという規制がありまして、地方公務員法に規定しています。区では、再就職につきましては、個人の働く場所ですので、特段、区として何か規制を持っているというものではございません。","id":"exchange-176"},{"speaker":"安藤委員","kind":"質問","question":"再就職したＯＢが元いた役所に契約を依頼したりするなどの働きかけ、これは２年間禁止するなどの規制が現状では設けられております。伺いますけれども、あるいは働きかけというのは行われているのか、それぞれ伺います。","respondent":"黒田人事課長","answer":"それぞれ個人の自由であろうと考えていますし、刑事罰が科されているですので、そういったことがあってはならないと考えています。","id":"exchange-177"},{"speaker":"安藤委員","kind":"質問","question":"それは行われているのかを伺いました。今の答弁だとあまり分からなかったので、もう一度伺います。","respondent":"黒田人事課長","answer":"あっ旋ということは行ってございません。","id":"exchange-178"},{"speaker":"安藤委員","kind":"質問","question":"伺いますけれども、それを公表していたわけですが、今はあっ旋しないということに方針が変わったということなのでしょうか。変わったなら、いつ、どんな理由でそれを変えたのか伺います。","respondent":"黒田人事課長","answer":"ご本人の意思によるものというところでございまして、いつからということではございませんが、基本的にあっ旋はしていないです。","id":"exchange-179"},{"speaker":"安藤委員","kind":"質問","question":"当時の資料としては、あっ旋、計何名と、各団体ごとに書かれていたのですが、これは、当時はしていたということだと思うのです。なぜ変わったのか、その理由を改めて伺いたいと思いますし、当時はやっていたということでよろしいのか尋ねました。","respondent":"黒田人事課長","answer":"あっ旋という言葉が、どのような意味で使われたのか分かりませんが、現時点において、いわゆるあっ旋による就職は行っておりません。","id":"exchange-180"},{"speaker":"安藤委員","kind":"質問","question":"伺いたいのですが、いわゆる天下りは、李下に冠を正さずという言葉もありますが、公務の公正性を損なうことになっていないのか、伺いたいと思います。公務の公正性を担保するため、いわゆる天下りを規制する自主的なルールづくりが必要だと思いますけれども、いかがか尋ねました。","respondent":"黒田人事課長","answer":"人的援助を行うことが必要であると条例で定めるものは、職員を派遣して、その団体の身分を有して専らその事業に従事してよいと。ＯＢの再就職も、地方公共団体がその施策の推進を図るためという目的に合致していると考えておりまして、特段問題があるとは考えておりません。","id":"exchange-181"},{"speaker":"安藤委員","kind":"質問・要望","question":"大崎駅西口のバスターミナル脇の喫煙所なのですが、早急な撤去もしくは、煙を外と完全に遮断する喫煙施設の整備を求めます。新規事業に助成事業がありましたので、それとあわせて伺います。","respondent":"黛生活安全担当課長","answer":"ただいま委員からご指摘をいただきましたようなご意見は、ほかにも私どもでもいただいているところです。しっかりと受け止めまして、たばこを吸う人、吸わない人が、共に快適に過ごせるまちづくりを進めてまいりたいと考えております。","id":"exchange-182"},{"speaker":"大沢委員","kind":"質問・要望","question":"１番目に、お願いしたほうからこんなことを言うのも気が引けるところはあるのですが、しながわ活力応援給付金をやっていただきました。この２０項目、先の見えない時代だからあろうかと思いますので、そこの４点についてご答弁いただきたい。","respondent":"宮澤しながわ活力応援給付金担当課長","answer":"同時並行で動いておりました特別定額給付金の事務としっかり連携をしまして、改善すべき点というところを、しっかり連携した上で進めてまいりました。ただ、時間がない中、職員が創意工夫して知恵を出しながら、対応してきたです。","id":"exchange-183"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは議会全体で４０人の心を一つにしてお願いしたわけですから、これについて、本当に区長の英断には改めて敬意を表させてほしいと求めました。は議会の質問の仕方、１８時過ぎぐらいまでかかってしまっている委員会について、総務課長はどのようにお考えになるのか説明を求めました。","respondent":"立川総務課長","answer":"昨年からですけれども、委員会運営につきましては、議会の皆様と、またこちらの理事者側で最善を尽くして感染防止対策を施し、実施していると認識しております。","id":"exchange-184"},{"speaker":"大沢委員","kind":"質問・要望","question":"そして第５委員会室に分散しており、私たちの質問に答えていただくので、この委員会の開会中に入退室について取決めのようなものがあるのでしょうか。あれば教えていただきたい。","respondent":"立川総務課長","answer":"理事者側の入退室の取決めですが、特に生理現象について規制しているということはございません。","id":"exchange-185"},{"speaker":"大沢委員","kind":"質問","question":"私たちも区民の皆様の負託を受けているわけですから、理事者の皆さんにおいても、その辺の自由度をお持ちになったほうがいいのではなかろうか。そこについてどのようにお考えになるのか、総務課長、お願いします。","respondent":"立川総務課長","answer":"理事者側の態度、また考え方といたしましては、委員の皆様に極力失礼がないように、その辺を最重点として運営に携わっているものです。","id":"exchange-186"},{"speaker":"大沢委員","kind":"質問・要望","question":"４番目の波、３番目の波ということがあるので、十分に留意をされて委員会を進めてほしいと求めました。どのようなものが生み出されるのか、そして地域センターとしてどのように変わっていくのか、ビジョンがあったら説明を求めました。","respondent":"川島地域活動課長","answer":"何よりも新しい建物、それから区民集会所も新しくなりますので、快適にお使いいただけると考えています。引き続き、地域に根差した地域事務も行いまして、より一層地域の皆様に愛される地域センターを目指しまして、全力で開設準備を進めているところです。","id":"exchange-187"},{"speaker":"大沢委員","kind":"質問・要望","question":"今おっしゃった武蔵小山駅から１分、５分ということで、区境の方からも今後は来やすくなってくる。新しい地域センターづくりに努めてほしいと求めましたけれども、もう一度、決意のほど。","respondent":"川島地域活動課長","answer":"地域の皆様にも大変期待されている、新しいところに移るという新荏原第一地域センターですので、ご期待に沿えますように、しっかり準備を進めてまいりたいと考えています。","id":"exchange-188"},{"speaker":"若林委員","kind":"質問・要望","question":"ずっと１節から、多分これは２８節、その成果・効果についてお聞きしたいと思います。民間公共喫煙所の設置と、現在９か所ありますけれども、指定喫煙所との関係性はどのようになっていくのかというのもお聞きしておきたいと思います。","respondent":"品川財政課長、佐藤企画調整課長、黛生活安全担当課長","answer":"今回１０％のマイナスシーリングという形で、各予算担当職員に、非常に浸透させることができたのではないかと考えています。… 事業評価につながる実施計画の作成については、まず新型コロナウイルス感染症の収束を一定待ちたいと考えています。何点か項目がありますので… 設置費用については、年間１２０万円を上限に３分の２を５年間補助することで、今検討を進めているところです。他区におきましても、港区をはじめ…","id":"exchange-189"},{"speaker":"若林委員","kind":"意見","question":"時間がない中、すみませんでした。それから東口の高架下は、決してそういう環境をつくらない、それまでは閉鎖をするという考え方でお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-190"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そのときにＪＲ東日本の方に伺ったのが、１日何人を想定されているのですかと。まず最初に何点か伺ったのだけれども、そういうこともやっていらっしゃると思っているのだけれども、この辺の見解を教えていただきたい。","respondent":"古巻文化観光課長","answer":"集客という観点からのご質問だと認識をいたしておりますけれども、観光事業において、大事な指標の一つであると認識をしております。閲覧数はどれぐらいを見込むという目標値を立てて、そういったことを効果測定しながら次の事業につなげていく形で…","id":"exchange-191"},{"speaker":"石田（秀）委員","kind":"提案","question":"どうしてこの話をするかというと、考え方の話ですから、文庫の森もある。私はこういう所管というか、課をぜひつくっていただきたいと思うのだけれども、その点についてのお考えをお知らせくださいとの意見を述べました。","respondent":"佐藤企画調整課長","answer":"長期基本計画にも、まちの魅力を活かした都市型観光の推進ということで明確に掲げて、積極的に推進していくという考えに変わりはございません。今後、全庁的な連携も企画部が中心となって、集客・観光の視点を持った施策の推進について取り組んでいきたいと思います。","id":"exchange-192"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/309623?Template=document&Id=1130#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2021-01-01&TermEnd=2021-12-31"}],"sourceMeta":{"pages":0,"characters":125029,"voices":443}}]);
